    maturity_map = {'month_3': '3M', 'month_6': '6M', 'year_1': '1Y', 'year_2': '2Y', 'year_3': '3Y', 'year_4': '4Y', 'year_5': '5Y', 'year_6': '6Y', 'year_7': '7Y', 'year_8': '8Y', 'year_9': '9Y', 'year_10': '10Y', 'year_11': '11Y', 'year_12': '12Y', 'year_13': '13Y', 'year_14': '14Y', 'year_15': '15Y', 'year_16': '16Y', 'year_17': '17Y', 'year_18': '18Y', 'year_19': '19Y', 'year_20': '20Y', 'year_21': '21Y', 'year_22': '22Y', 'year_23': '23Y', 'year_24': '24Y', 'year_25': '25Y', 'year_26': '26Y', 'year_27': '27Y', 'year_28': '28Y', 'year_29': '29Y', 'year_30': '30Y'}
