class EIADataFetcher:
    """Fault-tolerant EIA data fetcher"""

    def __init__(self, api_key: Optional[str]=None):
        self.api_key = api_key
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': USER_AGENTS[0], 'Accept': 'application/json,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'Accept-Language': 'en-US,en;q=0.5', 'Accept-Encoding': 'gzip, deflate', 'Connection': 'keep-alive'})

    def _get_random_user_agent(self) -> str:
        """Get a random user agent"""
        import random
        return random.choice(USER_AGENTS)

    def _make_request(self, url: str, timeout: int=60) -> Optional[Union[Dict, bytes]]:
        """Make HTTP request with error handling"""
        try:
            self.session.headers['User-Agent'] = self._get_random_user_agent()
            response = self.session.get(url, timeout=timeout)
            response.raise_for_status()
            content_type = response.headers.get('content-type', '').lower()
            if 'application/json' in content_type:
                return response.json()
            elif 'excel' in content_type or 'spreadsheet' in content_type:
                return response.content
            else:
                return response.content
        except requests.exceptions.RequestException as e:
            raise EIAError(f'HTTP request failed for {url}: {str(e)}')
        except Exception as e:
            raise EIAError(f'Unexpected error fetching {url}: {str(e)}')

    def _parse_petroleum_excel(self, excel_data: bytes, category: str, tables: List[str]) -> List[Dict]:
        """Parse petroleum status report Excel data"""
        try:
            xls = pd.ExcelFile(BytesIO(excel_data))
            sheet_names = xls.sheet_names
            results = []
            for sheet_name in sheet_names:
                df = pd.read_excel(xls, sheet_name=sheet_name)
                if df.empty or len(df) < 2:
                    continue
                date_col = None
                for col in df.columns:
                    if any((keyword in str(col).lower() for keyword in ['date', 'week', 'period'])):
                        date_col = col
                        break
                if date_col is None:
                    date_col = df.columns[0]
                df[date_col] = pd.to_datetime(df[date_col], errors='coerce')
                df = df.dropna(subset=[date_col])
                df[date_col] = df[date_col].dt.date
                id_vars = [date_col]
                value_vars = [col for col in df.columns if col != date_col]
                if len(value_vars) > 0:
                    melted_df = df.melt(id_vars=id_vars, value_vars=value_vars, var_name='symbol', value_name='value')
                    melted_df = melted_df.dropna(subset=['value'])
                    for _, row in melted_df.iterrows():
                        results.append({'date': row[date_col].strftime('%Y-%m-%d'), 'category': category, 'table': sheet_name, 'symbol': str(row['symbol']), 'value': float(row['value']) if pd.notna(row['value']) else None, 'source': 'petroleum_status_report'})
            return results
        except Exception as e:
            raise EIAError(f'Error parsing petroleum Excel data for {category}: {str(e)}')

    def _parse_steo_data(self, api_data: Dict, table: str) -> List[Dict]:
        """Parse STEO API data"""
        try:
            results = []
            data = api_data.get('response', {}).get('data', [])
            for item in data:
                results.append({'date': item.get('period', ''), 'symbol': item.get('seriesId', ''), 'title': item.get('seriesDescription', ''), 'value': item.get('value', None), 'units': item.get('unitsofmeasure', ''), 'table': f'STEO-{table}: {STEO_TABLE_NAMES.get(table, table)}', 'source': 'short_term_energy_outlook'})
            return results
        except Exception as e:
            raise EIAError(f'Error parsing STEO data for table {table}: {str(e)}')

    def get_petroleum_status_report(self, category: str='balance_sheet', tables: Optional[List[str]]=None, start_date: Optional[str]=None, end_date: Optional[str]=None, use_cache: bool=True) -> Dict[str, Any]:
        """Get petroleum status report data"""
        try:
            if category not in WPSR_CATEGORY_CHOICES:
                raise EIAError(f'Invalid category: {category}. Valid choices: {WPSR_CATEGORY_CHOICES}')
            url = WPSR_FILE_MAP.get(category)
            if not url:
                raise EIAError(f'No URL found for category: {category}')
            excel_data = self._make_request(url)
            if not excel_data:
                raise EIAError(f'No data received from {url}')
            if not tables:
                tables = ['all']
            results = self._parse_petroleum_excel(excel_data, category, tables)
            if start_date:
                start_date_obj = datetime.strptime(start_date, '%Y-%m-%d').date()
                results = [r for r in results if datetime.strptime(r['date'], '%Y-%m-%d').date() >= start_date_obj]
            if end_date:
                end_date_obj = datetime.strptime(end_date, '%Y-%m-%d').date()
                results = [r for r in results if datetime.strptime(r['date'], '%Y-%m-%d').date() <= end_date_obj]
            return {'success': True, 'category': category, 'tables': tables, 'data': results, 'count': len(results), 'url': url}
        except EIAError:
            raise
        except Exception as e:
            return {'success': False, 'error': f'Error fetching petroleum status report: {str(e)}', 'category': category}

    def get_short_term_energy_outlook(self, table: str='01', symbols: Optional[List[str]]=None, frequency: Literal['month', 'quarter', 'annual']='month', start_date: Optional[str]=None, end_date: Optional[str]=None) -> Dict[str, Any]:
        """Get short term energy outlook data"""
        try:
            if not self.api_key:
                raise EIAError('API key required for STEO data')
            if table not in STEO_TABLE_NAMES:
                raise EIAError(f'Invalid table: {table}. Valid choices: {list(STEO_TABLE_NAMES.keys())}')
            if not symbols:
                symbols = STEO_SYMBOLS_MAP.get(table, [])
            if not symbols:
                raise EIAError(f'No symbols available for table: {table}')
            frequency_map = {'month': 'monthly', 'quarter': 'quarterly', 'annual': 'annual'}
            base_url = f'{BASE_API_URL}steo/data/?api_key={self.api_key}&frequency={frequency_map[frequency]}&data[0]=value'
            results = []
            for i in range(0, len(symbols), 10):
                symbol_chunk = symbols[i:i + 10]
                url_symbols = ''
                for symbol in symbol_chunk:
                    url_symbols += f'&facets[seriesId][]={symbol}'
                if start_date:
                    if frequency == 'monthly':
                        url_date = f'&start={datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y-%m')}'
                    elif frequency == 'quarterly':
                        quarter = (datetime.strptime(start_date, '%Y-%m-%d').month - 1) // 3 + 1
                        url_date = f'&start={datetime.strptime(start_date, '%Y-%m-%d').year}-Q{quarter}'
                    else:
                        url_date = f'&start={datetime.strptime(start_date, '%Y-%m-%d').year}'
                    url_symbols += url_date
                if end_date:
                    if frequency == 'monthly':
                        url_date = f'&end={datetime.strptime(end_date, '%Y-%m-%d').strftime('%Y-%m')}'
                    elif frequency == 'quarterly':
                        quarter = (datetime.strptime(end_date, '%Y-%m-%d').month - 1) // 3 + 1
                        url_date = f'&end={datetime.strptime(end_date, '%Y-%m-%d').year}-Q{quarter}'
                    else:
                        url_date = f'&end={datetime.strptime(end_date, '%Y-%m-%d').year}'
                    url_symbols += url_date
                url = f'{base_url}{url_symbols}&offset=0&length=5000'
                api_data = self._make_request(url)
                if api_data and isinstance(api_data, dict):
                    chunk_results = self._parse_steo_data(api_data, table)
                    results.extend(chunk_results)
            results.sort(key=lambda x: x['date'])
            return {'success': True, 'table': table, 'table_name': STEO_TABLE_NAMES[table], 'frequency': frequency, 'symbols': symbols, 'data': results, 'count': len(results)}
        except EIAError:
            raise
        except Exception as e:
            return {'success': False, 'error': f'Error fetching STEO data: {str(e)}', 'table': table}

    def get_available_categories(self) -> Dict[str, Any]:
        """Get available petroleum status report categories"""
        return {'success': True, 'categories': WPSR_CATEGORY_CHOICES, 'total_categories': len(WPSR_CATEGORY_CHOICES), 'file_urls': WPSR_FILE_MAP}

    def get_available_steo_tables(self) -> Dict[str, Any]:
        """Get available STEO tables"""
        return {'success': True, 'tables': STEO_TABLE_NAMES, 'symbols_map': STEO_SYMBOLS_MAP, 'total_tables': len(STEO_TABLE_NAMES)}

    def get_energy_overview(self, limit: Optional[int]=None) -> Dict[str, Any]:
        """Get comprehensive energy overview"""
        results = []
        errors = []
        try:
            petroleum_data = self.get_petroleum_status_report('balance_sheet', ['stocks', 'supply'])
            results.append(('petroleum_balance', petroleum_data))
        except Exception as e:
            errors.append(('petroleum_balance', str(e)))
        if self.api_key:
            try:
                steo_data = self.get_short_term_energy_outlook('01', frequency='month')
                results.append(('energy_markets_summary', steo_data))
            except Exception as e:
                errors.append(('energy_markets_summary', str(e)))
            try:
                natural_gas_data = self.get_short_term_energy_outlook('05a', frequency='month')
                results.append(('natural_gas', natural_gas_data))
            except Exception as e:
                errors.append(('natural_gas', str(e)))
        return {'success': len(results) > 0, 'results': results, 'errors': errors, 'total_requests': len(results) + len(errors), 'successful_fetches': len(results), 'failed_fetches': len(errors)}

def __init__(self, api_key: Optional[str]=None):
    self.api_key = api_key
    self.session = requests.Session()
    self.session.headers.update({'User-Agent': USER_AGENTS[0], 'Accept': 'application/json,application/vnd.ms-excel,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet', 'Accept-Language': 'en-US,en;q=0.5', 'Accept-Encoding': 'gzip, deflate', 'Connection': 'keep-alive'})

def _make_request(self, url: str, timeout: int=60) -> Optional[Union[Dict, bytes]]:
    """Make HTTP request with error handling"""
    try:
        self.session.headers['User-Agent'] = self._get_random_user_agent()
        response = self.session.get(url, timeout=timeout)
        response.raise_for_status()
        content_type = response.headers.get('content-type', '').lower()
        if 'application/json' in content_type:
            return response.json()
        elif 'excel' in content_type or 'spreadsheet' in content_type:
            return response.content
        else:
            return response.content
    except requests.exceptions.RequestException as e:
        raise EIAError(f'HTTP request failed for {url}: {str(e)}')
    except Exception as e:
        raise EIAError(f'Unexpected error fetching {url}: {str(e)}')

def _parse_petroleum_excel(self, excel_data: bytes, category: str, tables: List[str]) -> List[Dict]:
    """Parse petroleum status report Excel data"""
    try:
        xls = pd.ExcelFile(BytesIO(excel_data))
        sheet_names = xls.sheet_names
        results = []
        for sheet_name in sheet_names:
            df = pd.read_excel(xls, sheet_name=sheet_name)
            if df.empty or len(df) < 2:
                continue
            date_col = None
            for col in df.columns:
                if any((keyword in str(col).lower() for keyword in ['date', 'week', 'period'])):
                    date_col = col
                    break
            if date_col is None:
                date_col = df.columns[0]
            df[date_col] = pd.to_datetime(df[date_col], errors='coerce')
            df = df.dropna(subset=[date_col])
            df[date_col] = df[date_col].dt.date
            id_vars = [date_col]
            value_vars = [col for col in df.columns if col != date_col]
            if len(value_vars) > 0:
                melted_df = df.melt(id_vars=id_vars, value_vars=value_vars, var_name='symbol', value_name='value')
                melted_df = melted_df.dropna(subset=['value'])
                for _, row in melted_df.iterrows():
                    results.append({'date': row[date_col].strftime('%Y-%m-%d'), 'category': category, 'table': sheet_name, 'symbol': str(row['symbol']), 'value': float(row['value']) if pd.notna(row['value']) else None, 'source': 'petroleum_status_report'})
        return results
    except Exception as e:
        raise EIAError(f'Error parsing petroleum Excel data for {category}: {str(e)}')

def _parse_steo_data(self, api_data: Dict, table: str) -> List[Dict]:
    """Parse STEO API data"""
    try:
        results = []
        data = api_data.get('response', {}).get('data', [])
        for item in data:
            results.append({'date': item.get('period', ''), 'symbol': item.get('seriesId', ''), 'title': item.get('seriesDescription', ''), 'value': item.get('value', None), 'units': item.get('unitsofmeasure', ''), 'table': f'STEO-{table}: {STEO_TABLE_NAMES.get(table, table)}', 'source': 'short_term_energy_outlook'})
        return results
    except Exception as e:
        raise EIAError(f'Error parsing STEO data for table {table}: {str(e)}')

def get_petroleum_status_report(self, category: str='balance_sheet', tables: Optional[List[str]]=None, start_date: Optional[str]=None, end_date: Optional[str]=None, use_cache: bool=True) -> Dict[str, Any]:
    """Get petroleum status report data"""
    try:
        if category not in WPSR_CATEGORY_CHOICES:
            raise EIAError(f'Invalid category: {category}. Valid choices: {WPSR_CATEGORY_CHOICES}')
        url = WPSR_FILE_MAP.get(category)
        if not url:
            raise EIAError(f'No URL found for category: {category}')
        excel_data = self._make_request(url)
        if not excel_data:
            raise EIAError(f'No data received from {url}')
        if not tables:
            tables = ['all']
        results = self._parse_petroleum_excel(excel_data, category, tables)
        if start_date:
            start_date_obj = datetime.strptime(start_date, '%Y-%m-%d').date()
            results = [r for r in results if datetime.strptime(r['date'], '%Y-%m-%d').date() >= start_date_obj]
        if end_date:
            end_date_obj = datetime.strptime(end_date, '%Y-%m-%d').date()
            results = [r for r in results if datetime.strptime(r['date'], '%Y-%m-%d').date() <= end_date_obj]
        return {'success': True, 'category': category, 'tables': tables, 'data': results, 'count': len(results), 'url': url}
    except EIAError:
        raise
    except Exception as e:
        return {'success': False, 'error': f'Error fetching petroleum status report: {str(e)}', 'category': category}

class BLSDataAPI:
    """BLS Data API wrapper for modular data fetching"""

    def __init__(self, api_key: Optional[str]=None):
        self.api_key = api_key or os.getenv('BLS_API_KEY')
        self.session = requests.Session()
        self.session.headers.update({'User-Agent': 'Fincept-Terminal/1.0', 'Content-Type': 'application/json'})
        self._cache_timeout = 24 * 60 * 60
        self._cache = {}

    def _is_cache_valid(self, cache_key: str) -> bool:
        """Check if cached data is still valid"""
        if cache_key not in self._cache:
            return False
        cached_time = self._cache[cache_key].get('timestamp', 0)
        current_time = datetime.now().timestamp()
        return current_time - cached_time < self._cache_timeout

    def _get_cached_data(self, cache_key: str) -> Optional[pd.DataFrame]:
        """Get cached data if valid"""
        if self._is_cache_valid(cache_key):
            return self._cache[cache_key].get('data')
        return None

    def _set_cache_data(self, cache_key: str, data: pd.DataFrame) -> None:
        """Set cached data with timestamp"""
        self._cache[cache_key] = {'data': data, 'timestamp': datetime.now().timestamp()}

    async def _make_async_request(self, url: str, method: str='GET', headers: Optional[Dict]=None, data: Optional[str]=None) -> Dict[str, Any]:
        """Make async HTTP request with error handling"""
        try:
            async with aiohttp.ClientSession(headers=headers) as session:
                if method.upper() == 'GET':
                    async with session.get(url) as response:
                        if response.status == 200:
                            result = await response.json()
                            return {'success': True, 'data': result}
                        else:
                            return BLSError(url, f'HTTP {response.status}: {await response.text()}', response.status).to_dict()
                elif method.upper() == 'POST':
                    async with session.post(url, data=data) as response:
                        if response.status == 200:
                            result = await response.json()
                            return {'success': True, 'data': result}
                        else:
                            return BLSError(url, f'HTTP {response.status}: {await response.text()}', response.status).to_dict()
        except aiohttp.ClientError as e:
            return BLSError(url, f'Network error: {str(e)}').to_dict()
        except json.JSONDecodeError as e:
            return BLSError(url, f'JSON decode error: {str(e)}').to_dict()
        except Exception as e:
            return BLSError(url, f'Unexpected error: {str(e)}').to_dict()

    def _make_request(self, url: str, method: str='GET', headers: Optional[Dict]=None, data: Optional[str]=None) -> Dict[str, Any]:
        """Make HTTP request with error handling"""
        try:
            if method.upper() == 'GET':
                response = self.session.get(url, headers=headers, timeout=30)
            elif method.upper() == 'POST':
                response = self.session.post(url, headers=headers, data=data, timeout=30)
            else:
                return BLSError(url, f'Unsupported method: {method}').to_dict()
            if response.status_code == 200:
                try:
                    data = response.json()
                    return {'success': True, 'data': data}
                except json.JSONDecodeError:
                    return BLSError(url, 'Invalid JSON response', response.status_code).to_dict()
            else:
                return BLSError(url, f'HTTP {response.status_code}: {response.text}', response.status_code).to_dict()
        except requests.exceptions.RequestException as e:
            return BLSError(url, f'Network error: {str(e)}', getattr(e.response, 'status_code', None)).to_dict()
        except Exception as e:
            return BLSError(url, f'Unexpected error: {str(e)}').to_dict()

    def _parse_ftp_data(self, content: str) -> pd.DataFrame:
        """Parse tab-delimited FTP data"""
        try:
            df = pd.read_csv(StringIO(content), sep='\t', low_memory=False, dtype='object')
            df.columns = [col.strip() for col in df.columns]
            df = df.apply(lambda x: x.str.strip() if x.dtype == 'object' else x)
            df = df.replace({"''": None, '""': None, 'nan': None, '': None})
            df = df.dropna(how='all', axis=1)
            return df
        except Exception as e:
            raise ValueError(f'Failed to parse FTP data: {str(e)}')

    async def get_bls_timeseries(self, series_ids: Union[str, List[str]], start_year: Optional[int]=None, end_year: Optional[int]=None, calculations: bool=True, catalog: bool=True, annual_average: bool=False, aspects: bool=False) -> Dict[str, Any]:
        """Get BLS timeseries data with API request chunking"""
        if not self.api_key:
            return BLSError('bls_timeseries', 'BLS API key required. Get one at: https://data.bls.gov/registrationEngine/').to_dict()
        symbols = series_ids.split(',') if isinstance(series_ids, str) else series_ids
        if len(symbols) > 50:
            symbols = symbols[:50]
        current_year = datetime.now().year
        if not start_year:
            start_year = current_year - 3
        if not end_year:
            end_year = current_year
        payload = {'seriesid': symbols, 'startyear': start_year, 'endyear': end_year, 'catalog': catalog, 'calculations': calculations, 'annualaverage': annual_average, 'aspects': aspects, 'registrationkey': self.api_key}
        payload = {k: v for k, v in payload.items() if v}
        headers = {'Content-Type': 'application/json'}
        payload_json = json.dumps(payload)
        result = await self._make_async_request(BLS_API_URL, 'POST', headers, payload_json)
        if 'error' in result:
            return result
        bls_data = result.get('data', {})
        if not bls_data or 'Results' not in bls_data:
            return BLSError('bls_timeseries', 'Invalid BLS response format').to_dict()
        results = bls_data.get('Results', {})
        series_data = results.get('series', [])
        messages = bls_data.get('message', [])
        processed_data = []
        metadata = {}
        for series in series_data:
            series_id = series.get('seriesID')
            if not series_id:
                continue
            catalog_info = series.get('catalog')
            if catalog_info:
                metadata[series_id] = catalog_info
            data_points = series.get('data', [])
            for point in data_points:
                year = point.get('year', '')
                period = point.get('period', '').replace('M', '')
                if period.startswith('A') or period in ('S01', 'Q01'):
                    date_str = f'{year}-01-01'
                elif period == 'S02':
                    date_str = f'{year}-07-01'
                elif period in ('S03', 'Q05'):
                    date_str = f'{year}-12-31'
                    period = '13'
                elif period == 'Q02':
                    date_str = f'{year}-04-01'
                elif period == 'Q03':
                    date_str = f'{year}-07-01'
                elif period == 'Q04':
                    date_str = f'{year}-10-01'
                else:
                    date_str = f'{year}-{period.zfill(2)}-01'
                value = point.get('value')
                if value and value != '-':
                    try:
                        numeric_value = float(value)
                    except ValueError:
                        numeric_value = None
                else:
                    numeric_value = None
                record = {'symbol': series_id, 'date': date_str, 'value': numeric_value, 'latest': point.get('latest') == 'true'}
                if catalog_info and 'series_title' in catalog_info:
                    title = catalog_info['series_title']
                    if period == '13':
                        title += ' (Annual Average)'
                    record['title'] = title
                footnotes = point.get('footnotes', [])
                if footnotes:
                    footnote_text = '; '.join([f.get('text', str(f)) if isinstance(f, dict) else str(f) for f in footnotes if f])
                    if footnote_text.strip():
                        record['footnotes'] = footnote_text
                calculations_data = point.get('calculations', {})
                if calculations_data:
                    net_changes = calculations_data.get('net_changes', {})
                    record.update({'change_1M': float(net_changes.get('1')) if net_changes.get('1') else None, 'change_3M': float(net_changes.get('3')) if net_changes.get('3') else None, 'change_6M': float(net_changes.get('6')) if net_changes.get('6') else None, 'change_12M': float(net_changes.get('12')) if net_changes.get('12') else None})
                    pct_changes = calculations_data.get('pct_changes', {})
                    record.update({'change_percent_1M': float(pct_changes.get('1')) / 100 if pct_changes.get('1') else None, 'change_percent_3M': float(pct_changes.get('3')) / 100 if pct_changes.get('3') else None, 'change_percent_6M': float(pct_changes.get('6')) / 100 if pct_changes.get('6') else None, 'change_percent_12M': float(pct_changes.get('12')) / 100 if pct_changes.get('12') else None})
                processed_data.append(record)
        if not processed_data:
            error_msg = '; '.join(messages) if messages else 'No data found'
            return BLSError('bls_timeseries', error_msg).to_dict()
        return {'success': True, 'data': {'series_data': processed_data, 'metadata': metadata, 'messages': messages}}

    def search_bls_series(self, query: str, category: str='cpi', include_extras: bool=False, include_code_map: bool=False) -> Dict[str, Any]:
        """Search for BLS series by category and query"""
        try:
            if category not in SURVEY_CATEGORIES:
                available_categories = ', '.join(SURVEY_CATEGORY_NAMES.keys())
                return BLSError('bls_search', f'Invalid category. Available: {available_categories}').to_dict()
            cache_key = f'{category}_series'
            series_df = self._get_cached_data(cache_key)
            if series_df is None:
                series_df = self._get_local_category_data(category)
                if series_df is None:
                    return BLSError('bls_search', f"Series data for category '{category}' not available locally").to_dict()
                self._set_cache_data(cache_key, series_df)
            if series_df.empty:
                return BLSError('bls_search', f"No series data found for category '{category}'").to_dict()
            if not query.strip():
                results_df = series_df
            else:
                search_terms = [term.strip() for term in query.split(';')]
                combined_mask = pd.Series([True] * len(series_df))
                for term in search_terms:
                    term_mask = series_df.apply(lambda row, term=term: row.astype(str).str.contains(term, case=False, regex=False, na=False)).any(axis=1)
                    combined_mask &= term_mask
                results_df = series_df[combined_mask]
            if results_df.empty:
                return BLSError('bls_search', f"No results found for query: '{query}' in category '{category}'").to_dict()
            if include_extras:
                results = results_df.to_dict('records')
            else:
                essential_cols = ['series_id', 'series_title', 'survey_name']
                available_cols = [col for col in essential_cols if col in results_df.columns]
                results = results_df[available_cols].to_dict('records')
            metadata = {}
            if include_code_map:
                metadata = self._get_local_code_map(category)
            return {'success': True, 'data': {'query': query, 'category': category, 'results': results, 'metadata': metadata if metadata else None}}
        except Exception as e:
            return BLSError('bls_search', str(e)).to_dict()

    def _get_local_category_data(self, category: str) -> Optional[pd.DataFrame]:
        """Get category series data from local cache (simplified version)"""
        if category == 'cpi':
            data = [{'series_id': 'CPIAUCSL', 'series_title': 'Consumer Price Index for All Urban Consumers: All Items', 'survey_name': 'Consumer Price Index - All Urban Consumers'}, {'series_id': 'CPIAUCNS', 'series_title': 'Consumer Price Index for All Urban Consumers: All Items (NSA)', 'survey_name': 'Consumer Price Index - All Urban Consumers'}, {'series_id': 'CUSR0000SA0', 'series_title': 'Consumer Price Index for All Urban Consumers: All Items (Seasonally Adjusted)', 'survey_name': 'Consumer Price Index - All Urban Consumers'}]
        elif category == 'employment':
            data = [{'series_id': 'UNRATE', 'series_title': 'Unemployment Rate', 'survey_name': 'Current Population Survey'}, {'series_id': 'PAYEMS', 'series_title': 'All Employees: Total Nonfarm Payrolls', 'survey_name': 'Current Employment Statistics survey (National)'}, {'series_id': 'LNS14000000', 'series_title': 'Unemployment Rate', 'survey_name': 'Labor Force Statistics from the Current Population Survey'}]
        else:
            return None
        return pd.DataFrame(data)

    def _get_local_code_map(self, category: str) -> Dict:
        """Get code map for category (simplified version)"""
        return {}

    async def get_series_data(self, series_ids: Union[str, List[str]], start_date: Optional[str]=None, end_date: Optional[str]=None, calculations: bool=True, annual_average: bool=False, aspects: bool=False) -> Dict[str, Any]:
        """Get time series data for specific series IDs"""
        try:
            start_year = None
            end_year = None
            if start_date:
                try:
                    start_dt = datetime.strptime(start_date, '%Y-%m-%d')
                    start_year = start_dt.year
                except ValueError:
                    return BLSError('get_series_data', f'Invalid start_date format: {start_date}. Use YYYY-MM-DD').to_dict()
            if end_date:
                try:
                    end_dt = datetime.strptime(end_date, '%Y-%m-%d')
                    end_year = end_dt.year
                except ValueError:
                    return BLSError('get_series_data', f'Invalid end_date format: {end_date}. Use YYYY-MM-DD').to_dict()
            return await self.get_bls_timeseries(series_ids=series_ids, start_year=start_year, end_year=end_year, calculations=calculations, catalog=True, annual_average=annual_average, aspects=aspects)
        except Exception as e:
            return BLSError('get_series_data', str(e)).to_dict()

    async def get_popular_series(self) -> Dict[str, Any]:
        """Get data for popular economic series"""
        try:
            popular_series_ids = list(POPULAR_SERIES.keys())
            result = await self.get_bls_timeseries(series_ids=popular_series_ids, start_year=datetime.now().year - 2, calculations=True, catalog=True)
            if 'error' in result:
                return result
            data = result.get('data', {})
            series_data = data.get('series_data', [])
            for record in series_data:
                series_id = record.get('symbol')
                if series_id in POPULAR_SERIES:
                    record['description'] = POPULAR_SERIES[series_id]
            return {'success': True, 'data': {'popular_series': series_data, 'available_series': POPULAR_SERIES}}
        except Exception as e:
            return BLSError('get_popular_series', str(e)).to_dict()

