class ML4TFramework:
    """Main orchestrator for the ML4T framework"""

    def __init__(self, config: ML4TConfig=None):
        self.config = config or ML4TConfig()
        self.logger = ML4TLogger('ML4TFramework')
        self.data_manager = DataManager(self.config)
        self.alpha_engine = AlphaFactorEngine(self.config)
        self.portfolio_optimizer = PortfolioOptimizer(self.config)
        self.backtest_engine = BacktestEngine(self.config)
        self.visualizer = ML4TVisualizer(self.config)
        self.data = {}
        self.factors = {}
        self.models = {}
        self.strategies = {}
        self.results = {}

    def load_data(self, symbols: List[str], start_date: str, end_date: str, include_fundamental: bool=True, include_alternative: bool=True):
        """Load all required data"""
        self.logger.info('Loading market data...')
        self.data['market'] = self.data_manager.load_market_data(symbols, start_date, end_date)
        if include_fundamental:
            self.logger.info('Loading fundamental data...')
            self.data['fundamental'] = self.data_manager.load_fundamental_data(symbols)
        if include_alternative:
            self.logger.info('Loading alternative data...')
            self.data['alternative'] = {'sentiment': self.data_manager.load_alternative_data('sentiment'), 'social': self.data_manager.load_alternative_data('social')}

    def engineer_features(self, symbols: List[str]):
        """Generate comprehensive feature set"""
        self.logger.info('Engineering features...')
        all_features = []
        for symbol in symbols:
            technical_data = self.alpha_engine.calculate_technical_factors(self.data['market'], symbol)
            if 'fundamental' in self.data:
                fundamental_data = self.alpha_engine.calculate_fundamental_factors(technical_data, self.data['fundamental'])
            else:
                fundamental_data = technical_data
            if 'alternative' in self.data:
                final_data = self.alpha_engine.calculate_alternative_factors(fundamental_data, self.data['alternative'])
            else:
                final_data = fundamental_data
            all_features.append(final_data)
        self.factors['engineered'] = pd.concat(all_features, ignore_index=True)
        self.factors['engineered'] = self.factors['engineered'].sort_values(['symbol', 'date'])
        self.factors['engineered']['future_returns'] = self.factors['engineered'].groupby('symbol')['returns'].shift(-1)
        self.factors['engineered'] = self.factors['engineered'].dropna(subset=['future_returns'])
        return self.factors['engineered']

    def train_models(self, feature_data: pd.DataFrame, models_config: List[Dict]):
        """Train multiple ML models"""
        self.logger.info('Training models...')
        feature_columns = [col for col in feature_data.columns if col not in ['date', 'symbol', 'future_returns', 'open', 'high', 'low', 'close', 'volume']]
        X = feature_data[feature_columns].fillna(0)
        y = feature_data['future_returns'].fillna(0)
        for model_config in models_config:
            model_name = model_config['name']
            model_type = model_config['type']
            model_params = model_config.get('params', {})
            self.logger.info(f'Training {model_name} ({model_type})...')
            if model_type in ['linear', 'ridge', 'lasso', 'logistic']:
                model = LinearModel(self.config, model_type, **model_params)
            elif model_type in ['random_forest', 'gradient_boosting']:
                model = TreeBasedModel(self.config, model_type, **model_params)
            elif model_type in ['arima']:
                model = TimeSeriesModel(self.config, model_type, **model_params)
            else:
                self.logger.warning(f'Unknown model type: {model_type}')
                continue
            model.fit(X, y)
            self.models[model_name] = model
            self.logger.info(f'Model {model_name} trained successfully')

    def create_strategies(self, strategy_configs: List[Dict]):
        """Create trading strategies"""
        self.logger.info('Creating strategies...')
        for strategy_config in strategy_configs:
            strategy_name = strategy_config['name']
            strategy_type = strategy_config['type']
            strategy_params = strategy_config.get('params', {})
            if strategy_type == 'mean_reversion':
                strategy = MeanReversionStrategy(self.config, **strategy_params)
            elif strategy_type == 'momentum':
                strategy = MomentumStrategy(self.config, **strategy_params)
            elif strategy_type == 'ml_strategy':
                model_name = strategy_params.get('model_name')
                if model_name in self.models:
                    features = strategy_params.get('features', [])
                    strategy = MLStrategy(self.config, self.models[model_name], features)
                else:
                    self.logger.warning(f'Model {model_name} not found for ML strategy')
                    continue
            else:
                self.logger.warning(f'Unknown strategy type: {strategy_type}')
                continue
            self.strategies[strategy_name] = strategy
            self.logger.info(f'Strategy {strategy_name} created successfully')

    def run_backtests(self):
        """Run backtests for all strategies"""
        self.logger.info('Running backtests...')
        for strategy_name, strategy in self.strategies.items():
            self.logger.info(f'Backtesting strategy: {strategy_name}')
            signals = strategy.generate_signals(self.factors['engineered'])
            backtest_results = self.backtest_engine.run_backtest(signals, self.data['market'], self.config.initial_capital)
            self.results[strategy_name] = backtest_results
            metrics = backtest_results['metrics']
            self.logger.info(f'Strategy {strategy_name} - Sharpe: {metrics['sharpe_ratio']:.3f}, Return: {metrics['annualized_return']:.3f}, MaxDD: {metrics['max_drawdown']:.3f}')

    def generate_report(self):
        """Generate comprehensive performance report"""
        self.logger.info('Generating performance report...')
        summary_data = []
        for strategy_name, results in self.results.items():
            metrics = results['metrics']
            summary_data.append({'Strategy': strategy_name, 'Total Return': f'{metrics['total_return']:.2%}', 'Annualized Return': f'{metrics['annualized_return']:.2%}', 'Volatility': f'{metrics['annualized_volatility']:.2%}', 'Sharpe Ratio': f'{metrics['sharpe_ratio']:.3f}', 'Max Drawdown': f'{metrics['max_drawdown']:.2%}', 'Calmar Ratio': f'{metrics['calmar_ratio']:.3f}'})
        summary_df = pd.DataFrame(summary_data)
        print('\n' + '=' * 80)
        print('ML4T FRAMEWORK - PERFORMANCE SUMMARY')
        print('=' * 80)
        print(summary_df.to_string(index=False))
        print('=' * 80)
        return summary_df

    def visualize_results(self, strategy_name: str=None):
        """Create visualizations for results"""
        if strategy_name is None:
            for name in self.results.keys():
                self.visualizer.plot_portfolio_performance(self.results[name])
        elif strategy_name in self.results:
            self.visualizer.plot_portfolio_performance(self.results[strategy_name])
        else:
            self.logger.warning(f'Strategy {strategy_name} not found in results')

def create_strategies(self, strategy_configs: List[Dict]):
    """Create trading strategies"""
    self.logger.info('Creating strategies...')
    for strategy_config in strategy_configs:
        strategy_name = strategy_config['name']
        strategy_type = strategy_config['type']
        strategy_params = strategy_config.get('params', {})
        if strategy_type == 'mean_reversion':
            strategy = MeanReversionStrategy(self.config, **strategy_params)
        elif strategy_type == 'momentum':
            strategy = MomentumStrategy(self.config, **strategy_params)
        elif strategy_type == 'ml_strategy':
            model_name = strategy_params.get('model_name')
            if model_name in self.models:
                features = strategy_params.get('features', [])
                strategy = MLStrategy(self.config, self.models[model_name], features)
            else:
                self.logger.warning(f'Model {model_name} not found for ML strategy')
                continue
        else:
            self.logger.warning(f'Unknown strategy type: {strategy_type}')
            continue
        self.strategies[strategy_name] = strategy
        self.logger.info(f'Strategy {strategy_name} created successfully')

class FinancialCalculations:
    """Common financial calculation utilities"""

    @staticmethod
    def time_value_of_money(principal: float, rate: float, periods: int, compounding: str='annual') -> Dict[str, float]:
        """Comprehensive time value of money calculations"""
        compounding_freq = {'annual': 1, 'semi-annual': 2, 'quarterly': 4, 'monthly': 12, 'daily': 365, 'continuous': float('inf')}
        freq = compounding_freq.get(compounding.lower(), 1)
        if freq == float('inf'):
            future_value = principal * math.exp(rate * periods)
            effective_rate = math.exp(rate) - 1
        else:
            future_value = principal * (1 + rate / freq) ** (freq * periods)
            effective_rate = (1 + rate / freq) ** freq - 1
        present_value = future_value / (1 + effective_rate) ** periods
        return {'principal': principal, 'future_value': future_value, 'present_value_of_fv': present_value, 'effective_annual_rate': effective_rate, 'total_interest': future_value - principal, 'compounding_frequency': freq}

    @staticmethod
    def annuity_calculations(payment: float, rate: float, periods: int, annuity_type: str='ordinary') -> Dict[str, float]:
        """Calculate present and future value of annuities"""
        if rate <= 0:
            pv_annuity = payment * periods
            fv_annuity = payment * periods
        else:
            pv_ordinary = payment * ((1 - (1 + rate) ** (-periods)) / rate)
            fv_ordinary = payment * (((1 + rate) ** periods - 1) / rate)
            if annuity_type.lower() == 'due':
                pv_annuity = pv_ordinary * (1 + rate)
                fv_annuity = fv_ordinary * (1 + rate)
            else:
                pv_annuity = pv_ordinary
                fv_annuity = fv_ordinary
        return {'payment_amount': payment, 'present_value': pv_annuity, 'future_value': fv_annuity, 'total_payments': payment * periods, 'total_interest': fv_annuity - payment * periods, 'annuity_type': annuity_type}

    @staticmethod
    def perpetuity_value(payment: float, discount_rate: float, growth_rate: float=0) -> Dict[str, float]:
        """Calculate present value of perpetuity"""
        if discount_rate <= growth_rate:
            raise ValidationError('Discount rate must be greater than growth rate')
        if growth_rate == 0:
            pv = payment / discount_rate
        else:
            pv = payment / (discount_rate - growth_rate)
        return {'payment': payment, 'discount_rate': discount_rate, 'growth_rate': growth_rate, 'present_value': pv, 'perpetuity_type': 'Growing' if growth_rate > 0 else 'Simple'}

    @staticmethod
    def loan_calculations(principal: float, annual_rate: float, years: int, payment_frequency: int=12) -> Dict[str, Any]:
        """Calculate loan payments and amortization"""
        monthly_rate = annual_rate / payment_frequency
        total_payments = years * payment_frequency
        if annual_rate == 0:
            payment = principal / total_payments
        else:
            payment = principal * (monthly_rate * (1 + monthly_rate) ** total_payments) / ((1 + monthly_rate) ** total_payments - 1)
        balance = principal
        schedule = []
        total_interest = 0
        for i in range(1, int(total_payments) + 1):
            interest_payment = balance * monthly_rate
            principal_payment = payment - interest_payment
            balance -= principal_payment
            total_interest += interest_payment
            schedule.append({'payment_number': i, 'payment': payment, 'principal': principal_payment, 'interest': interest_payment, 'balance': max(0, balance)})
        return {'loan_amount': principal, 'monthly_payment': payment, 'total_payments': total_payments, 'total_interest': total_interest, 'total_cost': principal + total_interest, 'amortization_schedule': schedule[:12], 'full_schedule_available': True}

    @staticmethod
    def bond_calculations(face_value: float, coupon_rate: float, market_rate: float, years_to_maturity: float, frequency: int=2) -> Dict[str, float]:
        """Calculate bond price, yield, and duration"""
        periods = years_to_maturity * frequency
        coupon_payment = face_value * coupon_rate / frequency
        period_rate = market_rate / frequency
        if market_rate == 0:
            bond_price = face_value + coupon_payment * periods
        else:
            pv_coupons = coupon_payment * ((1 - (1 + period_rate) ** (-periods)) / period_rate)
            pv_face = face_value / (1 + period_rate) ** periods
            bond_price = pv_coupons + pv_face
        current_yield = coupon_payment * frequency / bond_price
        cash_flows = [coupon_payment] * int(periods)
        cash_flows[-1] += face_value
        weighted_time = 0
        total_pv = 0
        for t, cf in enumerate(cash_flows, 1):
            pv_cf = cf / (1 + period_rate) ** t
            weighted_time += t / frequency * pv_cf
            total_pv += pv_cf
        macaulay_duration = weighted_time / total_pv
        modified_duration = macaulay_duration / (1 + market_rate / frequency)
        return {'bond_price': bond_price, 'face_value': face_value, 'coupon_rate': coupon_rate, 'market_rate': market_rate, 'current_yield': current_yield, 'macaulay_duration': macaulay_duration, 'modified_duration': modified_duration, 'price_sensitivity': modified_duration * bond_price * 0.01, 'premium_discount': 'Premium' if bond_price > face_value else 'Discount' if bond_price < face_value else 'Par'}

@staticmethod
def annuity_calculations(payment: float, rate: float, periods: int, annuity_type: str='ordinary') -> Dict[str, float]:
    """Calculate present and future value of annuities"""
    if rate <= 0:
        pv_annuity = payment * periods
        fv_annuity = payment * periods
    else:
        pv_ordinary = payment * ((1 - (1 + rate) ** (-periods)) / rate)
        fv_ordinary = payment * (((1 + rate) ** periods - 1) / rate)
        if annuity_type.lower() == 'due':
            pv_annuity = pv_ordinary * (1 + rate)
            fv_annuity = fv_ordinary * (1 + rate)
        else:
            pv_annuity = pv_ordinary
            fv_annuity = fv_ordinary
    return {'payment_amount': payment, 'present_value': pv_annuity, 'future_value': fv_annuity, 'total_payments': payment * periods, 'total_interest': fv_annuity - payment * periods, 'annuity_type': annuity_type}

class BaseAnalyticalModel(ABC):
    """Abstract base class for all analytical models"""

    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description
        self.last_calculation = None
        self.assumptions = {}

    @abstractmethod
    def validate_inputs(self, **kwargs) -> bool:
        """Validate input parameters for the model"""
        pass

    @abstractmethod
    def calculate(self, **kwargs) -> ValuationResult:
        """Perform the main calculation"""
        pass

    def get_assumptions(self) -> Dict[str, Any]:
        """Return current model assumptions"""
        return self.assumptions.copy()

    def set_assumptions(self, **kwargs):
        """Set model assumptions"""
        self.assumptions.update(kwargs)

def set_assumptions(self, **kwargs):
    """Set model assumptions"""
    self.assumptions.update(kwargs)

def validate_all_inputs(valuation_method: ValuationMethod, **kwargs) -> bool:
    """Master validation function for all models"""
    if valuation_method in [ValuationMethod.DDM_GORDON, ValuationMethod.DDM_TWO_STAGE, ValuationMethod.DDM_THREE_STAGE, ValuationMethod.DDM_H_MODEL]:
        return DDMValidator.validate_gordon_growth_inputs(kwargs.get('dividend', 0), kwargs.get('growth_rate', 0), kwargs.get('required_return', 0))
    elif valuation_method in [ValuationMethod.DCF_FCFF, ValuationMethod.DCF_FCFE]:
        return DCFValidator.validate_fcf_inputs(kwargs.get('cash_flows', []), kwargs.get('discount_rate', 0), kwargs.get('terminal_value'))
    elif valuation_method in [ValuationMethod.MULTIPLES_PE, ValuationMethod.MULTIPLES_PB, ValuationMethod.MULTIPLES_PS, ValuationMethod.MULTIPLES_EV_EBITDA]:
        return MultiplesValidator.validate_multiple_values(kwargs.get('multiples', {}))
    elif valuation_method == ValuationMethod.RESIDUAL_INCOME:
        return ResidualIncomeValidator.validate_ri_inputs(kwargs.get('net_income', 0), kwargs.get('book_value', 0), kwargs.get('required_return', 0), kwargs.get('roe', 0))
    return True

class AlphaVantageProvider(DataProvider):
    """Alpha Vantage data provider implementation"""

    def __init__(self, api_key: str):
        self.name = 'Alpha Vantage'
        self.api_key = api_key
        self.base_url = 'https://www.alphavantage.co/query'

    def _make_request(self, params: Dict[str, str]) -> Dict[str, Any]:
        """Make API request to Alpha Vantage"""
        params['apikey'] = self.api_key
        response = requests.get(self.base_url, params=params)
        response.raise_for_status()
        return response.json()

    def get_company_data(self, symbol: str) -> CompanyData:
        """Retrieve company data from Alpha Vantage"""
        try:
            overview_params = {'function': 'OVERVIEW', 'symbol': symbol}
            overview = self._make_request(overview_params)
            quote_params = {'function': 'GLOBAL_QUOTE', 'symbol': symbol}
            quote_data = self._make_request(quote_params)
            quote = quote_data.get('Global Quote', {})
            current_price = float(quote.get('05. price', 0))
            shares_outstanding = float(overview.get('SharesOutstanding', 0))
            financial_data = {'revenue': float(overview.get('RevenueTTM', 0)), 'net_income': float(overview.get('ProfitMargin', 0)) * float(overview.get('RevenueTTM', 0)), 'total_assets': 0, 'book_value': float(overview.get('BookValue', 0)), 'earnings_per_share': float(overview.get('EPS', 0)), 'dividend_per_share': float(overview.get('DividendPerShare', 0)), 'roe': float(overview.get('ReturnOnEquityTTM', 0)), 'profit_margin': float(overview.get('ProfitMargin', 0)), 'ebitda': float(overview.get('EBITDA', 0))}
            market_data = {'beta': float(overview.get('Beta', 1.0)), 'pe_ratio': float(overview.get('PERatio', 0)), 'pb_ratio': float(overview.get('PriceToBookRatio', 0)), 'peg_ratio': float(overview.get('PEGRatio', 0)), 'dividend_yield': float(overview.get('DividendYield', 0)), '52_week_high': float(overview.get('52WeekHigh', 0)), '52_week_low': float(overview.get('52WeekLow', 0))}
            return CompanyData(symbol=symbol.upper(), name=overview.get('Name', symbol), sector=overview.get('Sector', 'Unknown'), industry=overview.get('Industry', 'Unknown'), market_cap=float(overview.get('MarketCapitalization', 0)), shares_outstanding=shares_outstanding, current_price=current_price, financial_data=financial_data, market_data=market_data, last_updated=datetime.now())
        except Exception as e:
            raise DataProviderError(f'Failed to retrieve company data for {symbol}: {str(e)}')

    def get_market_data(self, symbol: str) -> MarketData:
        """Retrieve market data from Alpha Vantage"""
        try:
            overview_params = {'function': 'OVERVIEW', 'symbol': symbol}
            overview = self._make_request(overview_params)
            return MarketData(risk_free_rate=0.05, market_return=0.1, beta=float(overview.get('Beta', 1.0)), dividend_yield=float(overview.get('DividendYield', 0)), growth_rate=0.03, required_return=0.08)
        except Exception as e:
            raise DataProviderError(f'Failed to retrieve market data for {symbol}: {str(e)}')

    def get_financial_statements(self, symbol: str, period: str='annual') -> Dict[str, pd.DataFrame]:
        """Retrieve financial statements from Alpha Vantage"""
        try:
            statements = {}
            income_params = {'function': 'INCOME_STATEMENT', 'symbol': symbol}
            income_data = self._make_request(income_params)
            if period == 'annual':
                statements['income_statement'] = pd.DataFrame(income_data.get('annualReports', []))
            else:
                statements['income_statement'] = pd.DataFrame(income_data.get('quarterlyReports', []))
            balance_params = {'function': 'BALANCE_SHEET', 'symbol': symbol}
            balance_data = self._make_request(balance_params)
            if period == 'annual':
                statements['balance_sheet'] = pd.DataFrame(balance_data.get('annualReports', []))
            else:
                statements['balance_sheet'] = pd.DataFrame(balance_data.get('quarterlyReports', []))
            cashflow_params = {'function': 'CASH_FLOW', 'symbol': symbol}
            cashflow_data = self._make_request(cashflow_params)
            if period == 'annual':
                statements['cash_flow_statement'] = pd.DataFrame(cashflow_data.get('annualReports', []))
            else:
                statements['cash_flow_statement'] = pd.DataFrame(cashflow_data.get('quarterlyReports', []))
            return statements
        except Exception as e:
            raise DataProviderError(f'Failed to retrieve financial statements for {symbol}: {str(e)}')

    def get_price_data(self, symbol: str, start_date: str, end_date: str) -> pd.DataFrame:
        """Retrieve historical price data from Alpha Vantage"""
        try:
            params = {'function': 'TIME_SERIES_DAILY_ADJUSTED', 'symbol': symbol, 'outputsize': 'full'}
            data = self._make_request(params)
            time_series = data.get('Time Series (Daily)', {})
            df = pd.DataFrame.from_dict(time_series, orient='index')
            df.index = pd.to_datetime(df.index)
            df = df.sort_index()
            df.columns = ['Open', 'High', 'Low', 'Close', 'Adj Close', 'Volume', 'Dividend', 'Split']
            df = df.astype(float)
            mask = (df.index >= start_date) & (df.index <= end_date)
            return df.loc[mask]
        except Exception as e:
            raise DataProviderError(f'Failed to retrieve price data for {symbol}: {str(e)}')

def _make_request(self, params: Dict[str, str]) -> Dict[str, Any]:
    """Make API request to Alpha Vantage"""
    params['apikey'] = self.api_key
    response = requests.get(self.base_url, params=params)
    response.raise_for_status()
    return response.json()

class DiscountPremiumAnalyzer:
    """Analyze discounts and premiums for private company valuations"""

    def __init__(self):
        self.typical_ranges = {'marketability_discount': (0.2, 0.4), 'control_premium': (0.2, 0.35), 'minority_discount': (0.1, 0.25), 'key_person_discount': (0.05, 0.2), 'size_discount': (0.05, 0.15)}

    def calculate_marketability_discount(self, company_characteristics: Dict[str, Any]) -> Dict[str, float]:
        """Calculate discount for lack of marketability (DLOM)"""
        base_discount = 0.25
        adjustments = 0
        profitability = company_characteristics.get('profitability', 'Average')
        if profitability == 'Strong':
            adjustments -= 0.05
        elif profitability == 'Weak':
            adjustments += 0.1
        revenue = company_characteristics.get('revenue', 0)
        if revenue > 100000000:
            adjustments -= 0.05
        elif revenue < 10000000:
            adjustments += 0.05
        reporting_quality = company_characteristics.get('financial_reporting_quality', 'Compiled')
        if reporting_quality == 'Audited':
            adjustments -= 0.05
        elif reporting_quality == 'Compiled':
            adjustments += 0.05
        growth_prospects = company_characteristics.get('growth_prospects', 'Average')
        if growth_prospects == 'High':
            adjustments -= 0.05
        elif growth_prospects == 'Low':
            adjustments += 0.05
        management_quality = company_characteristics.get('management_quality', 'Average')
        if management_quality == 'Strong':
            adjustments -= 0.03
        elif management_quality == 'Weak':
            adjustments += 0.07
        final_discount = max(0.1, min(0.5, base_discount + adjustments))
        return {'base_discount': base_discount, 'total_adjustments': adjustments, 'final_marketability_discount': final_discount, 'discount_range': self.typical_ranges['marketability_discount']}

    def calculate_control_premium(self, ownership_percentage: float, control_characteristics: Dict[str, Any]) -> Dict[str, float]:
        """Calculate control premium or minority discount"""
        if ownership_percentage >= 0.5:
            base_premium = 0.25
            adjustments = 0
            if ownership_percentage >= 0.75:
                adjustments += 0.05
            elif ownership_percentage < 0.6:
                adjustments -= 0.05
            synergy_potential = control_characteristics.get('synergy_potential', 'Medium')
            if synergy_potential == 'High':
                adjustments += 0.1
            elif synergy_potential == 'Low':
                adjustments -= 0.05
            strategic_value = control_characteristics.get('strategic_value', 'Medium')
            if strategic_value == 'High':
                adjustments += 0.05
            final_premium = max(0.1, min(0.5, base_premium + adjustments))
            return {'control_premium': final_premium, 'ownership_percentage': ownership_percentage, 'control_level': 'Control', 'adjustments': adjustments}
        else:
            base_discount = 0.15
            adjustments = 0
            voting_rights = control_characteristics.get('voting_rights', 'Proportional')
            if voting_rights == 'Enhanced':
                adjustments -= 0.05
            elif voting_rights == 'Limited':
                adjustments += 0.05
            liquidity_provisions = control_characteristics.get('liquidity_provisions', False)
            if liquidity_provisions:
                adjustments -= 0.03
            tag_along_rights = control_characteristics.get('tag_along_rights', False)
            if tag_along_rights:
                adjustments -= 0.02
            final_discount = max(0.05, min(0.3, base_discount + adjustments))
            return {'minority_discount': final_discount, 'ownership_percentage': ownership_percentage, 'control_level': 'Minority', 'adjustments': adjustments}

    def calculate_key_person_discount(self, key_person_characteristics: Dict[str, Any]) -> Dict[str, float]:
        """Calculate discount for key person dependency"""
        dependency_level = key_person_characteristics.get('dependency_level', 'Medium')
        base_discounts = {'High': 0.15, 'Medium': 0.08, 'Low': 0.03}
        base_discount = base_discounts.get(dependency_level, 0.08)
        adjustments = 0
        age = key_person_characteristics.get('age', 50)
        if age > 65:
            adjustments += 0.05
        elif age < 40:
            adjustments -= 0.02
        succession_plan = key_person_characteristics.get('succession_plan', False)
        if succession_plan:
            adjustments -= 0.05
        else:
            adjustments += 0.03
        employment_contract = key_person_characteristics.get('employment_contract', False)
        if employment_contract:
            adjustments -= 0.02
        non_compete = key_person_characteristics.get('non_compete', False)
        if non_compete:
            adjustments -= 0.02
        final_discount = max(0, min(0.25, base_discount + adjustments))
        return {'base_discount': base_discount, 'adjustments': adjustments, 'final_key_person_discount': final_discount, 'dependency_level': dependency_level}

    def calculate_size_discount(self, company_size_metrics: Dict[str, float]) -> Dict[str, float]:
        """Calculate size-related discount"""
        revenue = company_size_metrics.get('revenue', 0)
        assets = company_size_metrics.get('total_assets', 0)
        employees = company_size_metrics.get('employee_count', 0)
        if revenue > 1000000000:
            size_discount = 0.02
        elif revenue > 100000000:
            size_discount = 0.05
        elif revenue > 25000000:
            size_discount = 0.08
        elif revenue > 5000000:
            size_discount = 0.12
        else:
            size_discount = 0.15
        return {'size_discount': size_discount, 'revenue': revenue, 'size_category': self.categorize_company_size(revenue)}

    def categorize_company_size(self, revenue: float) -> str:
        """Categorize company by size"""
        if revenue > 1000000000:
            return 'Large'
        elif revenue > 100000000:
            return 'Medium-Large'
        elif revenue > 25000000:
            return 'Medium'
        elif revenue > 5000000:
            return 'Small-Medium'
        else:
            return 'Small'

    def apply_all_discounts_premiums(self, base_value: float, discount_premium_factors: Dict[str, float]) -> Dict[str, float]:
        """Apply multiple discounts and premiums to base value"""
        adjusted_value = base_value
        cumulative_adjustment = 0
        if 'control_premium' in discount_premium_factors:
            control_premium = discount_premium_factors['control_premium']
            adjusted_value *= 1 + control_premium
            cumulative_adjustment += control_premium
        elif 'minority_discount' in discount_premium_factors:
            minority_discount = discount_premium_factors['minority_discount']
            adjusted_value *= 1 - minority_discount
            cumulative_adjustment -= minority_discount
        if 'marketability_discount' in discount_premium_factors:
            marketability_discount = discount_premium_factors['marketability_discount']
            adjusted_value *= 1 - marketability_discount
            cumulative_adjustment -= marketability_discount
        if 'key_person_discount' in discount_premium_factors:
            key_person_discount = discount_premium_factors['key_person_discount']
            adjusted_value *= 1 - key_person_discount
            cumulative_adjustment -= key_person_discount
        if 'size_discount' in discount_premium_factors:
            size_discount = discount_premium_factors['size_discount']
            adjusted_value *= 1 - size_discount
            cumulative_adjustment -= size_discount
        return {'base_value': base_value, 'adjusted_value': adjusted_value, 'total_adjustment_percentage': cumulative_adjustment, 'individual_adjustments': discount_premium_factors}

def calculate_size_discount(self, company_size_metrics: Dict[str, float]) -> Dict[str, float]:
    """Calculate size-related discount"""
    revenue = company_size_metrics.get('revenue', 0)
    assets = company_size_metrics.get('total_assets', 0)
    employees = company_size_metrics.get('employee_count', 0)
    if revenue > 1000000000:
        size_discount = 0.02
    elif revenue > 100000000:
        size_discount = 0.05
    elif revenue > 25000000:
        size_discount = 0.08
    elif revenue > 5000000:
        size_discount = 0.12
    else:
        size_discount = 0.15
    return {'size_discount': size_discount, 'revenue': revenue, 'size_category': self.categorize_company_size(revenue)}

class PrivateCompanyValuator:
    """Comprehensive private company valuation framework"""

    def __init__(self):
        self.normalizer = PrivateCompanyNormalizer()
        self.income_valuator = IncomeApproachValuator()
        self.market_valuator = MarketApproachValuator()
        self.asset_valuator = AssetApproachValuator()
        self.discount_analyzer = DiscountPremiumAnalyzer()

    def comprehensive_valuation(self, private_company: PrivateCompanyData, valuation_inputs: Dict[str, Any]) -> Dict[str, Any]:
        """Perform comprehensive private company valuation"""
        earnings_adjustments = valuation_inputs.get('earnings_adjustments', {})
        normalized_earnings = self.normalizer.normalize_earnings(private_company.net_income, earnings_adjustments)
        income_valuations = self.perform_income_approach_valuations(private_company, normalized_earnings, valuation_inputs)
        market_valuations = self.perform_market_approach_valuations(private_company, valuation_inputs)
        asset_valuations = self.perform_asset_approach_valuations(private_company, valuation_inputs)
        discounts_premiums = self.calculate_discounts_premiums(private_company, valuation_inputs)
        final_valuation = self.synthesize_valuation_results(income_valuations, market_valuations, asset_valuations, discounts_premiums)
        return {'normalized_earnings': normalized_earnings, 'income_approach': income_valuations, 'market_approach': market_valuations, 'asset_approach': asset_valuations, 'discounts_premiums': discounts_premiums, 'final_valuation': final_valuation, 'valuation_summary': self.generate_valuation_summary(final_valuation)}

    def perform_income_approach_valuations(self, company: PrivateCompanyData, normalized_earnings: Dict[str, float], inputs: Dict[str, Any]) -> Dict[str, Any]:
        """Perform all income approach valuations"""
        income_valuations = {}
        cap_rate = inputs.get('capitalization_rate', 0.2)
        growth_rate = inputs.get('growth_rate', 0.03)
        try:
            cap_earnings_value = self.income_valuator.calculate_capitalized_earnings_value(normalized_earnings['normalized_earnings'], cap_rate, growth_rate)
            income_valuations['capitalized_earnings'] = {'value': cap_earnings_value, 'method': 'Capitalized Earnings', 'cap_rate': cap_rate, 'growth_rate': growth_rate}
        except Exception as e:
            income_valuations['capitalized_earnings'] = {'error': str(e)}
        if 'projected_cash_flows' in inputs:
            discount_rate = inputs.get('discount_rate', 0.15)
            terminal_growth = inputs.get('terminal_growth', 0.03)
            try:
                dcf_value = self.income_valuator.calculate_dcf_value(inputs['projected_cash_flows'], discount_rate, None, terminal_growth)
                income_valuations['dcf'] = {**dcf_value, 'method': 'Discounted Cash Flow', 'discount_rate': discount_rate, 'terminal_growth': terminal_growth}
            except Exception as e:
                income_valuations['dcf'] = {'error': str(e)}
        if 'tangible_assets' in inputs:
            tangible_assets = inputs['tangible_assets']
            asset_return_rate = inputs.get('asset_return_rate', 0.08)
            intangible_return_rate = inputs.get('intangible_return_rate', 0.15)
            try:
                excess_earnings_value = self.income_valuator.calculate_excess_earnings_value(normalized_earnings['normalized_earnings'], tangible_assets, asset_return_rate, intangible_return_rate)
                income_valuations['excess_earnings'] = {**excess_earnings_value, 'method': 'Excess Earnings'}
            except Exception as e:
                income_valuations['excess_earnings'] = {'error': str(e)}
        return income_valuations

    def perform_market_approach_valuations(self, company: PrivateCompanyData, inputs: Dict[str, Any]) -> Dict[str, Any]:
        """Perform market approach valuations"""
        market_valuations = {}
        company_metrics = {'revenue': company.annual_revenue, 'ebitda': company.ebitda, 'net_income': company.net_income}
        if 'public_comparables' in inputs:
            control_premium = inputs.get('control_premium', 0)
            try:
                gpc_value = self.market_valuator.calculate_guideline_public_company_value(company_metrics, inputs['public_comparables'], control_premium)
                market_valuations['guideline_public_companies'] = {**gpc_value, 'method': 'Guideline Public Companies'}
            except Exception as e:
                market_valuations['guideline_public_companies'] = {'error': str(e)}
        if 'transaction_comparables' in inputs:
            try:
                transaction_value = self.market_valuator.calculate_guideline_transaction_value(company_metrics, inputs['transaction_comparables'])
                market_valuations['guideline_transactions'] = {**transaction_value, 'method': 'Guideline Transactions'}
            except Exception as e:
                market_valuations['guideline_transactions'] = {'error': str(e)}
        return market_valuations

    def perform_asset_approach_valuations(self, company: PrivateCompanyData, inputs: Dict[str, Any]) -> Dict[str, Any]:
        """Perform asset approach valuations"""
        asset_valuations = {}
        if 'asset_fair_values' in inputs:
            book_values = {'current_assets': company.total_assets * 0.4, 'fixed_assets': company.total_assets * 0.6}
            try:
                adjusted_bv = self.asset_valuator.calculate_adjusted_book_value(book_values, inputs['asset_fair_values'])
                asset_valuations['adjusted_book_value'] = {**adjusted_bv, 'method': 'Adjusted Book Value'}
            except Exception as e:
                asset_valuations['adjusted_book_value'] = {'error': str(e)}
        if 'asset_categories' in inputs:
            try:
                replacement_cost = self.asset_valuator.calculate_replacement_cost_value(inputs['asset_categories'])
                asset_valuations['replacement_cost'] = {**replacement_cost, 'method': 'Replacement Cost'}
            except Exception as e:
                asset_valuations['replacement_cost'] = {'error': str(e)}
        if 'liquidation_assumptions' in inputs:
            assets = {'total_assets': company.total_assets}
            liquidation_discounts = inputs['liquidation_assumptions'].get('discounts', {})
            liquidation_costs = inputs['liquidation_assumptions'].get('costs', 0)
            try:
                liquidation_value = self.asset_valuator.calculate_liquidation_value(assets, liquidation_discounts, liquidation_costs)
                asset_valuations['liquidation_value'] = {**liquidation_value, 'method': 'Liquidation Value'}
            except Exception as e:
                asset_valuations['liquidation_value'] = {'error': str(e)}
        return asset_valuations

    def calculate_discounts_premiums(self, company: PrivateCompanyData, inputs: Dict[str, Any]) -> Dict[str, Any]:
        """Calculate all applicable discounts and premiums"""
        discounts_premiums = {}
        characteristics = {'revenue': company.annual_revenue, 'profitability': self.assess_profitability_level(company), 'financial_reporting_quality': company.financial_reporting_quality, 'growth_prospects': inputs.get('growth_prospects', 'Average'), 'management_quality': company.management_quality}
        marketability_discount = self.discount_analyzer.calculate_marketability_discount(characteristics)
        discounts_premiums['marketability'] = marketability_discount
        ownership_percentage = inputs.get('ownership_percentage', 1.0)
        control_characteristics = inputs.get('control_characteristics', {})
        control_analysis = self.discount_analyzer.calculate_control_premium(ownership_percentage, control_characteristics)
        discounts_premiums['control'] = control_analysis
        key_person_chars = {'dependency_level': company.key_person_dependency, 'age': inputs.get('key_person_age', 50), 'succession_plan': inputs.get('succession_plan', False), 'employment_contract': inputs.get('employment_contract', False), 'non_compete': inputs.get('non_compete', False)}
        key_person_discount = self.discount_analyzer.calculate_key_person_discount(key_person_chars)
        discounts_premiums['key_person'] = key_person_discount
        size_metrics = {'revenue': company.annual_revenue, 'total_assets': company.total_assets, 'employee_count': company.employee_count}
        size_discount = self.discount_analyzer.calculate_size_discount(size_metrics)
        discounts_premiums['size'] = size_discount
        return discounts_premiums

    def assess_profitability_level(self, company: PrivateCompanyData) -> str:
        """Assess company profitability level"""
        if company.annual_revenue == 0:
            return 'Weak'
        ebitda_margin = company.ebitda / company.annual_revenue
        net_margin = company.net_income / company.annual_revenue
        if ebitda_margin > 0.2 and net_margin > 0.1:
            return 'Strong'
        elif ebitda_margin > 0.1 and net_margin > 0.05:
            return 'Average'
        else:
            return 'Weak'

    def synthesize_valuation_results(self, income_results: Dict, market_results: Dict, asset_results: Dict, discounts_premiums: Dict) -> Dict[str, Any]:
        """Synthesize results from all valuation approaches"""
        valuation_indications = []
        method_weights = {}
        for method, result in income_results.items():
            if 'error' not in result:
                if method == 'capitalized_earnings':
                    value = result['value']
                    weight = 0.4
                elif method == 'dcf':
                    value = result['enterprise_value']
                    weight = 0.4
                elif method == 'excess_earnings':
                    value = result['total_business_value']
                    weight = 0.3
                else:
                    continue
                valuation_indications.append(value)
                method_weights[f'income_{method}'] = weight
        for method, result in market_results.items():
            if 'error' not in result and 'indicated_values' in result:
                indicated_values = list(result['indicated_values'].values())
                if indicated_values:
                    value = np.median(indicated_values)
                    weight = 0.5
                    valuation_indications.append(value)
                    method_weights[f'market_{method}'] = weight
        for method, result in asset_results.items():
            if 'error' not in result:
                if method == 'adjusted_book_value':
                    value = result['adjusted_book_value']
                    weight = 0.2
                elif method == 'replacement_cost':
                    value = result['total_replacement_cost']
                    weight = 0.2
                elif method == 'liquidation_value':
                    value = result['net_liquidation_value']
                    weight = 0.1
                else:
                    continue
                valuation_indications.append(value)
                method_weights[f'asset_{method}'] = weight
        if len(valuation_indications) > 1:
            weights = list(method_weights.values())
            total_weight = sum(weights)
            normalized_weights = [w / total_weight for w in weights]
            weighted_value = sum((v * w for v, w in zip(valuation_indications, normalized_weights)))
            simple_average = np.mean(valuation_indications)
            median_value = np.median(valuation_indications)
        else:
            weighted_value = valuation_indications[0] if valuation_indications else 0
            simple_average = weighted_value
            median_value = weighted_value
        base_value = weighted_value
        dp_factors = {}
        if 'control' in discounts_premiums:
            control_result = discounts_premiums['control']
            if 'control_premium' in control_result:
                dp_factors['control_premium'] = control_result['control_premium']
            elif 'minority_discount' in control_result:
                dp_factors['minority_discount'] = control_result['minority_discount']
        if 'marketability' in discounts_premiums:
            dp_factors['marketability_discount'] = discounts_premiums['marketability']['final_marketability_discount']
        if 'key_person' in discounts_premiums:
            dp_factors['key_person_discount'] = discounts_premiums['key_person']['final_key_person_discount']
        if 'size' in discounts_premiums:
            dp_factors['size_discount'] = discounts_premiums['size']['size_discount']
        final_adjustment = self.discount_analyzer.apply_all_discounts_premiums(base_value, dp_factors)
        return {'valuation_indications': valuation_indications, 'method_weights': method_weights, 'base_valuation': {'weighted_average': weighted_value, 'simple_average': simple_average, 'median': median_value}, 'discount_premium_analysis': final_adjustment, 'final_valuation_range': {'low': final_adjustment['adjusted_value'] * 0.85, 'mid': final_adjustment['adjusted_value'], 'high': final_adjustment['adjusted_value'] * 1.15}, 'valuation_methods_used': len(valuation_indications)}

    def generate_valuation_summary(self, final_valuation: Dict[str, Any]) -> Dict[str, Any]:
        """Generate executive summary of valuation"""
        final_value = final_valuation['final_valuation_range']['mid']
        base_value = final_valuation['base_valuation']['weighted_average']
        total_adjustment = final_valuation['discount_premium_analysis']['total_adjustment_percentage']
        summary = {'final_value': final_value, 'valuation_range': final_valuation['final_valuation_range'], 'base_value_before_adjustments': base_value, 'total_discount_premium_adjustment': total_adjustment, 'number_of_methods_used': final_valuation['valuation_methods_used'], 'primary_valuation_driver': self.identify_primary_driver(final_valuation), 'confidence_level': self.assess_confidence_level(final_valuation), 'key_assumptions': self.extract_key_assumptions(final_valuation)}
        return summary

    def identify_primary_driver(self, final_valuation: Dict[str, Any]) -> str:
        """Identify primary valuation driver"""
        method_weights = final_valuation['method_weights']
        if not method_weights:
            return 'No clear driver'
        max_weight_method = max(method_weights.items(), key=lambda x: x[1])[0]
        if 'income' in max_weight_method:
            return 'Income/Earnings Generation'
        elif 'market' in max_weight_method:
            return 'Market Comparables'
        elif 'asset' in max_weight_method:
            return 'Asset Values'
        else:
            return 'Multiple Factors'

    def assess_confidence_level(self, final_valuation: Dict[str, Any]) -> str:
        """Assess confidence level in valuation"""
        num_methods = final_valuation['valuation_methods_used']
        if num_methods >= 3:
            return 'High'
        elif num_methods == 2:
            return 'Medium'
        else:
            return 'Low'

    def extract_key_assumptions(self, final_valuation: Dict[str, Any]) -> List[str]:
        """Extract key valuation assumptions"""
        assumptions = ['Normalized earnings reflect sustainable performance', 'Market multiples are representative of subject company', 'Discount rates reflect appropriate risk levels']
        dp_analysis = final_valuation['discount_premium_analysis']
        individual_adjustments = dp_analysis['individual_adjustments']
        if 'marketability_discount' in individual_adjustments:
            assumptions.append('Marketability discount reflects lack of ready market')
        if 'control_premium' in individual_adjustments:
            assumptions.append('Control premium reflects strategic value')
        elif 'minority_discount' in individual_adjustments:
            assumptions.append('Minority discount reflects lack of control')
        if 'key_person_discount' in individual_adjustments:
            assumptions.append('Key person discount reflects dependency risk')
        return assumptions

def comprehensive_valuation(self, private_company: PrivateCompanyData, valuation_inputs: Dict[str, Any]) -> Dict[str, Any]:
    """Perform comprehensive private company valuation"""
    earnings_adjustments = valuation_inputs.get('earnings_adjustments', {})
    normalized_earnings = self.normalizer.normalize_earnings(private_company.net_income, earnings_adjustments)
    income_valuations = self.perform_income_approach_valuations(private_company, normalized_earnings, valuation_inputs)
    market_valuations = self.perform_market_approach_valuations(private_company, valuation_inputs)
    asset_valuations = self.perform_asset_approach_valuations(private_company, valuation_inputs)
    discounts_premiums = self.calculate_discounts_premiums(private_company, valuation_inputs)
    final_valuation = self.synthesize_valuation_results(income_valuations, market_valuations, asset_valuations, discounts_premiums)
    return {'normalized_earnings': normalized_earnings, 'income_approach': income_valuations, 'market_approach': market_valuations, 'asset_approach': asset_valuations, 'discounts_premiums': discounts_premiums, 'final_valuation': final_valuation, 'valuation_summary': self.generate_valuation_summary(final_valuation)}

def perform_market_approach_valuations(self, company: PrivateCompanyData, inputs: Dict[str, Any]) -> Dict[str, Any]:
    """Perform market approach valuations"""
    market_valuations = {}
    company_metrics = {'revenue': company.annual_revenue, 'ebitda': company.ebitda, 'net_income': company.net_income}
    if 'public_comparables' in inputs:
        control_premium = inputs.get('control_premium', 0)
        try:
            gpc_value = self.market_valuator.calculate_guideline_public_company_value(company_metrics, inputs['public_comparables'], control_premium)
            market_valuations['guideline_public_companies'] = {**gpc_value, 'method': 'Guideline Public Companies'}
        except Exception as e:
            market_valuations['guideline_public_companies'] = {'error': str(e)}
