class ResidualIncomeAnalyzer:
    """Comprehensive Residual Income analysis tools"""

    def __init__(self):
        self.ri_model = ResidualIncomeModel()
        self.eva_model = EconomicValueAddedModel()

    def calculate_implied_growth_rate(self, current_price: float, current_book_value_per_share: float, roe: float, required_return: float) -> float:
        """Calculate implied growth rate from current market P/B ratio"""
        pb_ratio = current_price / current_book_value_per_share
        if pb_ratio <= 1:
            raise ValidationError('P/B ratio must be greater than 1 for growth calculation')
        implied_growth = required_return - (roe - required_return) / (pb_ratio - 1)
        return implied_growth

    def calculate_fundamental_pb_ratio(self, roe: float, required_return: float, growth_rate: float) -> float:
        """Calculate justified P/B ratio from fundamentals"""
        if required_return <= growth_rate:
            raise ValidationError('Required return must be greater than growth rate')
        return 1 + (roe - required_return) / (required_return - growth_rate)

    def analyze_roe_sustainability(self, historical_roe: List[float], industry_avg_roe: float) -> Dict[str, Any]:
        """Analyze ROE sustainability and mean reversion"""
        if not historical_roe:
            raise ValidationError('Historical ROE data required')
        current_roe = historical_roe[-1]
        avg_roe = np.mean(historical_roe)
        roe_volatility = np.std(historical_roe) if len(historical_roe) > 1 else 0
        roe_trend = np.polyfit(range(len(historical_roe)), historical_roe, 1)[0]
        sustainability_score = 'HIGH'
        warnings = []
        if current_roe > 0.25:
            sustainability_score = 'LOW'
            warnings.append('ROE above 25% typically not sustainable long-term')
        if abs(current_roe - industry_avg_roe) > 0.1:
            warnings.append('ROE significantly different from industry average')
        if roe_volatility > 0.05:
            warnings.append('High ROE volatility indicates uncertainty')
        return {'current_roe': current_roe, 'average_roe': avg_roe, 'industry_avg_roe': industry_avg_roe, 'roe_volatility': roe_volatility, 'roe_trend': roe_trend, 'sustainability_score': sustainability_score, 'warnings': warnings}

    def forecast_residual_income(self, current_book_value: float, projected_roes: List[float], required_return: float, payout_ratios: List[float]=None) -> List[float]:
        """Forecast residual income based on ROE and growth assumptions"""
        if payout_ratios is None:
            payout_ratios = [0.4] * len(projected_roes)
        if len(payout_ratios) != len(projected_roes):
            raise ValidationError('Payout ratios and ROEs must have same length')
        projected_ris = []
        book_value = current_book_value
        for i, (roe, payout_ratio) in enumerate(zip(projected_roes, payout_ratios)):
            net_income = book_value * roe
            ri = self.ri_model.calculate_residual_income(net_income, book_value, required_return)
            projected_ris.append(ri)
            retention_ratio = 1 - payout_ratio
            book_value *= 1 + roe * retention_ratio
        return projected_ris

    def compare_ri_with_other_models(self, company_data: CompanyData, market_data: MarketData, ddm_value: float=None, dcf_value: float=None) -> Dict[str, Any]:
        """Compare RI valuation with DDM and DCF models"""
        ri_value = self.ri_model.calculate_intrinsic_value(company_data, market_data)
        comparison = {'ri_value': ri_value, 'current_price': company_data.current_price}
        if ddm_value:
            comparison['ddm_value'] = ddm_value
            comparison['ri_vs_ddm_diff'] = (ri_value - ddm_value) / ddm_value * 100
        if dcf_value:
            comparison['dcf_value'] = dcf_value
            comparison['ri_vs_dcf_diff'] = (ri_value - dcf_value) / dcf_value * 100
        book_value_per_share = company_data.financial_data.get('book_value', 0) * company_data.shares_outstanding / company_data.shares_outstanding
        comparison['book_value_per_share'] = book_value_per_share
        comparison['market_to_book'] = company_data.current_price / book_value_per_share
        comparison['ri_to_book'] = ri_value / book_value_per_share
        return comparison

    def accounting_quality_assessment(self, financial_statements: Dict[str, pd.DataFrame]) -> Dict[str, Any]:
        """Assess accounting quality for RI model reliability"""
        income_stmt = financial_statements.get('income_statement', pd.DataFrame())
        balance_sheet = financial_statements.get('balance_sheet', pd.DataFrame())
        quality_issues = []
        quality_score = 100
        if income_stmt.empty or balance_sheet.empty:
            return {'quality_score': 0, 'issues': ['Financial statements not available']}
        try:
            revenue_growth = income_stmt['revenue'].pct_change().iloc[-1] if 'revenue' in income_stmt.columns else 0
            receivables_growth = balance_sheet['accounts_receivable'].pct_change().iloc[-1] if 'accounts_receivable' in balance_sheet.columns else 0
            if abs(receivables_growth) > abs(revenue_growth) * 1.5:
                quality_issues.append('Receivables growing much faster than revenue')
                quality_score -= 20
            if 'inventory' in balance_sheet.columns and 'cost_of_goods_sold' in income_stmt.columns:
                inventory_turnover = income_stmt['cost_of_goods_sold'].iloc[-1] / balance_sheet['inventory'].iloc[-1]
                if inventory_turnover < 2:
                    quality_issues.append('Low inventory turnover may indicate obsolete inventory')
                    quality_score -= 15
            if 'goodwill' in balance_sheet.columns and 'total_assets' in balance_sheet.columns:
                goodwill_ratio = balance_sheet['goodwill'].iloc[-1] / balance_sheet['total_assets'].iloc[-1]
                if goodwill_ratio > 0.3:
                    quality_issues.append('High goodwill percentage increases impairment risk')
                    quality_score -= 10
            if 'total_debt' in balance_sheet.columns and 'total_equity' in balance_sheet.columns:
                debt_to_equity = balance_sheet['total_debt'].iloc[-1] / balance_sheet['total_equity'].iloc[-1]
                if debt_to_equity > 2:
                    quality_issues.append('High leverage may distort ROE calculations')
                    quality_score -= 10
        except Exception as e:
            quality_issues.append(f'Error in accounting quality assessment: {str(e)}')
            quality_score -= 30
        return {'quality_score': max(0, quality_score), 'issues': quality_issues, 'recommendations': ['Verify revenue recognition policies', 'Check for off-balance-sheet items', 'Analyze working capital components', 'Review goodwill and intangible assets']}

def compare_ri_with_other_models(self, company_data: CompanyData, market_data: MarketData, ddm_value: float=None, dcf_value: float=None) -> Dict[str, Any]:
    """Compare RI valuation with DDM and DCF models"""
    ri_value = self.ri_model.calculate_intrinsic_value(company_data, market_data)
    comparison = {'ri_value': ri_value, 'current_price': company_data.current_price}
    if ddm_value:
        comparison['ddm_value'] = ddm_value
        comparison['ri_vs_ddm_diff'] = (ri_value - ddm_value) / ddm_value * 100
    if dcf_value:
        comparison['dcf_value'] = dcf_value
        comparison['ri_vs_dcf_diff'] = (ri_value - dcf_value) / dcf_value * 100
    book_value_per_share = company_data.financial_data.get('book_value', 0) * company_data.shares_outstanding / company_data.shares_outstanding
    comparison['book_value_per_share'] = book_value_per_share
    comparison['market_to_book'] = company_data.current_price / book_value_per_share
    comparison['ri_to_book'] = ri_value / book_value_per_share
    return comparison

class IndexConstructor:
    """Index construction and management framework"""

    def __init__(self, name: str, weighting_method: IndexWeightingMethod):
        self.name = name
        self.weighting_method = weighting_method
        self.constituents = []
        self.base_value = 1000
        self.base_date = None
        self.divisor = 1.0

    def add_constituent(self, constituent: IndexConstituent):
        """Add a constituent to the index"""
        self.constituents.append(constituent)

    def remove_constituent(self, symbol: str):
        """Remove a constituent from the index"""
        self.constituents = [c for c in self.constituents if c.symbol != symbol]

    def calculate_weights(self) -> Dict[str, float]:
        """Calculate weights based on weighting methodology"""
        if not self.constituents:
            return {}
        weights = {}
        if self.weighting_method == IndexWeightingMethod.PRICE_WEIGHTED:
            total_price = sum((c.current_price for c in self.constituents))
            for constituent in self.constituents:
                weights[constituent.symbol] = constituent.current_price / total_price
        elif self.weighting_method == IndexWeightingMethod.MARKET_CAP_WEIGHTED:
            total_market_cap = sum((c.market_cap for c in self.constituents))
            for constituent in self.constituents:
                weights[constituent.symbol] = constituent.market_cap / total_market_cap
        elif self.weighting_method == IndexWeightingMethod.EQUAL_WEIGHTED:
            equal_weight = 1.0 / len(self.constituents)
            for constituent in self.constituents:
                weights[constituent.symbol] = equal_weight
        elif self.weighting_method == IndexWeightingMethod.FLOAT_ADJUSTED:
            total_float_cap = sum((c.float_shares * c.current_price for c in self.constituents))
            for constituent in self.constituents:
                float_cap = constituent.float_shares * constituent.current_price
                weights[constituent.symbol] = float_cap / total_float_cap
        elif self.weighting_method == IndexWeightingMethod.FUNDAMENTAL_WEIGHTED:
            total_fundamental = sum((c.market_cap for c in self.constituents))
            for constituent in self.constituents:
                weights[constituent.symbol] = constituent.market_cap / total_fundamental
        return weights

    def calculate_index_value(self, prices: Dict[str, float], base_prices: Dict[str, float]=None) -> float:
        """Calculate current index value"""
        if not self.constituents:
            return self.base_value
        if base_prices is None:
            base_prices = {c.symbol: c.current_price for c in self.constituents}
        if self.weighting_method == IndexWeightingMethod.PRICE_WEIGHTED:
            return self._calculate_price_weighted_value(prices, base_prices)
        elif self.weighting_method in [IndexWeightingMethod.MARKET_CAP_WEIGHTED, IndexWeightingMethod.FLOAT_ADJUSTED]:
            return self._calculate_cap_weighted_value(prices, base_prices)
        elif self.weighting_method == IndexWeightingMethod.EQUAL_WEIGHTED:
            return self._calculate_equal_weighted_value(prices, base_prices)
        else:
            return self._calculate_cap_weighted_value(prices, base_prices)

    def _calculate_price_weighted_value(self, prices: Dict[str, float], base_prices: Dict[str, float]) -> float:
        """Calculate price-weighted index value"""
        current_sum = sum((prices.get(c.symbol, c.current_price) for c in self.constituents))
        base_sum = sum((base_prices.get(c.symbol, c.current_price) for c in self.constituents))
        return self.base_value * (current_sum / base_sum) / self.divisor

    def _calculate_cap_weighted_value(self, prices: Dict[str, float], base_prices: Dict[str, float]) -> float:
        """Calculate market cap weighted index value"""
        current_cap = 0
        base_cap = 0
        for constituent in self.constituents:
            shares = constituent.float_shares if self.weighting_method == IndexWeightingMethod.FLOAT_ADJUSTED else constituent.shares_outstanding
            current_price = prices.get(constituent.symbol, constituent.current_price)
            base_price = base_prices.get(constituent.symbol, constituent.current_price)
            current_cap += shares * current_price
            base_cap += shares * base_price
        return self.base_value * (current_cap / base_cap) if base_cap > 0 else self.base_value

    def _calculate_equal_weighted_value(self, prices: Dict[str, float], base_prices: Dict[str, float]) -> float:
        """Calculate equal-weighted index value"""
        returns = []
        for constituent in self.constituents:
            current_price = prices.get(constituent.symbol, constituent.current_price)
            base_price = base_prices.get(constituent.symbol, constituent.current_price)
            if base_price > 0:
                returns.append(current_price / base_price)
        if returns:
            avg_return = np.mean(returns)
            return self.base_value * avg_return
        else:
            return self.base_value

def _calculate_cap_weighted_value(self, prices: Dict[str, float], base_prices: Dict[str, float]) -> float:
    """Calculate market cap weighted index value"""
    current_cap = 0
    base_cap = 0
    for constituent in self.constituents:
        shares = constituent.float_shares if self.weighting_method == IndexWeightingMethod.FLOAT_ADJUSTED else constituent.shares_outstanding
        current_price = prices.get(constituent.symbol, constituent.current_price)
        base_price = base_prices.get(constituent.symbol, constituent.current_price)
        current_cap += shares * current_price
        base_cap += shares * base_price
    return self.base_value * (current_cap / base_cap) if base_cap > 0 else self.base_value

class IndexCalculator:
    """Calculate index returns and performance metrics"""

    @staticmethod
    def calculate_price_return(current_value: float, previous_value: float) -> float:
        """Calculate price return"""
        if previous_value <= 0:
            raise ValidationError('Previous value must be positive')
        return (current_value - previous_value) / previous_value

    @staticmethod
    def calculate_total_return(current_value: float, previous_value: float, dividend_income: float) -> float:
        """Calculate total return including dividends"""
        if previous_value <= 0:
            raise ValidationError('Previous value must be positive')
        return (current_value - previous_value + dividend_income) / previous_value

    @staticmethod
    def calculate_index_dividend_yield(constituents: List[IndexConstituent], weights: Dict[str, float], dividend_yields: Dict[str, float]) -> float:
        """Calculate weighted average dividend yield"""
        total_yield = 0
        for constituent in constituents:
            weight = weights.get(constituent.symbol, 0)
            div_yield = dividend_yields.get(constituent.symbol, 0)
            total_yield += weight * div_yield
        return total_yield

    @staticmethod
    def calculate_index_volatility(returns: pd.Series, annualize: bool=True) -> float:
        """Calculate index volatility"""
        volatility = returns.std()
        if annualize:
            volatility *= np.sqrt(252)
        return volatility

    @staticmethod
    def calculate_tracking_error(index_returns: pd.Series, benchmark_returns: pd.Series) -> float:
        """Calculate tracking error between index and benchmark"""
        if len(index_returns) != len(benchmark_returns):
            raise ValidationError('Return series must have same length')
        excess_returns = index_returns - benchmark_returns
        return excess_returns.std() * np.sqrt(252)

@staticmethod
def calculate_index_dividend_yield(constituents: List[IndexConstituent], weights: Dict[str, float], dividend_yields: Dict[str, float]) -> float:
    """Calculate weighted average dividend yield"""
    total_yield = 0
    for constituent in constituents:
        weight = weights.get(constituent.symbol, 0)
        div_yield = dividend_yields.get(constituent.symbol, 0)
        total_yield += weight * div_yield
    return total_yield

class SecurityClassifier:
    """Classify and analyze different types of securities"""

    def __init__(self):
        self.security_characteristics = {SecurityType.COMMON_STOCK: {'voting_rights': True, 'dividend_rights': True, 'residual_claim': True, 'maturity': None, 'priority_in_liquidation': 'Last', 'income_type': 'Variable', 'risk_level': 'High'}, SecurityType.PREFERRED_STOCK: {'voting_rights': False, 'dividend_rights': True, 'residual_claim': False, 'maturity': None, 'priority_in_liquidation': 'Before Common', 'income_type': 'Fixed', 'risk_level': 'Medium'}, SecurityType.CORPORATE_BOND: {'voting_rights': False, 'dividend_rights': False, 'residual_claim': False, 'maturity': 'Fixed', 'priority_in_liquidation': 'Before Equity', 'income_type': 'Fixed', 'risk_level': 'Low-Medium'}, SecurityType.GOVERNMENT_BOND: {'voting_rights': False, 'dividend_rights': False, 'residual_claim': False, 'maturity': 'Fixed', 'priority_in_liquidation': 'Highest', 'income_type': 'Fixed', 'risk_level': 'Low'}}

    def classify_equity_security(self, characteristics: Dict[str, Any]) -> Dict[str, Any]:
        """Classify equity security and its features"""
        voting_rights = characteristics.get('voting_rights', True)
        dividend_preference = characteristics.get('dividend_preference', False)
        cumulative_dividends = characteristics.get('cumulative_dividends', False)
        callable = characteristics.get('callable', False)
        convertible = characteristics.get('convertible', False)
        if dividend_preference:
            security_type = SecurityType.PREFERRED_STOCK
            risk_level = 'Medium'
        else:
            security_type = SecurityType.COMMON_STOCK
            risk_level = 'High'
        features = []
        if cumulative_dividends:
            features.append('Cumulative Dividends')
        if callable:
            features.append('Callable')
        if convertible:
            features.append('Convertible')
        if not voting_rights:
            features.append('Non-Voting')
        return {'security_type': security_type, 'risk_level': risk_level, 'voting_rights': voting_rights, 'dividend_preference': dividend_preference, 'special_features': features, 'investment_characteristics': self.get_investment_characteristics(security_type)}

    def classify_debt_security(self, characteristics: Dict[str, Any]) -> Dict[str, Any]:
        """Classify debt security and its features"""
        issuer_type = characteristics.get('issuer_type', 'Corporate')
        maturity_years = characteristics.get('maturity_years', 10)
        coupon_rate = characteristics.get('coupon_rate', 0.05)
        callable = characteristics.get('callable', False)
        convertible = characteristics.get('convertible', False)
        secured = characteristics.get('secured', False)
        if issuer_type.lower() in ['government', 'treasury', 'federal']:
            security_type = SecurityType.GOVERNMENT_BOND
            risk_level = 'Low'
        else:
            security_type = SecurityType.CORPORATE_BOND
            risk_level = 'Low-Medium'
        if maturity_years <= 1:
            maturity_class = 'Short-term'
        elif maturity_years <= 10:
            maturity_class = 'Medium-term'
        else:
            maturity_class = 'Long-term'
        features = []
        if callable:
            features.append('Callable')
        if convertible:
            features.append('Convertible')
        if secured:
            features.append('Secured')
        return {'security_type': security_type, 'issuer_type': issuer_type, 'maturity_classification': maturity_class, 'risk_level': risk_level, 'coupon_rate': coupon_rate, 'special_features': features, 'investment_characteristics': self.get_investment_characteristics(security_type)}

    def get_investment_characteristics(self, security_type: SecurityType) -> Dict[str, str]:
        """Get investment characteristics for security type"""
        return self.security_characteristics.get(security_type, {})

    def compare_security_types(self, security_types: List[SecurityType]) -> pd.DataFrame:
        """Compare characteristics of different security types"""
        comparison_data = []
        for sec_type in security_types:
            characteristics = self.security_characteristics.get(sec_type, {})
            characteristics['security_type'] = sec_type.value
            comparison_data.append(characteristics)
        return pd.DataFrame(comparison_data)

