class PESTLEAnalyzer:
    """PESTLE analysis framework"""

    def perform_pestle_analysis(self, company_data: CompanyData) -> PESTLEAnalysis:
        """Perform PESTLE analysis for industry"""
        sector = company_data.sector
        political_factors = self.analyze_political_factors(sector)
        economic_factors = self.analyze_economic_factors(sector)
        social_factors = self.analyze_social_factors(sector)
        technological_factors = self.analyze_technological_factors(sector)
        legal_factors = self.analyze_legal_factors(sector)
        environmental_factors = self.analyze_environmental_factors(sector)
        factor_impacts = [len([f for f in political_factors if 'positive' not in f.lower()]), len([f for f in economic_factors if 'positive' not in f.lower()]), len([f for f in social_factors if 'positive' not in f.lower()]), len([f for f in technological_factors if 'threat' in f.lower() or 'disruption' in f.lower()]), len([f for f in legal_factors if 'risk' in f.lower() or 'compliance' in f.lower()]), len([f for f in environmental_factors if 'regulation' in f.lower() or 'pressure' in f.lower()])]
        total_negative_factors = sum(factor_impacts)
        if total_negative_factors <= 5:
            overall_impact = 'Favorable'
        elif total_negative_factors <= 10:
            overall_impact = 'Mixed'
        else:
            overall_impact = 'Challenging'
        return PESTLEAnalysis(political_factors=political_factors, economic_factors=economic_factors, social_factors=social_factors, technological_factors=technological_factors, legal_factors=legal_factors, environmental_factors=environmental_factors, overall_impact=overall_impact)

