        dpg.add_combo(['YYYY-MM-DD', 'DD/MM/YYYY', 'MM/DD/YYYY', 'DD-MMM-YYYY'], tag=date_format_tag, default_value=preferences.get('date_format', 'YYYY-MM-DD'), width=150)
        dpg.add_text('Decimal places for prices:')
