class APIConfig:
    """Centralized API configuration"""
    API_BASE_URL = os.getenv('FINCEPT_API_URL', 'https://finceptbackend.share.zrok.io')
    FALLBACK_URLS = ['http://localhost:4500', 'https://api.fincept.in']
    API_VERSION = '2.1.0'
    REQUEST_TIMEOUT = 10
    CONNECTION_TIMEOUT = 5
    MAX_RETRIES = 3
    RETRY_DELAY = 1.0
    REQUIRE_API_CONNECTION = True
    ALLOW_GUEST_FALLBACK = False
    CONFIG_DIR_NAME = '.fincept'
    CREDENTIALS_FILE = 'credentials.json'
    CACHE_FILE = 'cache.json'
    APP_NAME = 'Fincept Financial Terminal'
    APP_VERSION = '2.1.0'
    LOG_LEVEL = os.getenv('FINCEPT_LOG_LEVEL', 'INFO').upper()
    DEBUG_MODE = os.getenv('FINCEPT_DEBUG', 'false').lower() == 'true'
    _config_dir = None
    _credentials_path = None
    _cache_path = None

    def __init__(self):
        """Initialize configuration"""
        self._setup_directories()
        info('API configuration initialized', module='config', context={'api_url': self.get_api_url(), 'version': self.API_VERSION})

    @monitor_performance
    def _setup_directories(self):
        """Setup configuration directories"""
        with operation('setup_config_directories', module='config'):
            try:
                home_dir = Path.home()
                self._config_dir = home_dir / self.CONFIG_DIR_NAME
                self._config_dir.mkdir(exist_ok=True)
                self._credentials_path = self._config_dir / self.CREDENTIALS_FILE
                self._cache_path = self._config_dir / self.CACHE_FILE
                debug('Configuration directories setup completed', module='config', context={'config_dir': str(self._config_dir)})
            except Exception as e:
                error('Failed to setup configuration directories', module='config', context={'error': str(e)}, exc_info=True)
                raise

    @classmethod
    def get_api_url(cls) -> str:
        """Get the primary API URL"""
        url = cls.API_BASE_URL.rstrip('/')
        debug('Retrieved API URL', module='config', context={'url': url})
        return url

    @classmethod
    def get_full_url(cls, endpoint: str) -> str:
        """Get full URL for an endpoint"""
        if not endpoint.startswith('/'):
            endpoint = '/' + endpoint
        full_url = f'{cls.get_api_url()}{endpoint}'
        debug('Generated full URL', module='config', context={'endpoint': endpoint, 'full_url': full_url})
        return full_url

    @classmethod
    def get_fallback_urls(cls) -> List[str]:
        """Get list of fallback URLs"""
        urls = [url.rstrip('/') for url in cls.FALLBACK_URLS]
        debug('Retrieved fallback URLs', module='config', context={'count': len(urls)})
        return urls

    @classmethod
    def validate_configuration(cls) -> Dict[str, Any]:
        """Validate current configuration"""
        with operation('validate_configuration', module='config'):
            config_data = {'api_url': cls.get_api_url(), 'api_version': cls.API_VERSION, 'require_connection': cls.REQUIRE_API_CONNECTION, 'allow_guest_fallback': cls.ALLOW_GUEST_FALLBACK, 'request_timeout': cls.REQUEST_TIMEOUT, 'connection_timeout': cls.CONNECTION_TIMEOUT, 'max_retries': cls.MAX_RETRIES, 'debug_mode': cls.DEBUG_MODE, 'fallback_urls_count': len(cls.FALLBACK_URLS)}
            info('Configuration validated', module='config', context=config_data)
            return config_data

    @classmethod
    def set_api_url(cls, new_url: str):
        """Update API URL at runtime"""
        old_url = cls.API_BASE_URL
        cls.API_BASE_URL = new_url.rstrip('/')
        info('API URL updated', module='config', context={'old_url': old_url, 'new_url': cls.API_BASE_URL})

    @classmethod
    def set_debug_mode(cls, debug_enabled: bool):
        """Set debug mode"""
        old_debug = cls.DEBUG_MODE
        cls.DEBUG_MODE = debug_enabled
        set_debug_mode(debug_enabled)
        info('Debug mode changed', module='config', context={'old_debug': old_debug, 'new_debug': debug_enabled})

    @classmethod
    def set_strict_mode(cls, strict: bool):
        """Set strict API connection mode"""
        old_strict = cls.REQUIRE_API_CONNECTION
        cls.REQUIRE_API_CONNECTION = strict
        cls.ALLOW_GUEST_FALLBACK = not strict
        info('Strict mode changed', module='config', context={'old_strict': old_strict, 'new_strict': strict})

    def get_config_dir(self) -> Path:
        """Get configuration directory path"""
        return self._config_dir

    def get_credentials_path(self) -> Path:
        """Get credentials file path"""
        return self._credentials_path

    def get_cache_path(self) -> Path:
        """Get cache file path"""
        return self._cache_path

    @classmethod
    def get_request_headers(cls, api_key: Optional[str]=None) -> Dict[str, str]:
        """Get standard request headers"""
        headers = {'Content-Type': 'application/json', 'User-Agent': f'{cls.APP_NAME}/{cls.APP_VERSION}', 'Accept': 'application/json', 'X-API-Version': cls.API_VERSION}
        if api_key:
            headers['X-API-Key'] = api_key
        debug('Generated request headers', module='config', context={'has_api_key': bool(api_key)})
        return headers

    @classmethod
    def get_timeout_config(cls) -> Dict[str, float]:
        """Get timeout configuration"""
        timeout_config = {'connect': cls.CONNECTION_TIMEOUT, 'read': cls.REQUEST_TIMEOUT, 'total': cls.REQUEST_TIMEOUT + cls.CONNECTION_TIMEOUT}
        debug('Generated timeout configuration', module='config', context=timeout_config)
        return timeout_config

    def cleanup(self):
        """Cleanup configuration resources"""
        with operation('config_cleanup', module='config'):
            info('Configuration cleanup completed', module='config')

@classmethod
def get_request_headers(cls, api_key: Optional[str]=None) -> Dict[str, str]:
    """Get standard request headers"""
    headers = {'Content-Type': 'application/json', 'User-Agent': f'{cls.APP_NAME}/{cls.APP_VERSION}', 'Accept': 'application/json', 'X-API-Version': cls.API_VERSION}
    if api_key:
        headers['X-API-Key'] = api_key
    debug('Generated request headers', module='config', context={'has_api_key': bool(api_key)})
    return headers

class BaseTab:
    """Base class for all tabs in the application"""

    def __init__(self, app):
        self.app = app

    def get_label(self):
        """Return the tab label - override in subclasses"""
        return 'Base Tab'

    def create_content(self):
        """Create tab content - override in subclasses"""
        dpg.add_text('Base tab content')

    def add_section_header(self, text, color=None):
        """Add a section header with consistent styling"""
        if color is None:
            color = [200, 200, 255]
        dpg.add_spacer(height=10)
        dpg.add_text(text, color=color)
        dpg.add_separator()
        dpg.add_spacer(height=10)

    def create_child_window(self, tag=None, width=300, height=200, **kwargs):
        """Create a standardized child window"""
        return dpg.child_window(tag=tag, width=width, height=height, border=True, **kwargs)

    def show_message(self, message, message_type='info'):
        """Show a message with appropriate styling"""
        colors = {'info': [100, 150, 255], 'success': [100, 255, 100], 'warning': [255, 200, 100], 'error': [255, 100, 100]}
        color = colors.get(message_type, colors['info'])
        dpg.add_text(message, color=color)

    def get_app_sizes(self):
        """Get application layout sizes for backward compatibility"""
        if hasattr(self.app, 'usable_width') and hasattr(self.app, 'usable_height'):
            return {'usable_width': self.app.usable_width, 'usable_height': self.app.usable_height, 'left_width': getattr(self.app, 'left_width', 300), 'center_width': getattr(self.app, 'center_width', 500), 'right_width': getattr(self.app, 'right_width', 300), 'top_height': getattr(self.app, 'top_height', 400), 'bottom_height': getattr(self.app, 'bottom_height', 200), 'cell_height': getattr(self.app, 'cell_height', 180)}
        else:
            return {'usable_width': 1180, 'usable_height': 480, 'left_width': 290, 'center_width': 590, 'right_width': 290, 'top_height': 320, 'bottom_height': 160, 'cell_height': 160}

    def resize_components(self, left_width, center_width, right_width, top_height, bottom_height, cell_height):
        """Handle component resizing - override in subclasses if needed"""
        pass

    def get_auth_headers(self):
        """Get authentication headers for API calls"""
        if hasattr(self.app, 'get_auth_headers'):
            return self.app.get_auth_headers()
        return {}

    def is_user_authenticated(self):
        """Check if user is authenticated"""
        if hasattr(self.app, 'is_user_authenticated'):
            return self.app.is_user_authenticated()
        return False

    def get_user_type(self):
        """Get current user type"""
        if hasattr(self.app, 'get_user_type'):
            return self.app.get_user_type()
        return None

    def get_session_data(self):
        """Get session data"""
        if hasattr(self.app, 'get_session_data'):
            return self.app.get_session_data()
        return {}

    def cleanup(self):
        """Clean up tab resources - override in subclasses if needed"""
        pass

def show_message(self, message, message_type='info'):
    """Show a message with appropriate styling"""
    colors = {'info': [100, 150, 255], 'success': [100, 255, 100], 'warning': [255, 200, 100], 'error': [255, 100, 100]}
    color = colors.get(message_type, colors['info'])
    dpg.add_text(message, color=color)

class FinceptAPIClient:

    def __init__(self, session_data: Dict[str, Any]):
        self.api_base = 'https://finceptbackend.share.zrok.io'
        self.session_data = session_data
        self.api_key = session_data.get('api_key')
        self.user_type = session_data.get('user_type', 'guest')
        self.request_count = 0
        info('API client initialized', context={'user_type': self.user_type, 'has_api_key': bool(self.api_key)})

    def get_headers(self) -> Dict[str, str]:
        """Get authentication headers"""
        headers = {'Content-Type': 'application/json'}
        if self.api_key:
            headers['X-API-Key'] = self.api_key
        return headers

    def make_request(self, method: str, endpoint: str, data: dict=None, params: dict=None, timeout: int=10) -> Dict[str, Any]:
        """Make authenticated API request"""
        try:
            url = f'{self.api_base}{endpoint}'
            headers = self.get_headers()
            self.request_count += 1
            if method.upper() == 'GET':
                response = requests.get(url, headers=headers, params=params, timeout=timeout)
            elif method.upper() == 'POST':
                response = requests.post(url, headers=headers, json=data, timeout=timeout)
            elif method.upper() == 'PUT':
                response = requests.put(url, headers=headers, json=data, timeout=timeout)
            elif method.upper() == 'DELETE':
                response = requests.delete(url, headers=headers, timeout=timeout)
            else:
                error('Unsupported HTTP method', context={'method': method, 'endpoint': endpoint})
                return {'success': False, 'error': f'Unsupported method: {method}'}
            if response.status_code >= 400:
                error('API request failed', context={'method': method, 'endpoint': endpoint, 'status_code': response.status_code})
            return {'success': response.status_code < 400, 'status_code': response.status_code, 'data': response.json() if response.content else {}, 'headers': dict(response.headers)}
        except requests.exceptions.Timeout:
            warning('API request timeout', context={'endpoint': endpoint, 'timeout': timeout})
            return {'success': False, 'error': 'Request timeout'}
        except requests.exceptions.ConnectionError:
            error('API connection error', context={'endpoint': endpoint})
            return {'success': False, 'error': 'Connection error - API server not available'}
        except requests.exceptions.RequestException as e:
            error('API request exception', context={'endpoint': endpoint, 'error': str(e)})
            return {'success': False, 'error': f'Request error: {str(e)}'}
        except Exception as e:
            error('Unexpected API error', context={'endpoint': endpoint, 'error': str(e)})
            return {'success': False, 'error': f'Unexpected error: {str(e)}'}

    def check_auth_status(self) -> Dict[str, Any]:
        """Check current authentication status"""
        result = self.make_request('GET', '/auth/status')
        if result['success'] and result['data'].get('success'):
            return {'success': True, 'authenticated': result['data']['data'].get('authenticated', False), 'user_type': result['data']['data'].get('user_type'), 'user_info': result['data']['data'].get('user', result['data']['data'].get('guest'))}
        return {'success': False, 'authenticated': False}

    def logout(self) -> Dict[str, Any]:
        """Logout user and clear session"""
        if not self.is_authenticated():
            return {'success': False, 'error': 'User is not authenticated'}
        result = self.make_request('POST', '/auth/logout')
        if result['success'] and result['data'].get('success'):
            info('User logged out successfully', context={'user_type': self.user_type})
            self.clear_session()
            return {'success': True, 'message': result['data']['data'].get('message', 'Logged out successfully')}
        error('Logout failed', context={'user_type': self.user_type})
        return {'success': False, 'error': result.get('error', 'Failed to logout')}

    def clear_session(self) -> None:
        """Clear all session data locally"""
        device_id = self.session_data.get('device_id', 'unknown')
        self.session_data = {'user_type': 'guest', 'authenticated': False, 'api_key': None, 'device_id': device_id, 'user_info': {}, 'expires_at': None, 'requests_today': 0, 'daily_limit': 50}
        self.api_key = None
        self.user_type = 'guest'
        self.request_count = 0

    def force_logout(self) -> Dict[str, Any]:
        """Force logout without API call (for offline situations)"""
        info('Force logout executed', context={'user_type': self.user_type})
        self.clear_session()
        return {'success': True, 'message': 'Forced logout completed - session cleared locally'}

    def get_chat_sessions(self, limit: int=50) -> Dict[str, Any]:
        """Get user's chat sessions"""
        params = {'limit': limit}
        result = self.make_request('GET', '/chat/sessions', params=params)
        if result['success'] and result['data'].get('success'):
            return {'success': True, 'sessions': result['data']['data']['sessions'], 'total': result['data']['data'].get('total', 0), 'user_type': result['data']['data'].get('user_type')}
        return {'success': False, 'sessions': [], 'error': result.get('error', 'Failed to get chat sessions')}

    def create_chat_session(self, title: str='New Conversation') -> Dict[str, Any]:
        """Create new chat session"""
        data = {'title': title}
        result = self.make_request('POST', '/chat/sessions', data)
        if result['success'] and result['data'].get('success'):
            return {'success': True, 'session': result['data']['data']['session'], 'message': result['data']['data'].get('message', 'Session created')}
        return {'success': False, 'error': result.get('error', 'Failed to create chat session')}

    def get_chat_session(self, session_uuid: str) -> Dict[str, Any]:
        """Get specific chat session with messages"""
        result = self.make_request('GET', f'/chat/sessions/{session_uuid}')
        if result['success'] and result['data'].get('success'):
            session_detail = result['data']['data']
            return {'success': True, 'session': session_detail['session'], 'messages': session_detail['messages'], 'total_messages': session_detail['total_messages']}
        return {'success': False, 'error': result.get('error', 'Failed to get chat session')}

    def send_chat_message(self, session_uuid: str, content: str) -> Dict[str, Any]:
        """Send message to chat session"""
        data = {'content': content}
        result = self.make_request('POST', f'/chat/sessions/{session_uuid}/messages', data)
        if result['success'] and result['data'].get('success'):
            return {'success': True, 'user_message': result['data']['data']['user_message'], 'ai_message': result['data']['data']['ai_message'], 'new_title': result['data']['data'].get('new_title')}
        return {'success': False, 'error': result.get('error', 'Failed to send message')}

