class StackInspector:
    """Efficient stack inspection for class detection"""

    @staticmethod
    @lru_cache(maxsize=512)
    def get_caller_class_name(skip_frames: int=3) -> Optional[str]:
        """
        Get the class name of the calling code with caching.
        skip_frames: number of frames to skip (logger internals)
        """
        try:
            frame = inspect.currentframe()
            for _ in range(skip_frames):
                if frame is None:
                    return None
                frame = frame.f_back
            if frame is None:
                return None
            local_vars = frame.f_locals
            if 'self' in local_vars:
                return local_vars['self'].__class__.__name__
            code = frame.f_code
            if code.co_name != '<module>':
                global_vars = frame.f_globals
                for name, obj in global_vars.items():
                    if inspect.isclass(obj) and hasattr(obj, code.co_name):
                        return name
            module_name = frame.f_globals.get('__name__', '')
            if module_name:
                return module_name.split('.')[-1]
            return None
        except Exception:
            return None
        finally:
            del frame

@staticmethod
@lru_cache(maxsize=512)
def get_caller_class_name(skip_frames: int=3) -> Optional[str]:
    """
        Get the class name of the calling code with caching.
        skip_frames: number of frames to skip (logger internals)
        """
    try:
        frame = inspect.currentframe()
        for _ in range(skip_frames):
            if frame is None:
                return None
            frame = frame.f_back
        if frame is None:
            return None
        local_vars = frame.f_locals
        if 'self' in local_vars:
            return local_vars['self'].__class__.__name__
        code = frame.f_code
        if code.co_name != '<module>':
            global_vars = frame.f_globals
            for name, obj in global_vars.items():
                if inspect.isclass(obj) and hasattr(obj, code.co_name):
                    return name
        module_name = frame.f_globals.get('__name__', '')
        if module_name:
            return module_name.split('.')[-1]
        return None
    except Exception:
        return None
    finally:
        del frame

class ConnectionPool:
    """Simple connection pool for HTTP requests - optimized"""

    def __init__(self, max_connections=5):
        self.max_connections = max_connections
        self._session = None
        self._lock = threading.RLock()
        self._creation_time = None

    @monitor_performance
    def get_session(self):
        if self._session is None:
            with self._lock:
                if self._session is None:
                    with operation('create_session'):
                        requests = _lazy_imports.get_requests()
                        self._session = requests.Session()
                        self._creation_time = datetime.now()
                        adapter = requests.adapters.HTTPAdapter(pool_connections=self.max_connections, pool_maxsize=self.max_connections, max_retries=0)
                        self._session.mount('http://', adapter)
                        self._session.mount('https://', adapter)
                        logger.debug('HTTP session created with connection pooling')
        return self._session

    def close(self):
        if self._session:
            try:
                self._session.close()
                if self._creation_time:
                    duration = (datetime.now() - self._creation_time).total_seconds()
                    logger.debug(f'HTTP session closed after {duration:.2f} seconds')
                self._session = None
                self._creation_time = None
            except Exception as e:
                logger.error(f'Error closing HTTP session: {e}')

@monitor_performance
def get_session(self):
    if self._session is None:
        with self._lock:
            if self._session is None:
                with operation('create_session'):
                    requests = _lazy_imports.get_requests()
                    self._session = requests.Session()
                    self._creation_time = datetime.now()
                    adapter = requests.adapters.HTTPAdapter(pool_connections=self.max_connections, pool_maxsize=self.max_connections, max_retries=0)
                    self._session.mount('http://', adapter)
                    self._session.mount('https://', adapter)
                    logger.debug('HTTP session created with connection pooling')
    return self._session

