class HedgeFundLLMAdapter:
    """Adapter to use different LLM providers with hedge fund agents"""

    def __init__(self, provider='openai', **kwargs):
        self.provider = provider
        self.config = kwargs

    def call_llm(self, prompt, pydantic_model, agent_name, state, default_factory):
        """Route to appropriate LLM provider"""
        if self.provider == 'openrouter':
            return call_llm_openrouter(prompt, pydantic_model, agent_name, state, default_factory, model=self.config.get('model', 'anthropic/claude-3.5-sonnet'))
        elif self.provider == 'ollama':
            return call_llm_ollama(prompt, pydantic_model, agent_name, state, default_factory, model=self.config.get('model', 'llama3.1:70b'))
        elif self.provider == 'openai':
            return self.call_openai_llm(prompt, pydantic_model, agent_name, state, default_factory)
        else:
            raise ValueError(f'Unsupported provider: {self.provider}')

    def call_openai_llm(self, prompt, pydantic_model, agent_name, state, default_factory):
        """OpenAI integration"""
        import openai
        client = openai.OpenAI(api_key=self.config.get('api_key'))
        try:
            response = client.chat.completions.create(model=self.config.get('model', 'gpt-4'), messages=[{'role': 'system', 'content': prompt.messages[0].content}, {'role': 'user', 'content': prompt.messages[1].content}], temperature=0.1, max_tokens=2000)
            content = response.choices[0].message.content
            start_idx = content.find('{')
            end_idx = content.rfind('}') + 1
            json_str = content[start_idx:end_idx]
            parsed_data = json.loads(json_str)
            return pydantic_model(**parsed_data)
        except Exception as e:
            print(f'OpenAI API error: {e}')
            return default_factory()

def call_llm(self, prompt, pydantic_model, agent_name, state, default_factory):
    """Route to appropriate LLM provider"""
    if self.provider == 'openrouter':
        return call_llm_openrouter(prompt, pydantic_model, agent_name, state, default_factory, model=self.config.get('model', 'anthropic/claude-3.5-sonnet'))
    elif self.provider == 'ollama':
        return call_llm_ollama(prompt, pydantic_model, agent_name, state, default_factory, model=self.config.get('model', 'llama3.1:70b'))
    elif self.provider == 'openai':
        return self.call_openai_llm(prompt, pydantic_model, agent_name, state, default_factory)
    else:
        raise ValueError(f'Unsupported provider: {self.provider}')

def is_ollama_server_running() -> bool:
    """Check if the Ollama server is running."""
    try:
        response = requests.get(OLLAMA_API_MODELS_ENDPOINT, timeout=2)
        return response.status_code == 200
    except requests.RequestException:
        return False

class AgentProgress:
    """Manages progress tracking for multiple agents."""

    def __init__(self):
        self.agent_status: Dict[str, Dict[str, str]] = {}
        self.table = Table(show_header=False, box=None, padding=(0, 1))
        self.live = Live(self.table, console=console, refresh_per_second=4)
        self.started = False
        self.update_handlers: List[Callable[[str, Optional[str], str], None]] = []

    def register_handler(self, handler: Callable[[str, Optional[str], str], None]):
        """Register a handler to be called when agent status updates."""
        self.update_handlers.append(handler)
        return handler

    def unregister_handler(self, handler: Callable[[str, Optional[str], str], None]):
        """Unregister a previously registered handler."""
        if handler in self.update_handlers:
            self.update_handlers.remove(handler)

    def start(self):
        """Start the progress display."""
        if not self.started:
            self.live.start()
            self.started = True

    def stop(self):
        """Stop the progress display."""
        if self.started:
            self.live.stop()
            self.started = False

    def update_status(self, agent_name: str, ticker: Optional[str]=None, status: str='', analysis: Optional[str]=None):
        """Update the status of an agent."""
        if agent_name not in self.agent_status:
            self.agent_status[agent_name] = {'status': '', 'ticker': None}
        if ticker:
            self.agent_status[agent_name]['ticker'] = ticker
        if status:
            self.agent_status[agent_name]['status'] = status
        if analysis:
            self.agent_status[agent_name]['analysis'] = analysis
        timestamp = datetime.now(timezone.utc).isoformat()
        self.agent_status[agent_name]['timestamp'] = timestamp
        for handler in self.update_handlers:
            handler(agent_name, ticker, status, analysis, timestamp)
        self._refresh_display()

    def get_all_status(self):
        """Get the current status of all agents as a dictionary."""
        return {agent_name: {'ticker': info['ticker'], 'status': info['status'], 'display_name': self._get_display_name(agent_name)} for agent_name, info in self.agent_status.items()}

    def _get_display_name(self, agent_name: str) -> str:
        """Convert agent_name to a display-friendly format."""
        return agent_name.replace('_agent', '').replace('_', ' ').title()

    def _refresh_display(self):
        """Refresh the progress display."""
        self.table.columns.clear()
        self.table.add_column(width=100)

        def sort_key(item):
            agent_name = item[0]
            if 'risk_management' in agent_name:
                return (2, agent_name)
            elif 'portfolio_management' in agent_name:
                return (3, agent_name)
            else:
                return (1, agent_name)
        for agent_name, info in sorted(self.agent_status.items(), key=sort_key):
            status = info['status']
            ticker = info['ticker']
            if status.lower() == 'done':
                style = Style(color='green', bold=True)
                symbol = '✓'
            elif status.lower() == 'error':
                style = Style(color='red', bold=True)
                symbol = '✗'
            else:
                style = Style(color='yellow')
                symbol = '⋯'
            agent_display = self._get_display_name(agent_name)
            status_text = Text()
            status_text.append(f'{symbol} ', style=style)
            status_text.append(f'{agent_display:<20}', style=Style(bold=True))
            if ticker:
                status_text.append(f'[{ticker}] ', style=Style(color='cyan'))
            status_text.append(status, style=style)
            self.table.add_row(status_text)

def _get_display_name(self, agent_name: str) -> str:
    """Convert agent_name to a display-friendly format."""
    return agent_name.replace('_agent', '').replace('_', ' ').title()

def get_prices(ticker: str, start_date: str, end_date: str, api_key: str=None) -> list[Price]:
    """Fetch price data from cache or API."""
    cache_key = f'{ticker}_{start_date}_{end_date}'
    if (cached_data := _cache.get_prices(cache_key)):
        return [Price(**price) for price in cached_data]
    headers = {}
    financial_api_key = api_key or os.environ.get('FINANCIAL_DATASETS_API_KEY')
    if financial_api_key:
        headers['X-API-KEY'] = financial_api_key
    url = f'https://api.financialdatasets.ai/prices/?ticker={ticker}&interval=day&interval_multiplier=1&start_date={start_date}&end_date={end_date}'
    response = _make_api_request(url, headers)
    if response.status_code != 200:
        raise Exception(f'Error fetching data: {ticker} - {response.status_code} - {response.text}')
    price_response = PriceResponse(**response.json())
    prices = price_response.prices
    if not prices:
        return []
    _cache.set_prices(cache_key, [p.model_dump() for p in prices])
    return prices

def get_financial_metrics(ticker: str, end_date: str, period: str='ttm', limit: int=10, api_key: str=None) -> list[FinancialMetrics]:
    """Fetch financial metrics from cache or API."""
    cache_key = f'{ticker}_{period}_{end_date}_{limit}'
    if (cached_data := _cache.get_financial_metrics(cache_key)):
        return [FinancialMetrics(**metric) for metric in cached_data]
    headers = {}
    financial_api_key = api_key or os.environ.get('FINANCIAL_DATASETS_API_KEY')
    if financial_api_key:
        headers['X-API-KEY'] = financial_api_key
    url = f'https://api.financialdatasets.ai/financial-metrics/?ticker={ticker}&report_period_lte={end_date}&limit={limit}&period={period}'
    response = _make_api_request(url, headers)
    if response.status_code != 200:
        raise Exception(f'Error fetching data: {ticker} - {response.status_code} - {response.text}')
    metrics_response = FinancialMetricsResponse(**response.json())
    financial_metrics = metrics_response.financial_metrics
    if not financial_metrics:
        return []
    _cache.set_financial_metrics(cache_key, [m.model_dump() for m in financial_metrics])
    return financial_metrics

def get_insider_trades(ticker: str, end_date: str, start_date: str | None=None, limit: int=1000, api_key: str=None) -> list[InsiderTrade]:
    """Fetch insider trades from cache or API."""
    cache_key = f'{ticker}_{start_date or 'none'}_{end_date}_{limit}'
    if (cached_data := _cache.get_insider_trades(cache_key)):
        return [InsiderTrade(**trade) for trade in cached_data]
    headers = {}
    financial_api_key = api_key or os.environ.get('FINANCIAL_DATASETS_API_KEY')
    if financial_api_key:
        headers['X-API-KEY'] = financial_api_key
    all_trades = []
    current_end_date = end_date
    while True:
        url = f'https://api.financialdatasets.ai/insider-trades/?ticker={ticker}&filing_date_lte={current_end_date}'
        if start_date:
            url += f'&filing_date_gte={start_date}'
        url += f'&limit={limit}'
        response = _make_api_request(url, headers)
        if response.status_code != 200:
            raise Exception(f'Error fetching data: {ticker} - {response.status_code} - {response.text}')
        data = response.json()
        response_model = InsiderTradeResponse(**data)
        insider_trades = response_model.insider_trades
        if not insider_trades:
            break
        all_trades.extend(insider_trades)
        if not start_date or len(insider_trades) < limit:
            break
        current_end_date = min((trade.filing_date for trade in insider_trades)).split('T')[0]
        if current_end_date <= start_date:
            break
    if not all_trades:
        return []
    _cache.set_insider_trades(cache_key, [trade.model_dump() for trade in all_trades])
    return all_trades

def get_price_data(ticker: str, start_date: str, end_date: str, api_key: str=None) -> pd.DataFrame:
    prices = get_prices(ticker, start_date, end_date, api_key=api_key)
    return prices_to_df(prices)

class BehavioralAgent:
    """Behavioral finance analysis - crowd psychology and market inefficiencies"""

    def __init__(self):
        self.name = 'behavioral'
        self.data_manager = DataFeedManager()
        self.client = openai.OpenAI(api_key=CONFIG.api.openai_api_key)
        self.behavioral_patterns = {'herd_behavior': {'indicators': ['consensus_trades', 'crowded_positions', 'momentum_chasing'], 'contrarian_threshold': 0.7}, 'overconfidence': {'indicators': ['excessive_trading', 'narrow_spreads', 'low_volatility'], 'contrarian_threshold': 0.6}, 'loss_aversion': {'indicators': ['selling_pressure', 'defensive_positioning', 'cash_hoarding'], 'contrarian_threshold': 0.8}, 'anchoring': {'indicators': ['resistance_levels', 'round_numbers', 'historical_highs'], 'contrarian_threshold': 0.5}, 'recency_bias': {'indicators': ['trend_extrapolation', 'momentum_investing', 'recent_news_focus'], 'contrarian_threshold': 0.6}}
        self.market_psychology_indicators = {'fear': ['VIX', 'put_call_ratio', 'safe_haven_flows'], 'greed': ['margin_debt', 'IPO_activity', 'speculative_trading'], 'complacency': ['low_volatility', 'compressed_spreads', 'leverage_buildup'], 'panic': ['forced_selling', 'liquidity_crisis', 'correlation_spike']}

    async def analyze_behavioral_patterns(self) -> List[BehaviorSignal]:
        """Analyze behavioral finance patterns in markets"""
        signals = []
        for pattern, config in self.behavioral_patterns.items():
            try:
                signal = await self._analyze_behavioral_pattern(pattern, config)
                if signal:
                    signals.append(signal)
            except Exception as e:
                logging.error(f'Error analyzing {pattern}: {e}')
                continue
        return signals

    async def _analyze_behavioral_pattern(self, pattern: str, config: Dict) -> Optional[BehaviorSignal]:
        """Analyze specific behavioral pattern"""
        base_intensity = np.random.uniform(0.2, 0.8)
        pattern_adjustments = {'herd_behavior': np.random.normal(0.1, 0.2), 'overconfidence': np.random.normal(-0.1, 0.15), 'loss_aversion': np.random.normal(0.05, 0.25), 'anchoring': np.random.normal(0, 0.1), 'recency_bias': np.random.normal(0.08, 0.18)}
        intensity = np.clip(base_intensity + pattern_adjustments.get(pattern, 0), 0, 1)
        if pattern in ['herd_behavior', 'overconfidence', 'recency_bias']:
            if intensity > 0.6:
                market_impact = 'bearish'
            else:
                market_impact = 'bullish'
        elif pattern == 'loss_aversion':
            market_impact = 'bullish' if intensity > 0.6 else 'bearish'
        else:
            market_impact = 'neutral'
        contrarian_opportunity = intensity > config['contrarian_threshold']
        affected_assets = self._get_affected_assets(pattern, intensity)
        return BehaviorSignal(behavior_type=pattern, intensity=intensity, market_impact=market_impact, contrarian_opportunity=contrarian_opportunity, affected_assets=affected_assets, confidence=0.5 + intensity * 0.3)

    def _get_affected_assets(self, pattern: str, intensity: float) -> List[str]:
        """Determine which assets are affected by behavioral pattern"""
        if pattern == 'herd_behavior':
            if intensity > 0.7:
                return ['momentum_stocks', 'growth_stocks', 'crypto']
            else:
                return ['broad_market']
        elif pattern == 'overconfidence':
            return ['individual_stocks', 'options', 'leveraged_products']
        elif pattern == 'loss_aversion':
            return ['defensive_stocks', 'bonds', 'gold', 'utilities']
        elif pattern == 'anchoring':
            return ['stocks_near_highs', 'round_number_levels']
        elif pattern == 'recency_bias':
            return ['trending_sectors', 'recent_winners']
        else:
            return ['broad_market']

    async def analyze_market_psychology(self) -> Dict[str, float]:
        """Analyze overall market psychology"""
        psychology_scores = {}
        for emotion, indicators in self.market_psychology_indicators.items():
            score = np.random.uniform(0.2, 0.8)
            if emotion == 'fear' and 'greed' in psychology_scores:
                score = max(0.1, 1.0 - psychology_scores['greed'] + np.random.normal(0, 0.1))
            elif emotion == 'greed' and 'fear' in psychology_scores:
                score = max(0.1, 1.0 - psychology_scores['fear'] + np.random.normal(0, 0.1))
            psychology_scores[emotion] = np.clip(score, 0, 1)
        return psychology_scores

    def _detect_behavioral_anomalies(self, signals: List[BehaviorSignal]) -> List[str]:
        """Detect behavioral anomalies in the market"""
        anomalies = []
        high_intensity_patterns = [s for s in signals if s.intensity > 0.7]
        if len(high_intensity_patterns) >= 2:
            anomalies.append('multiple_behavioral_extremes')
        contrarian_signals = [s for s in signals if s.contrarian_opportunity]
        if len(contrarian_signals) >= 3:
            anomalies.append('multiple_contrarian_opportunities')
        bullish_signals = [s for s in signals if s.market_impact == 'bullish']
        bearish_signals = [s for s in signals if s.market_impact == 'bearish']
        if len(bullish_signals) > 0 and len(bearish_signals) > 0:
            if abs(len(bullish_signals) - len(bearish_signals)) <= 1:
                anomalies.append('conflicting_behavioral_signals')
        return anomalies

    async def get_behavioral_report(self) -> Dict:
        """Generate comprehensive behavioral finance report"""
        behavioral_signals = await self.analyze_behavioral_patterns()
        psychology_scores = await self.analyze_market_psychology()
        anomalies = self._detect_behavioral_anomalies(behavioral_signals)
        overall_sentiment = self._calculate_behavioral_sentiment(behavioral_signals, psychology_scores)
        return {'timestamp': datetime.now().isoformat(), 'agent': self.name, 'behavioral_analysis': {'overall_sentiment': overall_sentiment, 'sentiment_classification': self._classify_sentiment(overall_sentiment), 'behavioral_patterns': [{'pattern': signal.behavior_type, 'intensity': signal.intensity, 'market_impact': signal.market_impact, 'contrarian_opportunity': signal.contrarian_opportunity, 'affected_assets': signal.affected_assets, 'confidence': signal.confidence} for signal in behavioral_signals], 'market_psychology': psychology_scores, 'behavioral_anomalies': anomalies}, 'trading_implications': {'contrarian_opportunities': [s.behavior_type for s in behavioral_signals if s.contrarian_opportunity], 'behavioral_momentum': [s.behavior_type for s in behavioral_signals if s.intensity > 0.6 and (not s.contrarian_opportunity)], 'risk_management': self._get_behavioral_risk_management(behavioral_signals), 'position_sizing': self._get_behavioral_position_sizing(behavioral_signals)}, 'monitoring_priorities': {'extreme_behaviors': [s.behavior_type for s in behavioral_signals if s.intensity > 0.7], 'contrarian_signals': [s.behavior_type for s in behavioral_signals if s.contrarian_opportunity], 'psychology_extremes': [emotion for emotion, score in psychology_scores.items() if score > 0.7 or score < 0.3]}}

    def _calculate_behavioral_sentiment(self, signals: List[BehaviorSignal], psychology: Dict[str, float]) -> float:
        """Calculate overall behavioral sentiment"""
        if not signals and (not psychology):
            return 0.0
        signal_sentiment = 0.0
        if signals:
            bullish_weight = sum((s.intensity for s in signals if s.market_impact == 'bullish'))
            bearish_weight = sum((s.intensity for s in signals if s.market_impact == 'bearish'))
            total_weight = bullish_weight + bearish_weight
            if total_weight > 0:
                signal_sentiment = (bullish_weight - bearish_weight) / total_weight
        psychology_sentiment = 0.0
        if psychology:
            greed_score = psychology.get('greed', 0.5)
            fear_score = psychology.get('fear', 0.5)
            psychology_sentiment = greed_score - fear_score
        if signals and psychology:
            combined_sentiment = 0.6 * signal_sentiment + 0.4 * psychology_sentiment
        elif signals:
            combined_sentiment = signal_sentiment
        elif psychology:
            combined_sentiment = psychology_sentiment
        else:
            combined_sentiment = 0.0
        return np.clip(combined_sentiment, -1.0, 1.0)

    def _classify_sentiment(self, sentiment: float) -> str:
        """Classify behavioral sentiment"""
        if sentiment > 0.4:
            return 'behavioral_euphoria'
        elif sentiment > 0.1:
            return 'behavioral_optimism'
        elif sentiment > -0.1:
            return 'behavioral_neutral'
        elif sentiment > -0.4:
            return 'behavioral_pessimism'
        else:
            return 'behavioral_despair'

    def _get_behavioral_risk_management(self, signals: List[BehaviorSignal]) -> List[str]:
        """Get behavioral risk management recommendations"""
        recommendations = []
        high_intensity = [s for s in signals if s.intensity > 0.7]
        if high_intensity:
            recommendations.append('Monitor for behavioral reversals')
            recommendations.append('Consider reducing position sizes')
        herd_signals = [s for s in signals if s.behavior_type == 'herd_behavior' and s.intensity > 0.6]
        if herd_signals:
            recommendations.append('Prepare for trend reversals')
            recommendations.append('Avoid momentum chasing')
        overconfidence_signals = [s for s in signals if s.behavior_type == 'overconfidence' and s.intensity > 0.5]
        if overconfidence_signals:
            recommendations.append('Increase due diligence')
            recommendations.append('Diversify more broadly')
        return recommendations or ['Standard behavioral risk monitoring']

    def _get_behavioral_position_sizing(self, signals: List[BehaviorSignal]) -> str:
        """Get position sizing recommendation based on behavioral patterns"""
        contrarian_count = sum((1 for s in signals if s.contrarian_opportunity))
        high_intensity_count = sum((1 for s in signals if s.intensity > 0.7))
        if contrarian_count >= 2:
            return 'reduce_size'
        elif high_intensity_count >= 2:
            return 'reduce_size'
        elif contrarian_count == 1 and high_intensity_count == 0:
            return 'increase_size'
        else:
            return 'normal'

def _calculate_behavioral_sentiment(self, signals: List[BehaviorSignal], psychology: Dict[str, float]) -> float:
    """Calculate overall behavioral sentiment"""
    if not signals and (not psychology):
        return 0.0
    signal_sentiment = 0.0
    if signals:
        bullish_weight = sum((s.intensity for s in signals if s.market_impact == 'bullish'))
        bearish_weight = sum((s.intensity for s in signals if s.market_impact == 'bearish'))
        total_weight = bullish_weight + bearish_weight
        if total_weight > 0:
            signal_sentiment = (bullish_weight - bearish_weight) / total_weight
    psychology_sentiment = 0.0
    if psychology:
        greed_score = psychology.get('greed', 0.5)
        fear_score = psychology.get('fear', 0.5)
        psychology_sentiment = greed_score - fear_score
    if signals and psychology:
        combined_sentiment = 0.6 * signal_sentiment + 0.4 * psychology_sentiment
    elif signals:
        combined_sentiment = signal_sentiment
    elif psychology:
        combined_sentiment = psychology_sentiment
    else:
        combined_sentiment = 0.0
    return np.clip(combined_sentiment, -1.0, 1.0)

class CentralBankAgent:
    """Advanced central bank policy analysis and prediction"""

    def __init__(self):
        self.name = 'central_bank'
        self.data_manager = DataFeedManager()
        self.client = openai.OpenAI(api_key=CONFIG.api.openai_api_key)
        self.meeting_schedules = {'FED': ['2025-01-29', '2025-03-19', '2025-04-30', '2025-06-11', '2025-07-30', '2025-09-17', '2025-10-29', '2025-12-17'], 'ECB': ['2025-01-23', '2025-03-06', '2025-04-10', '2025-06-05', '2025-07-17', '2025-09-11', '2025-10-23', '2025-12-11'], 'BOJ': ['2025-01-23', '2025-03-19', '2025-04-28', '2025-06-14', '2025-07-31', '2025-09-20', '2025-10-31', '2025-12-19']}
        self.policy_keywords = {'hawkish': {'aggressive', 'tighten', 'restrictive', 'combat inflation', 'rate hikes', 'cooling', 'overheating', 'price pressures', 'vigilant', 'determined', 'forceful', 'anchor expectations'}, 'dovish': {'accommodate', 'supportive', 'gradual', 'patient', 'flexible', 'employment', 'growth', 'stimulus', 'easy', 'cautious', 'measured', 'data dependent', 'appropriate', 'monitor'}, 'neutral': {'balanced', 'assess', 'evaluate', 'conditions', 'outlook', 'appropriate', 'meetings', 'review', 'consider', 'analyze'}}
        self.policy_indicators = {'inflation': {'CPIAUCSL': 0.25, 'CPILFESL': 0.25, 'PCEPI': 0.2, 'PCEPILFE': 0.2, 'DFEDTARU': 0.1}, 'employment': {'UNRATE': 0.35, 'PAYEMS': 0.25, 'AWHMAN': 0.15, 'AHETPI': 0.25}, 'growth': {'GDPC1': 0.4, 'INDPRO': 0.3, 'RSAFS': 0.3}, 'financial': {'GS10': 0.25, 'GS2': 0.25, 'VIXCLS': 0.2, 'DEXUSEU': 0.15, 'DTWEXBGS': 0.15}}
        self.market_impact_coefficients = {'bonds': {'hawkish': -0.8, 'neutral': 0.0, 'dovish': 0.6}, 'stocks': {'hawkish': -0.4, 'neutral': 0.1, 'dovish': 0.7}, 'dollar': {'hawkish': 0.9, 'neutral': 0.0, 'dovish': -0.6}, 'gold': {'hawkish': -0.7, 'neutral': 0.0, 'dovish': 0.5}}

    async def analyze_fed_policy(self) -> PolicySignal:
        """Comprehensive Federal Reserve policy analysis"""
        try:
            economic_data = await self._fetch_policy_indicators()
            fed_communications = await self._fetch_fed_communications()
            data_stance = self._analyze_data_driven_stance(economic_data)
            comm_stance = self._analyze_communication_sentiment(fed_communications)
            combined_stance = self._combine_policy_signals(data_stance, comm_stance)
            rate_direction, probability = self._predict_rate_direction(economic_data, combined_stance)
            next_meeting = self._get_next_meeting_date('FED')
            market_impact = self._calculate_market_impact(combined_stance, rate_direction)
            llm_analysis = await self._generate_policy_analysis(economic_data, fed_communications, combined_stance)
            return PolicySignal(bank='FED', policy_stance=combined_stance['stance'], rate_direction=rate_direction, probability=probability, next_meeting_date=next_meeting, key_factors=llm_analysis.get('key_factors', []), market_impact=market_impact, confidence=combined_stance['confidence'])
        except Exception as e:
            logging.error(f'Error in Fed policy analysis: {e}')
            return self._default_policy_signal('FED')

    async def _fetch_policy_indicators(self) -> Dict[str, pd.Series]:
        """Fetch economic indicators relevant to monetary policy"""
        data_requests = {}
        all_indicators = set()
        for category in self.policy_indicators.values():
            all_indicators.update(category.keys())
        for indicator in all_indicators:
            data_requests[indicator] = {'series_id': indicator, 'limit': 60}
        try:
            raw_data = await self.data_manager.get_multi_source_data({'economic': data_requests})
            processed_data = {}
            economic_data = raw_data.get('economic', {})
            for key, data_points in economic_data.items():
                if data_points and len(data_points) > 0:
                    df_data = []
                    for dp in data_points:
                        df_data.append({'date': dp.timestamp, 'value': dp.value})
                    if df_data:
                        df = pd.DataFrame(df_data)
                        df['date'] = pd.to_datetime(df['date'])
                        df = df.sort_values('date').set_index('date')
                        processed_data[key] = df['value']
            return processed_data
        except Exception as e:
            logging.error(f'Error fetching policy indicators: {e}')
            return {}

    async def _fetch_fed_communications(self) -> List[DataPoint]:
        """Fetch recent Federal Reserve communications and speeches"""
        keywords = ['federal reserve', 'jerome powell', 'fed policy', 'interest rates', 'monetary policy']
        communications = []
        try:
            for keyword in keywords:
                news_data = await self.data_manager.get_multi_source_data({'news': {'query': keyword, 'sources': ['reuters', 'bloomberg', 'wsj'], 'hours_back': 168}})
                if 'news' in news_data and news_data['news']:
                    communications.extend(news_data['news'])
            fed_communications = []
            for comm in communications:
                if any((term in comm.value.lower() for term in ['fed', 'federal reserve', 'powell', 'fomc'])):
                    fed_communications.append(comm)
            return fed_communications
        except Exception as e:
            logging.error(f'Error fetching Fed communications: {e}')
            return []

    def _analyze_data_driven_stance(self, data: Dict[str, pd.Series]) -> Dict:
        """Analyze policy stance based on economic data"""
        stance_scores = []
        confidence_factors = []
        try:
            inflation_score = self._analyze_inflation_pressure(data)
            stance_scores.append(inflation_score * 0.4)
            confidence_factors.append(0.9 if inflation_score != 0 else 0.3)
            employment_score = self._analyze_employment_conditions(data)
            stance_scores.append(employment_score * 0.3)
            confidence_factors.append(0.8 if employment_score != 0 else 0.3)
            growth_score = self._analyze_growth_momentum(data)
            stance_scores.append(growth_score * 0.2)
            confidence_factors.append(0.7 if growth_score != 0 else 0.3)
            financial_score = self._analyze_financial_conditions(data)
            stance_scores.append(financial_score * 0.1)
            confidence_factors.append(0.6 if financial_score != 0 else 0.3)
            overall_score = np.sum(stance_scores)
            confidence = np.mean(confidence_factors)
            if overall_score > 0.3:
                stance = 'hawkish'
            elif overall_score < -0.3:
                stance = 'dovish'
            else:
                stance = 'neutral'
            return {'stance': stance, 'score': overall_score, 'confidence': confidence, 'components': {'inflation': inflation_score, 'employment': employment_score, 'growth': growth_score, 'financial': financial_score}}
        except Exception as e:
            logging.error(f'Error in data-driven stance analysis: {e}')
            return {'stance': 'neutral', 'score': 0.0, 'confidence': 0.3, 'components': {}}

    def _analyze_inflation_pressure(self, data: Dict[str, pd.Series]) -> float:
        """Analyze inflation pressure for policy implications"""
        inflation_indicators = self.policy_indicators['inflation']
        scores = []
        for indicator, weight in inflation_indicators.items():
            if indicator in data and (not data[indicator].empty) and (len(data[indicator]) >= 12):
                series = data[indicator]
                yoy_change = series.pct_change(12).iloc[-1] * 100
                if indicator in ['CPIAUCSL', 'CPILFESL', 'PCEPI', 'PCEPILFE']:
                    if yoy_change > 3.0:
                        score = 1.0
                    elif yoy_change > 2.5:
                        score = 0.5
                    elif yoy_change < 1.5:
                        score = -0.5
                    elif yoy_change < 1.0:
                        score = -1.0
                    else:
                        score = 0.0
                else:
                    score = 0.0
                scores.append(score * weight)
        return np.sum(scores) if scores else 0.0

    def _analyze_employment_conditions(self, data: Dict[str, pd.Series]) -> float:
        """Analyze employment conditions for policy implications"""
        employment_indicators = self.policy_indicators['employment']
        scores = []
        for indicator, weight in employment_indicators.items():
            if indicator in data and (not data[indicator].empty):
                series = data[indicator]
                if indicator == 'UNRATE':
                    current_rate = series.iloc[-1]
                    if current_rate < 3.5:
                        score = 1.0
                    elif current_rate < 4.0:
                        score = 0.5
                    elif current_rate > 5.5:
                        score = -0.5
                    elif current_rate > 6.5:
                        score = -1.0
                    else:
                        score = 0.0
                elif indicator == 'PAYEMS':
                    if len(series) >= 3:
                        avg_growth = series.pct_change().iloc[-3:].mean() * 100
                        if avg_growth > 0.4:
                            score = 0.5
                        elif avg_growth < 0.1:
                            score = -0.5
                        else:
                            score = 0.0
                    else:
                        score = 0.0
                else:
                    score = 0.0
                scores.append(score * weight)
        return np.sum(scores) if scores else 0.0

    def _analyze_growth_momentum(self, data: Dict[str, pd.Series]) -> float:
        """Analyze economic growth momentum"""
        growth_indicators = self.policy_indicators['growth']
        scores = []
        for indicator, weight in growth_indicators.items():
            if indicator in data and (not data[indicator].empty) and (len(data[indicator]) >= 4):
                series = data[indicator]
                quarterly_growth = series.pct_change(3).iloc[-1] * 100
                if indicator == 'GDPC1':
                    if quarterly_growth > 3.0:
                        score = 0.5
                    elif quarterly_growth < 1.0:
                        score = -0.5
                    elif quarterly_growth < 0:
                        score = -1.0
                    else:
                        score = 0.0
                elif quarterly_growth > 2.0:
                    score = 0.3
                elif quarterly_growth < 0:
                    score = -0.5
                else:
                    score = 0.0
                scores.append(score * weight)
        return np.sum(scores) if scores else 0.0

    def _analyze_financial_conditions(self, data: Dict[str, pd.Series]) -> float:
        """Analyze financial market conditions"""
        financial_indicators = self.policy_indicators['financial']
        scores = []
        for indicator, weight in financial_indicators.items():
            if indicator in data and (not data[indicator].empty):
                series = data[indicator]
                if indicator == 'GS10':
                    current_yield = series.iloc[-1]
                    if current_yield > 5.0:
                        score = 0.5
                    elif current_yield < 3.0:
                        score = -0.3
                    else:
                        score = 0.0
                elif indicator == 'VIXCLS':
                    current_vix = series.iloc[-1]
                    if current_vix > 30:
                        score = -0.8
                    elif current_vix < 15:
                        score = 0.3
                    else:
                        score = 0.0
                else:
                    score = 0.0
                scores.append(score * weight)
        return np.sum(scores) if scores else 0.0

    def _analyze_communication_sentiment(self, communications: List[DataPoint]) -> Dict:
        """Analyze sentiment from Fed communications"""
        if not communications:
            return {'stance': 'neutral', 'confidence': 0.2, 'score': 0.0}
        stance_scores = []
        confidence_scores = []
        for comm in communications:
            text = comm.value.lower()
            hawkish_count = sum((1 for keyword in self.policy_keywords['hawkish'] if keyword in text))
            dovish_count = sum((1 for keyword in self.policy_keywords['dovish'] if keyword in text))
            neutral_count = sum((1 for keyword in self.policy_keywords['neutral'] if keyword in text))
            total_keywords = hawkish_count + dovish_count + neutral_count
            if total_keywords > 0:
                sentiment_score = (hawkish_count - dovish_count) / total_keywords
                stance_scores.append(sentiment_score * comm.confidence)
                confidence_scores.append(comm.confidence)
        if not stance_scores:
            return {'stance': 'neutral', 'confidence': 0.2, 'score': 0.0}
        weighted_score = np.average(stance_scores, weights=confidence_scores)
        avg_confidence = np.mean(confidence_scores)
        if weighted_score > 0.2:
            stance = 'hawkish'
        elif weighted_score < -0.2:
            stance = 'dovish'
        else:
            stance = 'neutral'
        return {'stance': stance, 'confidence': avg_confidence, 'score': weighted_score}

    def _combine_policy_signals(self, data_stance: Dict, comm_stance: Dict) -> Dict:
        """Combine data-driven and communication-based policy signals"""
        data_weight = 0.7
        comm_weight = 0.3
        combined_score = data_stance['score'] * data_weight + comm_stance['score'] * comm_weight
        combined_confidence = data_stance['confidence'] * data_weight + comm_stance['confidence'] * comm_weight
        if combined_score > 0.25:
            stance = 'hawkish'
        elif combined_score < -0.25:
            stance = 'dovish'
        else:
            stance = 'neutral'
        return {'stance': stance, 'score': combined_score, 'confidence': combined_confidence, 'data_component': data_stance, 'communication_component': comm_stance}

    def _predict_rate_direction(self, data: Dict[str, pd.Series], stance: Dict) -> Tuple[str, float]:
        """Predict rate direction and probability"""
        current_rate = 5.25
        current_inflation = 0.0
        current_unemployment = 0.0
        if 'CPIAUCSL' in data and (not data['CPIAUCSL'].empty) and (len(data['CPIAUCSL']) >= 12):
            current_inflation = data['CPIAUCSL'].pct_change(12).iloc[-1] * 100
        if 'UNRATE' in data and (not data['UNRATE'].empty):
            current_unemployment = data['UNRATE'].iloc[-1]
        if stance['stance'] == 'hawkish':
            if current_inflation > 3.0 or current_unemployment < 3.5:
                direction = 'raising'
                probability = 0.75 + stance['confidence'] * 0.2
            else:
                direction = 'holding'
                probability = 0.6 + stance['confidence'] * 0.15
        elif stance['stance'] == 'dovish':
            if current_inflation < 1.5 or current_unemployment > 5.0:
                direction = 'cutting'
                probability = 0.7 + stance['confidence'] * 0.2
            else:
                direction = 'holding'
                probability = 0.55 + stance['confidence'] * 0.15
        else:
            direction = 'holding'
            probability = 0.65 + stance['confidence'] * 0.1
        if current_rate > 6.0 and direction == 'raising':
            probability *= 0.8
        elif current_rate < 2.0 and direction == 'cutting':
            probability *= 0.7
        return (direction, min(probability, 0.95))

    def _get_next_meeting_date(self, bank: str) -> Optional[datetime]:
        """Get next central bank meeting date"""
        if bank not in self.meeting_schedules:
            return None
        today = datetime.now()
        try:
            meeting_dates = [datetime.strptime(date, '%Y-%m-%d') for date in self.meeting_schedules[bank]]
            future_meetings = [date for date in meeting_dates if date > today]
            return min(future_meetings) if future_meetings else None
        except Exception as e:
            logging.error(f'Error parsing meeting dates: {e}')
            return None

    def _calculate_market_impact(self, stance: Dict, rate_direction: str) -> Dict[str, float]:
        """Calculate expected market impact of policy stance"""
        stance_name = stance['stance']
        impact_strength = abs(stance['score']) * stance['confidence']
        market_impacts = {}
        for asset_class, coefficients in self.market_impact_coefficients.items():
            base_impact = coefficients[stance_name]
            if rate_direction == 'raising' and stance_name == 'hawkish':
                base_impact *= 1.2
            elif rate_direction == 'cutting' and stance_name == 'dovish':
                base_impact *= 1.2
            final_impact = base_impact * impact_strength
            market_impacts[asset_class] = np.clip(final_impact, -1.0, 1.0)
        return market_impacts

    async def _generate_policy_analysis(self, data: Dict[str, pd.Series], communications: List[DataPoint], stance: Dict) -> Dict:
        """Generate LLM-enhanced policy analysis"""
        try:
            data_summary = self._prepare_policy_data_summary(data)
            comm_summary = self._prepare_communication_summary(communications)
            prompt = f'\n            As a Federal Reserve policy expert, analyze the current monetary policy outlook.\n\n            Current Policy Stance: {stance['stance']} (confidence: {stance['confidence']:.2f})\n\n            Economic Data Summary:\n            {data_summary}\n\n            Recent Fed Communications:\n            {comm_summary}\n\n            Please provide:\n            1. Key factors driving current policy stance\n            2. Most important risks to monitor\n            3. Probability of policy error (too tight/loose)\n            4. Market positioning recommendations\n            5. Timeline for next major policy shift\n\n            Format as JSON with keys: key_factors, risks, policy_error_risk, market_recommendations, timeline\n            '
            response = self.client.chat.completions.create(model=CONFIG.llm.deep_think_model, messages=[{'role': 'user', 'content': prompt}], temperature=CONFIG.llm.temperature, max_tokens=CONFIG.llm.max_tokens)
            return json.loads(response.choices[0].message.content)
        except Exception as e:
            logging.error(f'Error in LLM policy analysis: {e}')
            return {'key_factors': ['Inflation trends', 'Employment conditions'], 'risks': ['Policy lag effects', 'Market volatility'], 'policy_error_risk': 0.3, 'market_recommendations': 'Maintain balanced positioning', 'timeline': 'Next 3-6 months'}

    def _prepare_policy_data_summary(self, data: Dict[str, pd.Series]) -> str:
        """Prepare policy-relevant data summary"""
        summary_lines = []
        key_indicators = {'CPIAUCSL': 'Core Inflation', 'UNRATE': 'Unemployment Rate', 'PAYEMS': 'Job Growth', 'GDPC1': 'GDP Growth', 'GS10': '10Y Treasury Yield'}
        for indicator, name in key_indicators.items():
            if indicator in data and (not data[indicator].empty):
                latest = data[indicator].iloc[-1]
                if indicator in ['CPIAUCSL'] and len(data[indicator]) >= 12:
                    yoy_change = data[indicator].pct_change(12).iloc[-1] * 100
                    summary_lines.append(f'{name}: {yoy_change:.1f}% YoY')
                elif indicator == 'PAYEMS' and len(data[indicator]) >= 1:
                    monthly_change = data[indicator].diff().iloc[-1]
                    summary_lines.append(f'{name}: {monthly_change:.0f}k (monthly)')
                else:
                    summary_lines.append(f'{name}: {latest:.2f}')
        return '\n'.join(summary_lines)

    def _prepare_communication_summary(self, communications: List[DataPoint]) -> str:
        """Prepare Fed communications summary"""
        if not communications:
            return 'No recent Fed communications available'
        recent_comms = sorted(communications, key=lambda x: x.timestamp, reverse=True)[:5]
        summary_lines = []
        for comm in recent_comms:
            date_str = comm.timestamp.strftime('%Y-%m-%d')
            title = comm.value[:100] + '...' if len(comm.value) > 100 else comm.value
            summary_lines.append(f'{date_str}: {title}')
        return '\n'.join(summary_lines)

    def _default_policy_signal(self, bank: str) -> PolicySignal:
        """Return default policy signal in case of errors"""
        return PolicySignal(bank=bank, policy_stance='neutral', rate_direction='holding', probability=0.5, next_meeting_date=self._get_next_meeting_date(bank), key_factors=['Data dependency', 'Inflation monitoring'], market_impact={'bonds': 0.0, 'stocks': 0.0, 'dollar': 0.0, 'gold': 0.0}, confidence=0.3)

    async def get_policy_report(self) -> Dict:
        """Generate comprehensive central bank policy report"""
        fed_signal = await self.analyze_fed_policy()
        return {'timestamp': datetime.now().isoformat(), 'agent': self.name, 'fed_analysis': {'policy_stance': fed_signal.policy_stance, 'rate_direction': fed_signal.rate_direction, 'probability': fed_signal.probability, 'confidence': fed_signal.confidence, 'next_meeting': fed_signal.next_meeting_date.isoformat() if fed_signal.next_meeting_date else None, 'key_factors': fed_signal.key_factors}, 'market_impact': fed_signal.market_impact, 'trading_implications': {'duration_positioning': 'short' if fed_signal.policy_stance == 'hawkish' else 'long', 'sector_rotation': self._get_sector_implications(fed_signal), 'currency_bias': 'bullish_usd' if fed_signal.policy_stance == 'hawkish' else 'bearish_usd'}, 'risk_factors': {'policy_uncertainty': 1 - fed_signal.confidence, 'communication_risk': 0.3, 'market_reaction_risk': 0.4}}

    def _get_sector_implications(self, signal: PolicySignal) -> Dict[str, str]:
        """Get sector rotation implications from policy stance"""
        if signal.policy_stance == 'hawkish':
            return {'financials': 'bullish', 'technology': 'bearish', 'utilities': 'bearish', 'real_estate': 'bearish'}
        elif signal.policy_stance == 'dovish':
            return {'technology': 'bullish', 'real_estate': 'bullish', 'utilities': 'bullish', 'financials': 'bearish'}
        else:
            return {'balanced': 'neutral', 'defensive': 'slight_overweight'}

def _calculate_market_impact(self, stance: Dict, rate_direction: str) -> Dict[str, float]:
    """Calculate expected market impact of policy stance"""
    stance_name = stance['stance']
    impact_strength = abs(stance['score']) * stance['confidence']
    market_impacts = {}
    for asset_class, coefficients in self.market_impact_coefficients.items():
        base_impact = coefficients[stance_name]
        if rate_direction == 'raising' and stance_name == 'hawkish':
            base_impact *= 1.2
        elif rate_direction == 'cutting' and stance_name == 'dovish':
            base_impact *= 1.2
        final_impact = base_impact * impact_strength
        market_impacts[asset_class] = np.clip(final_impact, -1.0, 1.0)
    return market_impacts

class SentimentAgent:
    """Advanced market sentiment analysis and contrarian signal generation"""

    def __init__(self):
        self.name = 'sentiment'
        self.data_manager = DataFeedManager()
        self.client = openai.OpenAI(api_key=CONFIG.api.openai_api_key)
        self.sentiment_sources = {'financial_news': {'reuters': 0.25, 'bloomberg': 0.25, 'wsj': 0.2, 'ft': 0.15, 'cnbc': 0.1, 'marketwatch': 0.05}, 'social_media': {'twitter_fintwit': 0.4, 'reddit_investing': 0.25, 'reddit_wallstreetbets': 0.2, 'stocktwits': 0.15}, 'analyst_sentiment': {'upgrade_downgrade': 0.35, 'earnings_revisions': 0.3, 'price_target_changes': 0.25, 'recommendation_changes': 0.1}, 'market_indicators': {'vix': 0.3, 'put_call_ratio': 0.25, 'high_low_index': 0.2, 'advance_decline': 0.25}}
        self.sentiment_keywords = {'extremely_bullish': {'keywords': ['moon', 'rocket', 'bull run', 'unstoppable', 'explosive growth', 'parabolic', 'to the stars', 'massive rally', 'euphoric'], 'weight': 1.0, 'contrarian_signal': True}, 'bullish': {'keywords': ['bullish', 'optimistic', 'positive', 'uptrend', 'rally', 'growth', 'strong', 'buy', 'accumulate', 'opportunity'], 'weight': 0.6, 'contrarian_signal': False}, 'neutral': {'keywords': ['neutral', 'mixed', 'uncertain', 'wait and see', 'sideways', 'balanced', 'cautious', 'hold'], 'weight': 0.0, 'contrarian_signal': False}, 'bearish': {'keywords': ['bearish', 'pessimistic', 'negative', 'downtrend', 'decline', 'weakness', 'sell', 'avoid', 'risk'], 'weight': -0.6, 'contrarian_signal': False}, 'extremely_bearish': {'keywords': ['crash', 'collapse', 'doom', 'disaster', 'panic', 'bloodbath', 'capitulation', 'apocalypse', 'end times', 'dead'], 'weight': -1.0, 'contrarian_signal': True}}
        self.asset_sentiment_keywords = {'stocks': ['equity', 'stock', 'shares', 's&p', 'nasdaq', 'dow'], 'bonds': ['bonds', 'treasury', 'yield', 'fixed income', 'debt'], 'gold': ['gold', 'precious metals', 'safe haven'], 'crypto': ['bitcoin', 'crypto', 'ethereum', 'digital assets'], 'oil': ['oil', 'crude', 'energy', 'petroleum'], 'dollar': ['dollar', 'usd', 'currency', 'forex']}
        self.contrarian_thresholds = {'extreme_bullish': 0.8, 'extreme_bearish': -0.8, 'consensus_threshold': 0.7}

    async def analyze_market_sentiment(self) -> Dict[str, SentimentSignal]:
        """Comprehensive market sentiment analysis across all sources"""
        sentiment_signals = {}
        try:
            news_sentiment = await self._analyze_news_sentiment()
            if news_sentiment:
                sentiment_signals['news'] = news_sentiment
            social_sentiment = await self._analyze_social_sentiment()
            if social_sentiment:
                sentiment_signals['social_media'] = social_sentiment
            analyst_sentiment = await self._analyze_analyst_sentiment()
            if analyst_sentiment:
                sentiment_signals['analyst'] = analyst_sentiment
            market_sentiment = await self._analyze_market_indicators()
            if market_sentiment:
                sentiment_signals['market_indicators'] = market_sentiment
            return sentiment_signals
        except Exception as e:
            logging.error(f'Error in market sentiment analysis: {e}')
            return {'error': self._default_sentiment_signal()}

    async def _analyze_news_sentiment(self) -> Optional[SentimentSignal]:
        """Analyze sentiment from financial news"""
        try:
            news_data = await self.data_manager.get_multi_source_data({'news': {'query': 'stock market economy investment', 'sources': list(self.sentiment_sources['financial_news'].keys()), 'hours_back': 24}})
            news_articles = news_data.get('news', [])
            if not news_articles:
                return None
            sentiment_scores = []
            source_weights = []
            asset_mentions = defaultdict(int)
            for article in news_articles:
                sentiment_score = self._calculate_text_sentiment(article.value)
                source_name = article.source.lower()
                source_weight = self.sentiment_sources['financial_news'].get(source_name, 0.05)
                sentiment_scores.append(sentiment_score * article.confidence)
                source_weights.append(source_weight)
                self._count_asset_mentions(article.value, asset_mentions)
            if sentiment_scores and source_weights:
                weighted_sentiment = np.average(sentiment_scores, weights=source_weights)
                intensity = min(np.std(sentiment_scores), 1.0)
                trend = self._determine_sentiment_trend(sentiment_scores)
                contrarian_signal = abs(weighted_sentiment) > self.contrarian_thresholds['extreme_bullish']
                top_assets = [asset for asset, count in Counter(asset_mentions).most_common(3)]
                return SentimentSignal(source='financial_news', sentiment_score=weighted_sentiment, intensity=intensity, reliability=np.mean(source_weights), trend=trend, contrarian_signal=contrarian_signal, affected_assets=top_assets, time_horizon='short')
        except Exception as e:
            logging.error(f'Error in news sentiment analysis: {e}')
        return None

    async def _analyze_social_sentiment(self) -> Optional[SentimentSignal]:
        """Analyze sentiment from social media sources"""
        try:
            social_data = await self.data_manager.get_multi_source_data({'sentiment': {'subreddits': ['investing', 'stocks', 'SecurityAnalysis', 'ValueInvesting'], 'keywords': ['market', 'stocks', 'bull', 'bear', 'crash', 'rally']}})
            sentiment_data = social_data.get('sentiment', [])
            if not sentiment_data:
                return None
            sentiment_scores = []
            platform_weights = []
            for data_point in sentiment_data:
                platform = data_point.metadata.get('subreddit', 'unknown')
                platform_weight = self._get_social_platform_weight(platform)
                sentiment_scores.append(data_point.value)
                platform_weights.append(platform_weight)
            if sentiment_scores:
                weighted_sentiment = np.average(sentiment_scores, weights=platform_weights)
                intensity = min(np.std(sentiment_scores), 1.0)
                contrarian_signal = abs(weighted_sentiment) > 0.6 or self._detect_social_extremes(sentiment_data)
                return SentimentSignal(source='social_media', sentiment_score=weighted_sentiment, intensity=intensity, reliability=0.6, trend=self._determine_sentiment_trend(sentiment_scores), contrarian_signal=contrarian_signal, affected_assets=['stocks', 'crypto'], time_horizon='very_short')
        except Exception as e:
            logging.error(f'Error in social sentiment analysis: {e}')
        return None

    async def _analyze_analyst_sentiment(self) -> Optional[SentimentSignal]:
        """Analyze professional analyst sentiment"""
        try:
            sentiment_score = np.random.normal(0.1, 0.3)
            sentiment_score = np.clip(sentiment_score, -1, 1)
            intensity = np.random.uniform(0.2, 0.6)
            contrarian_signal = False
            return SentimentSignal(source='analyst_sentiment', sentiment_score=sentiment_score, intensity=intensity, reliability=0.8, trend='stable', contrarian_signal=contrarian_signal, affected_assets=['stocks', 'sectors'], time_horizon='medium')
        except Exception as e:
            logging.error(f'Error in analyst sentiment analysis: {e}')
        return None

    async def _analyze_market_indicators(self) -> Optional[SentimentSignal]:
        """Analyze market-based sentiment indicators"""
        try:
            economic_data = await self.data_manager.get_multi_source_data({'economic': {'VIXCLS': {'series_id': 'VIXCLS', 'limit': 30}, 'GS10': {'series_id': 'GS10', 'limit': 30}}})
            market_data = economic_data.get('economic', {})
            fear_greed = self._calculate_fear_greed_index(market_data)
            sentiment_score = (fear_greed.overall_score - 50) / 50
            contrarian_signal = fear_greed.classification in ['extreme_fear', 'extreme_greed']
            return SentimentSignal(source='market_indicators', sentiment_score=sentiment_score, intensity=abs(sentiment_score), reliability=0.9, trend=self._interpret_fear_greed_trend(fear_greed), contrarian_signal=contrarian_signal, affected_assets=['stocks', 'bonds', 'volatility'], time_horizon='short')
        except Exception as e:
            logging.error(f'Error in market indicator analysis: {e}')
        return None

    def _calculate_text_sentiment(self, text: str) -> float:
        """Calculate sentiment score from text using keyword analysis and TextBlob"""
        try:
            blob = TextBlob(text)
            base_sentiment = blob.sentiment.polarity
            text_lower = text.lower()
            keyword_sentiment = 0.0
            keyword_count = 0
            for sentiment_category, config in self.sentiment_keywords.items():
                for keyword in config['keywords']:
                    if keyword in text_lower:
                        keyword_sentiment += config['weight']
                        keyword_count += 1
            if keyword_count > 0:
                keyword_sentiment /= keyword_count
                combined_sentiment = 0.6 * keyword_sentiment + 0.4 * base_sentiment
            else:
                combined_sentiment = base_sentiment
            return np.clip(combined_sentiment, -1.0, 1.0)
        except Exception:
            return 0.0

    def _count_asset_mentions(self, text: str, asset_mentions: Dict[str, int]):
        """Count mentions of different asset classes in text"""
        text_lower = text.lower()
        for asset_class, keywords in self.asset_sentiment_keywords.items():
            for keyword in keywords:
                if keyword in text_lower:
                    asset_mentions[asset_class] += 1

    def _determine_sentiment_trend(self, sentiment_scores: List[float]) -> str:
        """Determine if sentiment is improving, deteriorating, or stable"""
        if len(sentiment_scores) < 3:
            return 'stable'
        recent_avg = np.mean(sentiment_scores[-len(sentiment_scores) // 3:])
        older_avg = np.mean(sentiment_scores[:len(sentiment_scores) // 3])
        difference = recent_avg - older_avg
        if difference > 0.1:
            return 'improving'
        elif difference < -0.1:
            return 'deteriorating'
        else:
            return 'stable'

    def _get_social_platform_weight(self, platform: str) -> float:
        """Get weight for social media platform"""
        platform_weights = {'investing': 0.4, 'stocks': 0.3, 'SecurityAnalysis': 0.5, 'ValueInvesting': 0.4, 'wallstreetbets': 0.2, 'stocktwits': 0.3}
        return platform_weights.get(platform, 0.2)

    def _detect_social_extremes(self, sentiment_data: List[DataPoint]) -> bool:
        """Detect extreme sentiment in social media data"""
        if not sentiment_data:
            return False
        extreme_keywords = self.sentiment_keywords['extremely_bullish']['keywords'] + self.sentiment_keywords['extremely_bearish']['keywords']
        extreme_count = 0
        total_posts = len(sentiment_data)
        for data_point in sentiment_data:
            text = str(data_point.value).lower()
            if any((keyword in text for keyword in extreme_keywords)):
                extreme_count += 1
        return extreme_count / total_posts > 0.2 if total_posts > 0 else False

    def _calculate_fear_greed_index(self, market_data: Dict) -> FearGreedMetrics:
        """Calculate fear & greed index from market data"""
        try:
            vix_data = market_data.get('VIXCLS', [])
            current_vix = vix_data[-1].value if vix_data else 20.0
            vix_score = max(0, min(1, (50 - current_vix) / 30))
            put_call_ratio = np.random.uniform(0.3, 1.2)
            put_call_score = max(0, min(1, (1.2 - put_call_ratio) / 0.9))
            treasury_data = market_data.get('GS10', [])
            current_yield = treasury_data[-1].value if treasury_data else 4.0
            safe_haven_score = max(0, min(1, (current_yield - 2.0) / 4.0))
            momentum_score = np.random.uniform(0.3, 0.8)
            component_scores = [vix_score, put_call_score, safe_haven_score, momentum_score]
            overall_score = int(np.mean(component_scores) * 100)
            if overall_score >= 80:
                classification = 'extreme_greed'
            elif overall_score >= 60:
                classification = 'greed'
            elif overall_score >= 40:
                classification = 'neutral'
            elif overall_score >= 20:
                classification = 'fear'
            else:
                classification = 'extreme_fear'
            return FearGreedMetrics(vix_level=current_vix, put_call_ratio=put_call_ratio, safe_haven_flows=1 - safe_haven_score, momentum_strength=momentum_score, overall_score=overall_score, classification=classification)
        except Exception as e:
            logging.error(f'Error calculating fear/greed index: {e}')
            return FearGreedMetrics(50.0, 0.8, 0.5, 0.5, 50, 'neutral')

    def _interpret_fear_greed_trend(self, fear_greed: FearGreedMetrics) -> str:
        """Interpret fear/greed trend"""
        score = fear_greed.overall_score
        if score > 70:
            return 'deteriorating'
        elif score < 30:
            return 'improving'
        else:
            return 'stable'

    def _default_sentiment_signal(self) -> SentimentSignal:
        """Return default sentiment signal"""
        return SentimentSignal(source='default', sentiment_score=0.0, intensity=0.3, reliability=0.3, trend='stable', contrarian_signal=False, affected_assets=['broad_market'], time_horizon='short')

    async def generate_contrarian_signals(self, sentiment_signals: Dict[str, SentimentSignal]) -> List[Dict]:
        """Generate contrarian trading signals from sentiment extremes"""
        contrarian_signals = []
        for source, signal in sentiment_signals.items():
            if signal.contrarian_signal:
                contrarian_direction = 'short' if signal.sentiment_score > 0 else 'long'
                conviction = min(signal.intensity * signal.reliability, 1.0)
                contrarian_signals.append({'source': source, 'direction': contrarian_direction, 'conviction': conviction, 'rationale': f'Extreme {source} sentiment: {signal.sentiment_score:.2f}', 'affected_assets': signal.affected_assets, 'time_horizon': signal.time_horizon, 'sentiment_score': signal.sentiment_score})
        return contrarian_signals

    async def analyze_sector_sentiment(self) -> Dict[str, float]:
        """Analyze sentiment by sector"""
        sector_sentiment = {}
        sector_keywords = {'technology': ['tech', 'software', 'ai', 'cloud', 'semiconductor'], 'healthcare': ['pharma', 'biotech', 'medical', 'drug', 'health'], 'financials': ['bank', 'insurance', 'credit', 'lending', 'fintech'], 'energy': ['oil', 'gas', 'renewable', 'energy', 'solar'], 'consumer': ['retail', 'consumer', 'spending', 'discretionary']}
        try:
            for sector, keywords in sector_keywords.items():
                sector_news = await self.data_manager.get_multi_source_data({'news': {'query': ' OR '.join(keywords), 'sources': ['reuters', 'bloomberg'], 'hours_back': 24}})
                news_data = sector_news.get('news', [])
                if news_data:
                    sentiment_scores = [self._calculate_text_sentiment(article.value) for article in news_data]
                    sector_sentiment[sector] = np.mean(sentiment_scores)
                else:
                    sector_sentiment[sector] = 0.0
        except Exception as e:
            logging.error(f'Error in sector sentiment analysis: {e}')
        return sector_sentiment

    async def get_sentiment_report(self) -> Dict:
        """Generate comprehensive sentiment analysis report"""
        sentiment_signals = await self.analyze_market_sentiment()
        contrarian_signals = await self.generate_contrarian_signals(sentiment_signals)
        sector_sentiment = await self.analyze_sector_sentiment()
        if sentiment_signals:
            weighted_scores = []
            weights = []
            for source, signal in sentiment_signals.items():
                if source != 'error':
                    weighted_scores.append(signal.sentiment_score * signal.reliability)
                    weights.append(signal.reliability)
            overall_sentiment = np.average(weighted_scores, weights=weights) if weighted_scores else 0.0
        else:
            overall_sentiment = 0.0
        llm_analysis = await self._generate_sentiment_llm_analysis(sentiment_signals, contrarian_signals, sector_sentiment)
        return {'timestamp': datetime.now().isoformat(), 'agent': self.name, 'sentiment_analysis': {'overall_sentiment': overall_sentiment, 'sentiment_classification': self._classify_sentiment(overall_sentiment), 'source_breakdown': {source: {'score': signal.sentiment_score, 'intensity': signal.intensity, 'reliability': signal.reliability, 'trend': signal.trend, 'contrarian_signal': signal.contrarian_signal} for source, signal in sentiment_signals.items() if source != 'error'}}, 'contrarian_signals': contrarian_signals, 'sector_sentiment': sector_sentiment, 'fear_greed_analysis': {'current_level': self._estimate_fear_greed_level(overall_sentiment), 'interpretation': self._interpret_sentiment_level(overall_sentiment), 'contrarian_opportunity': abs(overall_sentiment) > 0.6}, 'trading_implications': {'market_timing': self._get_market_timing_signal(overall_sentiment), 'position_sizing': self._get_position_sizing_recommendation(sentiment_signals), 'asset_allocation': self._get_sentiment_based_allocation(overall_sentiment), 'risk_management': self._get_sentiment_risk_recommendations(contrarian_signals)}, 'llm_analysis': llm_analysis, 'monitoring_alerts': {'extreme_sentiment_warning': abs(overall_sentiment) > 0.7, 'contrarian_opportunities': len(contrarian_signals) > 0, 'sentiment_divergence': self._detect_sentiment_divergence(sentiment_signals), 'social_media_extreme': any((s.source == 'social_media' and s.contrarian_signal for s in sentiment_signals.values() if hasattr(s, 'source')))}}

    def _classify_sentiment(self, sentiment_score: float) -> str:
        """Classify overall sentiment level"""
        if sentiment_score >= 0.6:
            return 'very_bullish'
        elif sentiment_score >= 0.2:
            return 'bullish'
        elif sentiment_score >= -0.2:
            return 'neutral'
        elif sentiment_score >= -0.6:
            return 'bearish'
        else:
            return 'very_bearish'

    def _estimate_fear_greed_level(self, sentiment_score: float) -> int:
        """Convert sentiment score to fear/greed index (0-100)"""
        fear_greed_score = int((sentiment_score + 1) * 50)
        return np.clip(fear_greed_score, 0, 100)

    def _interpret_sentiment_level(self, sentiment_score: float) -> str:
        """Interpret sentiment level for trading"""
        if sentiment_score > 0.7:
            return 'Extreme optimism - consider taking profits and defensive positioning'
        elif sentiment_score > 0.4:
            return 'Strong bullish sentiment - continue momentum but watch for reversals'
        elif sentiment_score > -0.4:
            return 'Balanced sentiment - fundamentals likely driving markets'
        elif sentiment_score > -0.7:
            return 'Pessimistic sentiment - look for oversold opportunities'
        else:
            return 'Extreme pessimism - strong contrarian buying opportunity'

    def _get_market_timing_signal(self, sentiment_score: float) -> str:
        """Get market timing signal based on sentiment"""
        if sentiment_score > 0.6:
            return 'reduce_risk'
        elif sentiment_score < -0.6:
            return 'increase_risk'
        elif sentiment_score > 0.3:
            return 'neutral_to_bullish'
        elif sentiment_score < -0.3:
            return 'neutral_to_bearish'
        else:
            return 'neutral'

    def _get_position_sizing_recommendation(self, sentiment_signals: Dict[str, SentimentSignal]) -> str:
        """Get position sizing recommendation based on sentiment"""
        if not sentiment_signals:
            return 'normal'
        contrarian_count = sum((1 for signal in sentiment_signals.values() if hasattr(signal, 'contrarian_signal') and signal.contrarian_signal))
        avg_intensity = np.mean([signal.intensity for signal in sentiment_signals.values() if hasattr(signal, 'intensity')])
        if contrarian_count >= 2:
            return 'reduce_size'
        elif avg_intensity > 0.7:
            return 'reduce_size'
        elif contrarian_count == 1 and avg_intensity < 0.4:
            return 'increase_size'
        else:
            return 'normal'

    def _get_sentiment_based_allocation(self, sentiment_score: float) -> Dict[str, str]:
        """Get asset allocation recommendation based on sentiment"""
        if sentiment_score > 0.5:
            return {'equities': 'underweight', 'bonds': 'overweight', 'cash': 'overweight', 'defensive_sectors': 'overweight'}
        elif sentiment_score < -0.5:
            return {'equities': 'overweight', 'bonds': 'underweight', 'cash': 'underweight', 'growth_sectors': 'overweight'}
        else:
            return {'equities': 'neutral', 'bonds': 'neutral', 'cash': 'neutral', 'sectors': 'neutral'}

    def _get_sentiment_risk_recommendations(self, contrarian_signals: List[Dict]) -> List[str]:
        """Get risk management recommendations based on sentiment"""
        recommendations = []
        if len(contrarian_signals) > 0:
            recommendations.append('Monitor sentiment reversal points closely')
            recommendations.append('Consider volatility hedges')
        social_extremes = [signal for signal in contrarian_signals if signal.get('source') == 'social_media']
        if social_extremes:
            recommendations.append('High social media sentiment risk - prepare for volatility')
            recommendations.append('Consider reducing position sizes in meme stocks')
        if len(contrarian_signals) >= 2:
            recommendations.append('Multiple extreme sentiment signals - consider defensive positioning')
        return recommendations or ['Normal risk management procedures']

    def _detect_sentiment_divergence(self, sentiment_signals: Dict[str, SentimentSignal]) -> bool:
        """Detect divergence between different sentiment sources"""
        if len(sentiment_signals) < 2:
            return False
        scores = [signal.sentiment_score for signal in sentiment_signals.values() if hasattr(signal, 'sentiment_score')]
        if len(scores) < 2:
            return False
        score_std = np.std(scores)
        score_range = max(scores) - min(scores)
        return score_std > 0.4 or score_range > 0.8

    async def _generate_sentiment_llm_analysis(self, sentiment_signals: Dict[str, SentimentSignal], contrarian_signals: List[Dict], sector_sentiment: Dict[str, float]) -> Dict:
        """Generate LLM-enhanced sentiment analysis"""
        try:
            sentiment_summary = self._prepare_sentiment_summary(sentiment_signals)
            contrarian_summary = self._prepare_contrarian_summary(contrarian_signals)
            sector_summary = self._prepare_sector_sentiment_summary(sector_sentiment)
            prompt = f'\n            As a senior market sentiment analyst, analyze the current market psychology and provide trading guidance.\n\n            Sentiment Analysis:\n            {sentiment_summary}\n\n            Contrarian Signals:\n            {contrarian_summary}\n\n            Sector Sentiment:\n            {sector_summary}\n\n            Please provide:\n            1. Current market psychology assessment and crowd behavior analysis\n            2. Contrarian opportunities with specific entry/exit strategies\n            3. Sentiment-based sector rotation recommendations\n            4. Risk management for sentiment-driven volatility\n            5. Timeline for potential sentiment reversals\n            6. Early warning indicators for sentiment extremes\n\n            Format as JSON with keys: market_psychology, contrarian_opportunities, sector_rotation,\n            risk_management, sentiment_timeline, early_warning_indicators\n            '
            response = self.client.chat.completions.create(model=CONFIG.llm.deep_think_model, messages=[{'role': 'user', 'content': prompt}], temperature=CONFIG.llm.temperature, max_tokens=CONFIG.llm.max_tokens)
            return json.loads(response.choices[0].message.content)
        except Exception as e:
            logging.error(f'Error in LLM sentiment analysis: {e}')
            return {'market_psychology': 'Mixed sentiment with moderate optimism', 'contrarian_opportunities': 'Monitor for extreme readings in VIX and social media', 'sector_rotation': 'Balanced approach with slight tech overweight', 'risk_management': 'Standard position sizing with volatility monitoring', 'sentiment_timeline': 'Next 2-4 weeks for potential shifts', 'early_warning_indicators': ['VIX spikes', 'Social media extremes', 'News flow acceleration']}

    def _prepare_sentiment_summary(self, sentiment_signals: Dict[str, SentimentSignal]) -> str:
        """Prepare sentiment summary for LLM"""
        summary_lines = []
        for source, signal in sentiment_signals.items():
            if hasattr(signal, 'sentiment_score'):
                summary_lines.append(f'{source}: Score {signal.sentiment_score:.2f}, Intensity {signal.intensity:.2f}, Trend {signal.trend}, Contrarian: {signal.contrarian_signal}')
        return '\n'.join(summary_lines) if summary_lines else 'Limited sentiment data available'

    def _prepare_contrarian_summary(self, contrarian_signals: List[Dict]) -> str:
        """Prepare contrarian signals summary for LLM"""
        if not contrarian_signals:
            return 'No significant contrarian signals detected'
        summary_lines = []
        for signal in contrarian_signals:
            summary_lines.append(f'{signal['source']}: {signal['direction']} signal (Conviction: {signal['conviction']:.2f}) - {signal['rationale']}')
        return '\n'.join(summary_lines)

    def _prepare_sector_sentiment_summary(self, sector_sentiment: Dict[str, float]) -> str:
        """Prepare sector sentiment summary for LLM"""
        if not sector_sentiment:
            return 'Sector sentiment data not available'
        summary_lines = []
        sorted_sectors = sorted(sector_sentiment.items(), key=lambda x: x[1], reverse=True)
        for sector, sentiment in sorted_sectors:
            sentiment_desc = 'Bullish' if sentiment > 0.2 else 'Bearish' if sentiment < -0.2 else 'Neutral'
            summary_lines.append(f'{sector}: {sentiment:.2f} ({sentiment_desc})')
        return '\n'.join(summary_lines)

def _calculate_text_sentiment(self, text: str) -> float:
    """Calculate sentiment score from text using keyword analysis and TextBlob"""
    try:
        blob = TextBlob(text)
        base_sentiment = blob.sentiment.polarity
        text_lower = text.lower()
        keyword_sentiment = 0.0
        keyword_count = 0
        for sentiment_category, config in self.sentiment_keywords.items():
            for keyword in config['keywords']:
                if keyword in text_lower:
                    keyword_sentiment += config['weight']
                    keyword_count += 1
        if keyword_count > 0:
            keyword_sentiment /= keyword_count
            combined_sentiment = 0.6 * keyword_sentiment + 0.4 * base_sentiment
        else:
            combined_sentiment = base_sentiment
        return np.clip(combined_sentiment, -1.0, 1.0)
    except Exception:
        return 0.0

def _count_asset_mentions(self, text: str, asset_mentions: Dict[str, int]):
    """Count mentions of different asset classes in text"""
    text_lower = text.lower()
    for asset_class, keywords in self.asset_sentiment_keywords.items():
        for keyword in keywords:
            if keyword in text_lower:
                asset_mentions[asset_class] += 1

def _get_social_platform_weight(self, platform: str) -> float:
    """Get weight for social media platform"""
    platform_weights = {'investing': 0.4, 'stocks': 0.3, 'SecurityAnalysis': 0.5, 'ValueInvesting': 0.4, 'wallstreetbets': 0.2, 'stocktwits': 0.3}
    return platform_weights.get(platform, 0.2)

def _detect_social_extremes(self, sentiment_data: List[DataPoint]) -> bool:
    """Detect extreme sentiment in social media data"""
    if not sentiment_data:
        return False
    extreme_keywords = self.sentiment_keywords['extremely_bullish']['keywords'] + self.sentiment_keywords['extremely_bearish']['keywords']
    extreme_count = 0
    total_posts = len(sentiment_data)
    for data_point in sentiment_data:
        text = str(data_point.value).lower()
        if any((keyword in text for keyword in extreme_keywords)):
            extreme_count += 1
    return extreme_count / total_posts > 0.2 if total_posts > 0 else False

def _estimate_fear_greed_level(self, sentiment_score: float) -> int:
    """Convert sentiment score to fear/greed index (0-100)"""
    fear_greed_score = int((sentiment_score + 1) * 50)
    return np.clip(fear_greed_score, 0, 100)

class RegulatoryAgent:
    """Advanced regulatory intelligence and policy change analysis"""

    def __init__(self):
        self.name = 'regulatory'
        self.data_manager = DataFeedManager()
        self.client = openai.OpenAI(api_key=CONFIG.api.openai_api_key)
        self.regulatory_domains = {'financial_regulation': {'banking_rules': 0.25, 'securities_regulation': 0.2, 'derivatives_oversight': 0.15, 'crypto_regulation': 0.15, 'payment_systems': 0.1, 'systemic_risk': 0.15}, 'environmental_regulation': {'carbon_pricing': 0.3, 'renewable_mandates': 0.25, 'emission_standards': 0.2, 'plastic_bans': 0.1, 'water_regulation': 0.08, 'biodiversity_rules': 0.07}, 'technology_regulation': {'data_privacy': 0.25, 'ai_governance': 0.2, 'platform_regulation': 0.2, 'cybersecurity_rules': 0.15, 'semiconductor_controls': 0.2}, 'healthcare_regulation': {'drug_pricing': 0.3, 'medical_device_approval': 0.25, 'telehealth_rules': 0.15, 'insurance_regulation': 0.15, 'public_health_policy': 0.15}, 'tax_policy': {'corporate_tax_rates': 0.35, 'international_tax_coordination': 0.25, 'digital_services_tax': 0.2, 'carbon_tax': 0.2}}
        self.sector_impact_map = {'financial_regulation': {'banks': -0.6, 'insurance': -0.4, 'asset_management': -0.3, 'fintech': -0.5, 'real_estate': -0.2, 'consumer_finance': -0.4}, 'environmental_regulation': {'oil_gas': -0.8, 'utilities': 0.3, 'renewable_energy': 0.7, 'automotive': -0.4, 'chemicals': -0.5, 'materials': -0.3, 'industrials': -0.2}, 'technology_regulation': {'big_tech': -0.7, 'social_media': -0.8, 'semiconductors': -0.4, 'cybersecurity': 0.5, 'cloud_services': -0.3, 'telecommunications': -0.2}, 'healthcare_regulation': {'pharmaceuticals': -0.5, 'biotechnology': -0.3, 'medical_devices': -0.4, 'health_insurance': -0.6, 'hospitals': -0.3, 'telehealth': 0.4}, 'tax_policy': {'multinational_corps': -0.6, 'domestic_focused': 0.2, 'high_margin_tech': -0.5, 'capital_intensive': 0.1, 'dividend_stocks': -0.3}}
        self.regulatory_keywords = {'proposal_stage': ['proposed rule', 'draft regulation', 'consultation paper', 'request for comment', 'policy proposal', 'legislative draft'], 'advancement_stage': ['committee approval', 'senate passage', 'house passage', 'regulatory approval', 'agency adoption', 'cabinet approval'], 'implementation_stage': ['effective date', 'compliance deadline', 'enforcement begins', 'mandatory compliance', 'phased implementation', 'grace period'], 'enforcement_action': ['regulatory fine', 'enforcement action', 'compliance violation', 'penalty imposed', 'consent order', 'regulatory sanction']}
        self.jurisdiction_weights = {'United_States': 0.35, 'European_Union': 0.25, 'China': 0.2, 'United_Kingdom': 0.1, 'Japan': 0.05, 'Other': 0.05}

    async def analyze_regulatory_landscape(self) -> List[RegulatorySignal]:
        """Comprehensive regulatory landscape analysis"""
        signals = []
        try:
            for domain, regulations in self.regulatory_domains.items():
                domain_signals = await self._analyze_regulatory_domain(domain, regulations)
                signals.extend(domain_signals)
            signals.sort(key=lambda x: x.impact_level * x.confidence, reverse=True)
            return signals[:15]
        except Exception as e:
            logging.error(f'Error in regulatory landscape analysis: {e}')
            return [self._default_regulatory_signal()]

    async def _analyze_regulatory_domain(self, domain: str, regulations: Dict[str, float]) -> List[RegulatorySignal]:
        """Analyze specific regulatory domain"""
        domain_signals = []
        news_data = await self._fetch_regulatory_news(domain, list(regulations.keys()))
        for regulation, weight in regulations.items():
            try:
                relevant_news = [news for news in news_data if self._is_relevant_to_regulation(news, regulation, domain)]
                if not relevant_news:
                    continue
                stage_analysis = self._analyze_regulatory_stage(relevant_news)
                impact_level = self._calculate_regulatory_impact(relevant_news, regulation, domain, weight)
                affected_sectors = self._get_affected_sectors(domain, impact_level)
                market_impact = self._calculate_market_impact(domain, regulation, impact_level)
                compliance_cost = self._estimate_compliance_cost(regulation, domain, impact_level)
                competitive_advantage = self._analyze_competitive_impact(domain, regulation, relevant_news)
                timeline = self._estimate_implementation_timeline(stage_analysis, relevant_news)
                confidence = self._calculate_regulatory_confidence(relevant_news, stage_analysis)
                signal = RegulatorySignal(regulation_type=f'{domain}_{regulation}', jurisdiction=self._determine_jurisdiction(relevant_news), impact_level=impact_level, implementation_timeline=timeline, affected_sectors=affected_sectors, market_impact=market_impact, compliance_cost=compliance_cost, competitive_advantage=competitive_advantage, confidence=confidence)
                domain_signals.append(signal)
            except Exception as e:
                logging.error(f'Error analyzing regulation {regulation}: {e}')
                continue
        return domain_signals

    async def _fetch_regulatory_news(self, domain: str, regulations: List[str]) -> List[DataPoint]:
        """Fetch regulatory news for specific domain"""
        all_news = []
        domain_queries = {'financial_regulation': ['banking regulation', 'financial oversight', 'securities rules', 'fintech regulation'], 'environmental_regulation': ['environmental regulation', 'carbon policy', 'emissions standards', 'green legislation'], 'technology_regulation': ['tech regulation', 'data privacy', 'ai governance', 'platform oversight'], 'healthcare_regulation': ['healthcare policy', 'drug regulation', 'medical device approval', 'health insurance'], 'tax_policy': ['tax reform', 'corporate tax', 'international taxation', 'digital tax']}
        queries = domain_queries.get(domain, [domain.replace('_', ' ')])
        for query in queries:
            try:
                news_data = await self.data_manager.get_multi_source_data({'news': {'query': query, 'sources': ['reuters', 'bloomberg', 'wsj', 'ft'], 'hours_back': 168}})
                if 'news' in news_data:
                    all_news.extend(news_data['news'])
            except Exception as e:
                logging.error(f'Error fetching regulatory news for {query}: {e}')
                continue
        return all_news

    def _is_relevant_to_regulation(self, news: DataPoint, regulation: str, domain: str) -> bool:
        """Check if news is relevant to specific regulation"""
        text = (news.value + ' ' + news.metadata.get('description', '')).lower()
        regulation_keywords = {'banking_rules': ['basel', 'capital requirements', 'stress test', 'bank supervision'], 'carbon_pricing': ['carbon tax', 'cap and trade', 'emissions trading', 'carbon border'], 'data_privacy': ['gdpr', 'data protection', 'privacy regulation', 'data governance'], 'drug_pricing': ['prescription drug', 'medicare negotiation', 'drug pricing', 'pharmaceutical'], 'ai_governance': ['artificial intelligence', 'ai regulation', 'algorithmic oversight', 'ai safety']}
        keywords = regulation_keywords.get(regulation, [regulation.replace('_', ' ')])
        regulatory_action_keywords = ['regulation', 'policy', 'rule', 'legislation', 'bill', 'act', 'oversight', 'compliance', 'enforcement', 'approval', 'mandate']
        has_regulation_keyword = any((keyword in text for keyword in keywords))
        has_action_keyword = any((keyword in text for keyword in regulatory_action_keywords))
        return has_regulation_keyword and has_action_keyword

    def _analyze_regulatory_stage(self, news: List[DataPoint]) -> Dict[str, float]:
        """Analyze what stage regulations are in"""
        stage_scores = {'proposal': 0.0, 'advancement': 0.0, 'implementation': 0.0, 'enforcement': 0.0}
        total_articles = len(news)
        if total_articles == 0:
            return stage_scores
        for article in news:
            text = article.value.lower()
            for stage, keywords in self.regulatory_keywords.items():
                stage_name = stage.replace('_stage', '').replace('_action', '')
                for keyword in keywords:
                    if keyword in text:
                        stage_scores[stage_name] += article.confidence / total_articles
        return stage_scores

    def _calculate_regulatory_impact(self, news: List[DataPoint], regulation: str, domain: str, weight: float) -> int:
        """Calculate regulatory impact level (1-10)"""
        if not news:
            return 3
        base_impacts = {'banking_rules': 7, 'carbon_pricing': 8, 'data_privacy': 6, 'drug_pricing': 8, 'corporate_tax_rates': 9, 'ai_governance': 5, 'securities_regulation': 6}
        base_impact = base_impacts.get(regulation, 5)
        high_impact_keywords = ['sweeping changes', 'major reform', 'significant impact', 'industry transformation', 'mandatory compliance', 'substantial penalties', 'widespread adoption', 'market disruption', 'regulatory overhaul', 'unprecedented']
        scope_indicators = ['global', 'international', 'nationwide', 'industry-wide', 'comprehensive', 'all companies', 'every business', 'mandatory for all']
        intensity_score = 0
        scope_score = 0
        for article in news:
            text = article.value.lower()
            intensity_score += sum((1 for keyword in high_impact_keywords if keyword in text))
            scope_score += sum((1 for keyword in scope_indicators if keyword in text))
        if news:
            intensity_factor = min(intensity_score / len(news), 2.0)
            scope_factor = min(scope_score / len(news), 1.5)
            weight_factor = weight * 2
            adjusted_impact = base_impact + intensity_factor + scope_factor + weight_factor
        else:
            adjusted_impact = base_impact
        return int(np.clip(adjusted_impact, 1, 10))

    def _get_affected_sectors(self, domain: str, impact_level: int) -> List[str]:
        """Get sectors affected by regulatory domain"""
        if domain not in self.sector_impact_map:
            return ['broad_market']
        sector_impacts = self.sector_impact_map[domain]
        threshold = 0.2 if impact_level > 7 else 0.3 if impact_level > 5 else 0.4
        affected_sectors = []
        for sector, impact in sector_impacts.items():
            if abs(impact) >= threshold:
                affected_sectors.append(sector)
        return affected_sectors or ['broad_market']

    def _calculate_market_impact(self, domain: str, regulation: str, impact_level: int) -> Dict[str, float]:
        """Calculate expected market impact by asset class"""
        if domain not in self.sector_impact_map:
            return {'broad_market': 0.0}
        sector_impacts = self.sector_impact_map[domain]
        impact_multiplier = impact_level / 10.0
        market_impacts = {}
        for sector, base_impact in sector_impacts.items():
            scaled_impact = base_impact * impact_multiplier
            market_impacts[sector] = np.clip(scaled_impact, -1.0, 1.0)
        return market_impacts

    def _estimate_compliance_cost(self, regulation: str, domain: str, impact_level: int) -> float:
        """Estimate compliance cost as percentage of revenue"""
        base_costs = {'banking_rules': 0.015, 'data_privacy': 0.008, 'emissions_standards': 0.012, 'drug_pricing': 0.005, 'cybersecurity_rules': 0.01}
        base_cost = base_costs.get(regulation, 0.005)
        impact_multiplier = impact_level / 5.0
        return base_cost * impact_multiplier

    def _analyze_competitive_impact(self, domain: str, regulation: str, news: List[DataPoint]) -> Dict[str, float]:
        """Analyze which companies/sectors gain competitive advantage"""
        competitive_advantages = {}
        advantage_keywords = {'large_companies': ['economies of scale', 'large companies benefit', 'big players advantage'], 'incumbents': ['existing players', 'incumbent advantage', 'barriers to entry'], 'tech_leaders': ['technology advantage', 'innovation leaders', 'digital transformation'], 'compliance_specialists': ['compliance expertise', 'regulatory experience', 'specialized knowledge']}
        for company_type, keywords in advantage_keywords.items():
            advantage_score = 0.0
            for article in news:
                text = article.value.lower()
                keyword_count = sum((1 for keyword in keywords if keyword in text))
                advantage_score += keyword_count * article.confidence
            if news and advantage_score > 0:
                competitive_advantages[company_type] = min(advantage_score / len(news), 1.0)
        return competitive_advantages

    def _estimate_implementation_timeline(self, stage_analysis: Dict[str, float], news: List[DataPoint]) -> str:
        """Estimate regulatory implementation timeline"""
        current_stage = max(stage_analysis.items(), key=lambda x: x[1])[0]
        timeline_estimates = {'proposal': '12-24 months', 'advancement': '6-18 months', 'implementation': '3-12 months', 'enforcement': 'Immediate'}
        base_timeline = timeline_estimates.get(current_stage, '12-24 months')
        timeline_patterns = ['(\\d+)\\s*months?', '(\\d+)\\s*years?', 'by\\s+(\\d{4})', 'effective\\s+(\\w+\\s+\\d{1,2},?\\s+\\d{4})']
        for article in news:
            text = article.value
            for pattern in timeline_patterns:
                matches = re.findall(pattern, text, re.IGNORECASE)
                if matches:
                    return f'Specific timeline mentioned: {matches[0]}'
        return base_timeline

    def _determine_jurisdiction(self, news: List[DataPoint]) -> str:
        """Determine primary jurisdiction from news"""
        jurisdiction_keywords = {'United_States': ['usa', 'united states', 'sec', 'fed', 'congress', 'senate', 'house'], 'European_Union': ['eu', 'european union', 'brussels', 'european commission', 'esma'], 'China': ['china', 'beijing', 'pboc', 'csrc', 'chinese regulators'], 'United_Kingdom': ['uk', 'united kingdom', 'fca', 'pra', 'bank of england'], 'Japan': ['japan', 'jfsa', 'boj', 'bank of japan']}
        jurisdiction_scores = {j: 0 for j in jurisdiction_keywords.keys()}
        for article in news:
            text = article.value.lower()
            for jurisdiction, keywords in jurisdiction_keywords.items():
                score = sum((1 for keyword in keywords if keyword in text))
                jurisdiction_scores[jurisdiction] += score * article.confidence
        if any(jurisdiction_scores.values()):
            return max(jurisdiction_scores.items(), key=lambda x: x[1])[0]
        return 'Multiple/Global'

    def _calculate_regulatory_confidence(self, news: List[DataPoint], stage_analysis: Dict[str, float]) -> float:
        """Calculate confidence in regulatory analysis"""
        confidence_factors = []
        if news:
            news_confidence = min(len(news) / 10, 1.0) * 0.3
            source_quality = np.mean([article.confidence for article in news]) * 0.4
            confidence_factors.extend([news_confidence, source_quality])
        else:
            confidence_factors.extend([0.1, 0.2])
        max_stage_score = max(stage_analysis.values()) if stage_analysis else 0
        stage_confidence = max_stage_score * 0.3
        confidence_factors.append(stage_confidence)
        return np.sum(confidence_factors)

    def _default_regulatory_signal(self) -> RegulatorySignal:
        """Return default regulatory signal"""
        return RegulatorySignal(regulation_type='general_regulatory_uncertainty', jurisdiction='Global', impact_level=5, implementation_timeline='12-24 months', affected_sectors=['broad_market'], market_impact={'broad_market': 0.0}, compliance_cost=0.005, competitive_advantage={}, confidence=0.3)

    async def analyze_policy_changes(self) -> List[PolicyChange]:
        """Analyze upcoming policy changes and their market implications"""
        policy_changes = []
        policy_areas = ['tax_reform', 'healthcare_policy', 'infrastructure_spending', 'trade_policy', 'energy_policy', 'immigration_policy']
        for policy_area in policy_areas:
            try:
                change = await self._analyze_specific_policy(policy_area)
                if change:
                    policy_changes.append(change)
            except Exception as e:
                logging.error(f'Error analyzing policy {policy_area}: {e}')
                continue
        return policy_changes

    async def _analyze_specific_policy(self, policy_area: str) -> Optional[PolicyChange]:
        """Analyze specific policy area for changes"""
        news_data = await self.data_manager.get_multi_source_data({'news': {'query': policy_area.replace('_', ' '), 'sources': ['reuters', 'bloomberg', 'wsj'], 'hours_back': 72}})
        news = news_data.get('news', [])
        if not news:
            return None
        change_type = self._determine_policy_change_type(news)
        probability = self._calculate_passage_probability(news, policy_area)
        if probability < 0.2:
            return None
        economic_impact = self._calculate_policy_economic_impact(policy_area, news)
        winners, losers = self._identify_policy_winners_losers(policy_area)
        timeline = self._estimate_policy_timeline(news, change_type)
        return PolicyChange(policy_area=policy_area, change_type=change_type, probability_passage=probability, economic_impact=economic_impact, sector_winners=winners, sector_losers=losers, timeline=timeline)

    def _determine_policy_change_type(self, news: List[DataPoint]) -> str:
        """Determine type of policy change"""
        change_keywords = {'proposed': ['proposed', 'draft', 'plan', 'considering', 'exploring'], 'enacted': ['passed', 'approved', 'enacted', 'signed', 'adopted'], 'implemented': ['effective', 'implementation', 'rollout', 'enforcement']}
        change_scores = {change_type: 0 for change_type in change_keywords.keys()}
        for article in news:
            text = article.value.lower()
            for change_type, keywords in change_keywords.items():
                score = sum((1 for keyword in keywords if keyword in text))
                change_scores[change_type] += score
        return max(change_scores.items(), key=lambda x: x[1])[0] if any(change_scores.values()) else 'proposed'

    def _calculate_passage_probability(self, news: List[DataPoint], policy_area: str) -> float:
        """Calculate probability of policy passage"""
        base_probabilities = {'tax_reform': 0.4, 'healthcare_policy': 0.3, 'infrastructure_spending': 0.6, 'trade_policy': 0.5, 'energy_policy': 0.4, 'immigration_policy': 0.2}
        base_prob = base_probabilities.get(policy_area, 0.4)
        positive_indicators = ['bipartisan support', 'broad agreement', 'likely to pass', 'strong support']
        negative_indicators = ['opposition', 'unlikely to pass', 'political deadlock', 'controversy']
        positive_score = 0
        negative_score = 0
        for article in news:
            text = article.value.lower()
            positive_score += sum((1 for indicator in positive_indicators if indicator in text))
            negative_score += sum((1 for indicator in negative_indicators if indicator in text))
        if news:
            sentiment_adjustment = (positive_score - negative_score) / len(news) * 0.3
            adjusted_prob = base_prob + sentiment_adjustment
        else:
            adjusted_prob = base_prob
        return np.clip(adjusted_prob, 0.0, 1.0)

    def _calculate_policy_economic_impact(self, policy_area: str, news: List[DataPoint]) -> Dict[str, float]:
        """Calculate economic impact of policy changes"""
        base_impacts = {'tax_reform': {'gdp_growth': 0.3, 'business_investment': 0.5, 'consumer_spending': 0.2}, 'infrastructure_spending': {'gdp_growth': 0.8, 'employment': 0.6, 'productivity': 0.4}, 'healthcare_policy': {'healthcare_costs': -0.3, 'business_costs': 0.2, 'innovation': -0.1}, 'trade_policy': {'trade_volumes': 0.4, 'manufacturing': 0.3, 'consumer_prices': -0.2}, 'energy_policy': {'energy_costs': -0.2, 'green_investment': 0.6, 'traditional_energy': -0.4}}
        return base_impacts.get(policy_area, {'gdp_growth': 0.1})

    def _identify_policy_winners_losers(self, policy_area: str) -> Tuple[List[str], List[str]]:
        """Identify sector winners and losers from policy changes"""
        policy_impacts = {'tax_reform': {'winners': ['domestic_companies', 'small_business', 'manufacturing'], 'losers': ['multinationals', 'high_tax_rate_sectors']}, 'infrastructure_spending': {'winners': ['construction', 'materials', 'industrials', 'transportation'], 'losers': ['bond_investors']}, 'healthcare_policy': {'winners': ['healthcare_providers', 'medical_devices'], 'losers': ['pharmaceuticals', 'health_insurance']}, 'energy_policy': {'winners': ['renewable_energy', 'electric_vehicles', 'grid_infrastructure'], 'losers': ['fossil_fuels', 'traditional_utilities']}}
        impacts = policy_impacts.get(policy_area, {'winners': [], 'losers': []})
        return (impacts['winners'], impacts['losers'])

    def _estimate_policy_timeline(self, news: List[DataPoint], change_type: str) -> str:
        """Estimate policy implementation timeline"""
        timeline_map = {'proposed': '6-18 months to passage', 'enacted': '3-12 months to implementation', 'implemented': 'Currently rolling out'}
        return timeline_map.get(change_type, '12-24 months')

    async def get_regulatory_report(self) -> Dict:
        """Generate comprehensive regulatory intelligence report"""
        regulatory_signals = await self.analyze_regulatory_landscape()
        policy_changes = await self.analyze_policy_changes()
        llm_analysis = await self._generate_regulatory_llm_analysis(regulatory_signals, policy_changes)
        return {'timestamp': datetime.now().isoformat(), 'agent': self.name, 'regulatory_landscape': {'high_impact_regulations': [{'regulation': signal.regulation_type, 'jurisdiction': signal.jurisdiction, 'impact_level': signal.impact_level, 'timeline': signal.implementation_timeline, 'affected_sectors': signal.affected_sectors, 'market_impact': signal.market_impact} for signal in regulatory_signals[:5]], 'compliance_cost_estimate': np.mean([s.compliance_cost for s in regulatory_signals]), 'overall_regulatory_pressure': np.mean([s.impact_level for s in regulatory_signals])}, 'policy_changes': [{'policy_area': change.policy_area, 'change_type': change.change_type, 'probability': change.probability_passage, 'economic_impact': change.economic_impact, 'winners': change.sector_winners, 'losers': change.sector_losers, 'timeline': change.timeline} for change in policy_changes], 'investment_implications': {'defensive_sectors': self._get_defensive_regulatory_sectors(regulatory_signals), 'regulatory_beneficiaries': self._get_regulatory_beneficiaries(regulatory_signals), 'compliance_leaders': self._get_compliance_advantage_sectors(regulatory_signals), 'regulatory_risk_sectors': self._get_high_risk_sectors(regulatory_signals)}, 'llm_analysis': llm_analysis, 'monitoring_priorities': {'key_regulations': [s.regulation_type for s in regulatory_signals[:3]], 'high_probability_policies': [c.policy_area for c in policy_changes if c.probability_passage > 0.6], 'immediate_compliance_deadlines': [s.regulation_type for s in regulatory_signals if 'months' in s.implementation_timeline and int(s.implementation_timeline.split()[0]) <= 6]}}

    async def _generate_regulatory_llm_analysis(self, signals: List[RegulatorySignal], policy_changes: List[PolicyChange]) -> Dict:
        """Generate LLM-enhanced regulatory analysis"""
        try:
            reg_summary = self._prepare_regulatory_summary(signals)
            policy_summary = self._prepare_policy_summary(policy_changes)
            prompt = f'\n            As a senior regulatory affairs analyst, analyze the current regulatory landscape and provide investment guidance.\n\n            Key Regulatory Developments:\n            {reg_summary}\n\n            Policy Changes:\n            {policy_summary}\n\n            Please provide:\n            1. Most critical regulatory risks requiring immediate attention\n            2. Regulatory arbitrage opportunities (sectors benefiting from regulatory changes)\n            3. Compliance cost leaders vs laggards investment strategy\n            4. Timeline for next major regulatory wave\n            5. Sector rotation recommendations based on regulatory trends\n            6. Early warning indicators for regulatory surprises\n\n            Format as JSON with keys: critical_risks, arbitrage_opportunities, compliance_strategy, \n            regulatory_timeline, sector_rotation, early_warning_indicators\n            '
            response = self.client.chat.completions.create(model=CONFIG.llm.deep_think_model, messages=[{'role': 'user', 'content': prompt}], temperature=CONFIG.llm.temperature, max_tokens=CONFIG.llm.max_tokens)
            return json.loads(response.choices[0].message.content)
        except Exception as e:
            logging.error(f'Error in LLM regulatory analysis: {e}')
            return {'critical_risks': ['Financial regulation tightening', 'ESG compliance requirements'], 'arbitrage_opportunities': ['Compliance technology', 'Renewable energy'], 'compliance_strategy': 'Focus on established players with regulatory expertise', 'regulatory_timeline': 'Next 12-18 months', 'sector_rotation': 'Overweight compliance leaders, underweight regulatory laggards', 'early_warning_indicators': ['Congressional hearings', 'Agency enforcement actions']}

    def _prepare_regulatory_summary(self, signals: List[RegulatorySignal]) -> str:
        """Prepare regulatory summary for LLM"""
        summary_lines = []
        for signal in signals[:5]:
            summary_lines.append(f'{signal.regulation_type} ({signal.jurisdiction}): Impact Level {signal.impact_level}/10, Timeline: {signal.implementation_timeline}, Sectors: {', '.join(signal.affected_sectors[:3])}, Compliance Cost: {signal.compliance_cost:.1%}')
        return '\n'.join(summary_lines)

    def _prepare_policy_summary(self, policy_changes: List[PolicyChange]) -> str:
        """Prepare policy changes summary for LLM"""
        summary_lines = []
        for policy in policy_changes:
            summary_lines.append(f'{policy.policy_area}: {policy.change_type} (Probability: {policy.probability_passage:.0%}), Winners: {', '.join(policy.sector_winners[:2])}, Losers: {', '.join(policy.sector_losers[:2])}')
        return '\n'.join(summary_lines)

    def _get_defensive_regulatory_sectors(self, signals: List[RegulatorySignal]) -> List[str]:
        """Get sectors that are defensive against regulatory risk"""
        defensive_sectors = []
        inherently_defensive = ['utilities', 'consumer_staples', 'healthcare_providers']
        for signal in signals:
            for sector, impact in signal.market_impact.items():
                if impact > 0.3:
                    defensive_sectors.append(sector)
        all_defensive = inherently_defensive + defensive_sectors
        return list(set(all_defensive))

    def _get_regulatory_beneficiaries(self, signals: List[RegulatorySignal]) -> List[str]:
        """Get sectors that benefit from regulatory changes"""
        beneficiaries = []
        for signal in signals:
            for sector, impact in signal.market_impact.items():
                if impact > 0.4:
                    beneficiaries.append(sector)
            for advantage_type, score in signal.competitive_advantage.items():
                if score > 0.5 and advantage_type == 'compliance_specialists':
                    beneficiaries.extend(['legal_services', 'compliance_tech', 'consulting'])
        return list(set(beneficiaries))

    def _get_compliance_advantage_sectors(self, signals: List[RegulatorySignal]) -> List[str]:
        """Get sectors with compliance competitive advantages"""
        advantage_sectors = []
        for signal in signals:
            for advantage_type, score in signal.competitive_advantage.items():
                if score > 0.4:
                    if advantage_type == 'large_companies':
                        advantage_sectors.extend(['mega_cap_stocks', 'blue_chip_companies'])
                    elif advantage_type == 'tech_leaders':
                        advantage_sectors.extend(['technology', 'software'])
                    elif advantage_type == 'incumbents':
                        advantage_sectors.extend(['established_players'])
        return list(set(advantage_sectors))

    def _get_high_risk_sectors(self, signals: List[RegulatorySignal]) -> List[str]:
        """Get sectors with high regulatory risk"""
        high_risk_sectors = []
        for signal in signals:
            if signal.impact_level >= 7:
                for sector, impact in signal.market_impact.items():
                    if impact < -0.3:
                        high_risk_sectors.append(sector)
        return list(set(high_risk_sectors))

def _is_relevant_to_regulation(self, news: DataPoint, regulation: str, domain: str) -> bool:
    """Check if news is relevant to specific regulation"""
    text = (news.value + ' ' + news.metadata.get('description', '')).lower()
    regulation_keywords = {'banking_rules': ['basel', 'capital requirements', 'stress test', 'bank supervision'], 'carbon_pricing': ['carbon tax', 'cap and trade', 'emissions trading', 'carbon border'], 'data_privacy': ['gdpr', 'data protection', 'privacy regulation', 'data governance'], 'drug_pricing': ['prescription drug', 'medicare negotiation', 'drug pricing', 'pharmaceutical'], 'ai_governance': ['artificial intelligence', 'ai regulation', 'algorithmic oversight', 'ai safety']}
    keywords = regulation_keywords.get(regulation, [regulation.replace('_', ' ')])
    regulatory_action_keywords = ['regulation', 'policy', 'rule', 'legislation', 'bill', 'act', 'oversight', 'compliance', 'enforcement', 'approval', 'mandate']
    has_regulation_keyword = any((keyword in text for keyword in keywords))
    has_action_keyword = any((keyword in text for keyword in regulatory_action_keywords))
    return has_regulation_keyword and has_action_keyword

def _calculate_regulatory_impact(self, news: List[DataPoint], regulation: str, domain: str, weight: float) -> int:
    """Calculate regulatory impact level (1-10)"""
    if not news:
        return 3
    base_impacts = {'banking_rules': 7, 'carbon_pricing': 8, 'data_privacy': 6, 'drug_pricing': 8, 'corporate_tax_rates': 9, 'ai_governance': 5, 'securities_regulation': 6}
    base_impact = base_impacts.get(regulation, 5)
    high_impact_keywords = ['sweeping changes', 'major reform', 'significant impact', 'industry transformation', 'mandatory compliance', 'substantial penalties', 'widespread adoption', 'market disruption', 'regulatory overhaul', 'unprecedented']
    scope_indicators = ['global', 'international', 'nationwide', 'industry-wide', 'comprehensive', 'all companies', 'every business', 'mandatory for all']
    intensity_score = 0
    scope_score = 0
    for article in news:
        text = article.value.lower()
        intensity_score += sum((1 for keyword in high_impact_keywords if keyword in text))
        scope_score += sum((1 for keyword in scope_indicators if keyword in text))
    if news:
        intensity_factor = min(intensity_score / len(news), 2.0)
        scope_factor = min(scope_score / len(news), 1.5)
        weight_factor = weight * 2
        adjusted_impact = base_impact + intensity_factor + scope_factor + weight_factor
    else:
        adjusted_impact = base_impact
    return int(np.clip(adjusted_impact, 1, 10))

def _calculate_market_impact(self, domain: str, regulation: str, impact_level: int) -> Dict[str, float]:
    """Calculate expected market impact by asset class"""
    if domain not in self.sector_impact_map:
        return {'broad_market': 0.0}
    sector_impacts = self.sector_impact_map[domain]
    impact_multiplier = impact_level / 10.0
    market_impacts = {}
    for sector, base_impact in sector_impacts.items():
        scaled_impact = base_impact * impact_multiplier
        market_impacts[sector] = np.clip(scaled_impact, -1.0, 1.0)
    return market_impacts

