class AgentOrchestrator:
    """Orchestrates multi-agent analysis with inter-agent communication"""

    def __init__(self, gemini_api_key: str):
        genai.configure(api_key=gemini_api_key)
        self.gemini_model = genai.GenerativeModel('gemini-pro')
        self.agents = {'macro': MacroCycleAgent(), 'fed': CentralBankAgent(), 'geo': GeopoliticalAgent(), 'regulatory': RegulatoryAgent(), 'sentiment': SentimentAgent(), 'flows': InstitutionalFlowAgent(), 'supply': SupplyChainAgent(), 'innovation': InnovationAgent(), 'fx': CurrencyAgent(), 'behavioral': BehavioralAgent()}
        self.agent_weights = {'macro': 0.2, 'fed': 0.18, 'geo': 0.15, 'flows': 0.12, 'sentiment': 0.1, 'regulatory': 0.08, 'supply': 0.07, 'fx': 0.05, 'behavioral': 0.03, 'innovation': 0.02}
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')
        self.logger = logging.getLogger('AgentOrchestrator')

    async def run_comprehensive_analysis(self, target_assets: List[str]=None) -> ConsensusDecision:
        """Run comprehensive analysis with all agents and generate consensus decision"""
        self.logger.info('🚀 Starting comprehensive multi-agent analysis...')
        agent_decisions = await self._execute_all_agents()
        enriched_decisions = await self._facilitate_agent_communication(agent_decisions)
        consensus = await self._generate_consensus_decision(enriched_decisions, target_assets)
        final_decision = await self._validate_and_refine_decision(consensus, enriched_decisions)
        self.logger.info(f'✅ Analysis complete. Final signal: {final_decision.overall_signal}')
        return final_decision

    async def _execute_all_agents(self) -> Dict[str, AgentDecision]:
        """Execute all agents concurrently and standardize outputs"""
        self.logger.info('📊 Executing all agents concurrently...')

        async def run_single_agent(name: str, agent: Any) -> AgentDecision:
            try:
                if hasattr(agent, 'get_cycle_report'):
                    report = await agent.get_cycle_report()
                elif hasattr(agent, 'get_policy_report'):
                    report = await agent.get_policy_report()
                elif hasattr(agent, 'get_geopolitical_report'):
                    report = await agent.get_geopolitical_report()
                elif hasattr(agent, 'get_regulatory_report'):
                    report = await agent.get_regulatory_report()
                elif hasattr(agent, 'get_sentiment_report'):
                    report = await agent.get_sentiment_report()
                elif hasattr(agent, 'get_flow_report'):
                    report = await agent.get_flow_report()
                elif hasattr(agent, 'get_supply_chain_report'):
                    report = await agent.get_supply_chain_report()
                elif hasattr(agent, 'get_innovation_report'):
                    report = await agent.get_innovation_report()
                elif hasattr(agent, 'get_currency_report'):
                    report = await agent.get_currency_report()
                elif hasattr(agent, 'get_behavioral_report'):
                    report = await agent.get_behavioral_report()
                else:
                    report = {'error': f'No report method found for {name}'}
                return self._standardize_agent_output(name, report)
            except Exception as e:
                self.logger.error(f'❌ Error in agent {name}: {e}')
                return self._create_error_decision(name, str(e))
        tasks = [run_single_agent(name, agent) for name, agent in self.agents.items()]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        agent_decisions = {}
        for i, (name, agent) in enumerate(self.agents.items()):
            if i < len(results) and isinstance(results[i], AgentDecision):
                agent_decisions[name] = results[i]
            else:
                agent_decisions[name] = self._create_error_decision(name, 'Execution failed')
        self.logger.info(f'📈 Completed analysis from {len(agent_decisions)} agents')
        return agent_decisions

    def _standardize_agent_output(self, agent_name: str, report: Dict[str, Any]) -> AgentDecision:
        """Standardize agent outputs into common decision format"""
        try:
            signal_strength, direction, confidence, insights, implications = self._extract_agent_metrics(agent_name, report)
            return AgentDecision(agent_name=agent_name, timestamp=datetime.now(), signal_strength=signal_strength, direction=direction, confidence=confidence, key_insights=insights, market_implications=implications, time_horizon=self._determine_time_horizon(agent_name, report), raw_analysis=report)
        except Exception as e:
            self.logger.error(f'Error standardizing {agent_name} output: {e}')
            return self._create_error_decision(agent_name, str(e))

    def _extract_agent_metrics(self, agent_name: str, report: Dict) -> tuple:
        """Extract standardized metrics from agent reports"""
        signal_strength = 0.5
        direction = 'neutral'
        confidence = 0.5
        insights = []
        implications = {}
        try:
            if agent_name == 'macro':
                cycle_analysis = report.get('cycle_analysis', {})
                phase = cycle_analysis.get('current_phase', 'expansion')
                signal_strength = cycle_analysis.get('strength', 0.5)
                direction = 'bullish' if phase in ['expansion', 'trough'] else 'bearish'
                confidence = cycle_analysis.get('confidence', 0.5)
                insights = [f'Business cycle: {phase}']
                implications = report.get('investment_implications', {})
            elif agent_name == 'fed':
                fed_analysis = report.get('fed_analysis', {})
                stance = fed_analysis.get('policy_stance', 'neutral')
                signal_strength = fed_analysis.get('probability', 0.5)
                direction = 'bearish' if stance == 'hawkish' else 'bullish' if stance == 'dovish' else 'neutral'
                confidence = fed_analysis.get('confidence', 0.5)
                insights = [f'Fed stance: {stance}', f'Rate direction: {fed_analysis.get('rate_direction', 'holding')}']
                implications = report.get('market_impact', {})
            elif agent_name == 'geo':
                risk_assessment = report.get('global_risk_assessment', {})
                risk_level = risk_assessment.get('overall_risk_level', 5)
                signal_strength = min(risk_level / 10, 1.0)
                direction = 'bearish' if risk_level > 6 else 'neutral'
                confidence = 0.7
                top_risks = risk_assessment.get('top_risks', [])
                insights = [f'Geopolitical risk: {risk_level}/10'] + [risk.get('type', '') for risk in top_risks[:2]]
                implications = report.get('investment_implications', {})
            elif agent_name == 'sentiment':
                sentiment_analysis = report.get('sentiment_analysis', {})
                overall_sentiment = sentiment_analysis.get('overall_sentiment', 0)
                signal_strength = abs(overall_sentiment)
                direction = 'bullish' if overall_sentiment > 0.2 else 'bearish' if overall_sentiment < -0.2 else 'neutral'
                confidence = 0.6
                insights = [f'Market sentiment: {sentiment_analysis.get('sentiment_classification', 'neutral')}']
                contrarian_signals = report.get('contrarian_signals', [])
                if contrarian_signals:
                    insights.append(f'Contrarian opportunities: {len(contrarian_signals)}')
                implications = {'sentiment_momentum': overall_sentiment}
            elif agent_name == 'flows':
                flow_analysis = report.get('flow_analysis', {})
                flow_sentiment = flow_analysis.get('overall_flow_sentiment', 0)
                signal_strength = abs(flow_sentiment)
                direction = 'bullish' if flow_sentiment > 0.1 else 'bearish' if flow_sentiment < -0.1 else 'neutral'
                confidence = 0.8
                insights = [f'Institutional flows: {flow_analysis.get('flow_classification', 'balanced')}']
                implications = {'flow_momentum': flow_sentiment}
            else:
                insights = ['Analysis completed']
                implications = {'general_impact': 0.0}
        except Exception as e:
            self.logger.error(f'Error extracting metrics for {agent_name}: {e}')
        return (signal_strength, direction, confidence, insights, implications)

    def _determine_time_horizon(self, agent_name: str, report: Dict) -> str:
        """Determine time horizon based on agent type"""
        horizon_map = {'macro': 'long_term', 'fed': 'medium_term', 'geo': 'medium_term', 'regulatory': 'long_term', 'sentiment': 'short_term', 'flows': 'short_term', 'supply': 'medium_term', 'innovation': 'long_term', 'fx': 'short_term', 'behavioral': 'short_term'}
        return horizon_map.get(agent_name, 'medium_term')

    async def _facilitate_agent_communication(self, decisions: Dict[str, AgentDecision]) -> Dict[str, AgentDecision]:
        """Enable agents to communicate and refine their decisions based on peer insights"""
        self.logger.info('🤝 Facilitating inter-agent communication...')
        for agent_name, decision in decisions.items():
            peer_insights = self._get_relevant_peer_insights(agent_name, decisions)
            if peer_insights:
                refined_decision = await self._refine_decision_with_peers(decision, peer_insights)
                decisions[agent_name] = refined_decision
        return decisions

    def _get_relevant_peer_insights(self, agent_name: str, decisions: Dict[str, AgentDecision]) -> Dict[str, str]:
        """Get insights from peer agents relevant to the current agent"""
        peer_insights = {}
        agent_relationships = {'macro': ['fed', 'geo', 'flows'], 'fed': ['macro', 'sentiment', 'flows'], 'geo': ['supply', 'fx', 'flows'], 'sentiment': ['behavioral', 'flows', 'macro'], 'flows': ['sentiment', 'macro', 'fed'], 'supply': ['geo', 'innovation', 'regulatory'], 'regulatory': ['innovation', 'supply', 'flows'], 'fx': ['fed', 'geo', 'flows'], 'behavioral': ['sentiment', 'flows', 'macro'], 'innovation': ['regulatory', 'supply', 'macro']}
        relevant_agents = agent_relationships.get(agent_name, [])
        for peer_agent in relevant_agents:
            if peer_agent in decisions:
                peer_decision = decisions[peer_agent]
                insight_summary = f'{peer_decision.direction} signal ({peer_decision.signal_strength:.2f} strength) - {(peer_decision.key_insights[0] if peer_decision.key_insights else 'No specific insights')}'
                peer_insights[peer_agent] = insight_summary
        return peer_insights

    async def _refine_decision_with_peers(self, original_decision: AgentDecision, peer_insights: Dict[str, str]) -> AgentDecision:
        """Use Gemini AI to refine agent decision based on peer insights"""
        try:
            peer_summary = '\n'.join([f'{agent}: {insight}' for agent, insight in peer_insights.items()])
            prompt = f'\n            As the {original_decision.agent_name} agent, refine your analysis considering peer agent insights:\n\n            Your Original Analysis:\n            - Signal: {original_decision.direction} ({original_decision.signal_strength:.2f} strength)\n            - Confidence: {original_decision.confidence:.2f}\n            - Key Insights: {', '.join(original_decision.key_insights)}\n\n            Peer Agent Insights:\n            {peer_summary}\n\n            Considering these peer insights, should you:\n            1. Maintain your original assessment\n            2. Increase/decrease signal strength\n            3. Change direction\n            4. Adjust confidence level\n\n            Provide response in JSON format:\n            {{\n                "action": "maintain/strengthen/weaken/reverse",\n                "new_signal_strength": 0.0-1.0,\n                "new_direction": "bullish/bearish/neutral", \n                "new_confidence": 0.0-1.0,\n                "reasoning": "Brief explanation",\n                "key_factors": ["factor1", "factor2"]\n            }}\n            '
            response = self.gemini_model.generate_content(prompt)
            refinement = json.loads(response.text)
            original_decision.signal_strength = refinement.get('new_signal_strength', original_decision.signal_strength)
            original_decision.direction = refinement.get('new_direction', original_decision.direction)
            original_decision.confidence = refinement.get('new_confidence', original_decision.confidence)
            original_decision.key_insights.append(f'Peer-refined: {refinement.get('reasoning', 'No reasoning')}')
            return original_decision
        except Exception as e:
            self.logger.error(f'Error refining decision with Gemini: {e}')
            return original_decision

    async def _generate_consensus_decision(self, decisions: Dict[str, AgentDecision], target_assets: List[str]=None) -> ConsensusDecision:
        """Generate final consensus decision using Gemini AI"""
        self.logger.info('🧠 Generating consensus decision with Gemini AI...')
        decision_summary = self._prepare_decision_summary(decisions)
        prompt = f'\n        As a senior portfolio manager, analyze these AI agent insights and create a final investment decision:\n\n        Agent Analysis Summary:\n        {decision_summary}\n\n        Agent Weights for Decision Making:\n        {json.dumps(self.agent_weights, indent=2)}\n\n        Target Assets: {target_assets or 'Broad market exposure'}\n\n        Generate a comprehensive investment decision with:\n        1. Overall signal (strong_buy/buy/hold/sell/strong_sell)\n        2. Conviction level (0-1)\n        3. Asset allocation percentages\n        4. Sector weight recommendations\n        5. Risk level assessment (0-1)\n        6. Key consensus factors\n        7. Main dissenting views\n        8. Execution priority (immediate/gradual/wait)\n\n        Consider:\n        - Agent reliability and track record\n        - Signal consistency across agents\n        - Risk-adjusted returns\n        - Current market regime\n        - Diversification principles\n\n        Provide response in JSON format with all requested fields.\n        '
        try:
            response = self.gemini_model.generate_content(prompt)
            consensus_data = json.loads(response.text)
            return ConsensusDecision(timestamp=datetime.now(), overall_signal=consensus_data.get('overall_signal', 'hold'), conviction_level=consensus_data.get('conviction_level', 0.5), asset_allocation=consensus_data.get('asset_allocation', {'stocks': 0.6, 'bonds': 0.4}), sector_weights=consensus_data.get('sector_weights', {}), risk_level=consensus_data.get('risk_level', 0.5), consensus_factors=consensus_data.get('consensus_factors', []), dissenting_views=consensus_data.get('dissenting_views', []), execution_priority=consensus_data.get('execution_priority', 'gradual'))
        except Exception as e:
            self.logger.error(f'Error generating consensus with Gemini: {e}')
            return self._create_default_consensus(decisions)

    def _prepare_decision_summary(self, decisions: Dict[str, AgentDecision]) -> str:
        """Prepare summary of all agent decisions"""
        summary_lines = []
        for agent_name, decision in decisions.items():
            weight = self.agent_weights.get(agent_name, 0.0)
            summary_lines.append(f'{agent_name.upper()} (Weight: {weight:.1%}): {decision.direction} signal, Strength: {decision.signal_strength:.2f}, Confidence: {decision.confidence:.2f}, Horizon: {decision.time_horizon}, Key: {(decision.key_insights[0] if decision.key_insights else 'N/A')}')
        return '\n'.join(summary_lines)

    async def _validate_and_refine_decision(self, consensus: ConsensusDecision, decisions: Dict[str, AgentDecision]) -> ConsensusDecision:
        """Validate and refine the final decision"""
        self.logger.info('✅ Validating and refining final decision...')
        if consensus.risk_level > 0.8:
            self.logger.warning('⚠️  High risk level detected, adjusting position sizes...')
            for asset in ['stocks', 'growth', 'emerging_markets']:
                if asset in consensus.asset_allocation:
                    consensus.asset_allocation[asset] *= 0.8
        bullish_agents = len([d for d in decisions.values() if d.direction == 'bullish'])
        bearish_agents = len([d for d in decisions.values() if d.direction == 'bearish'])
        if abs(bullish_agents - bearish_agents) <= 1:
            self.logger.info('📊 Mixed signals detected, reducing conviction...')
            consensus.conviction_level *= 0.8
            consensus.execution_priority = 'gradual'
        return consensus

    def _create_error_decision(self, agent_name: str, error_msg: str) -> AgentDecision:
        """Create default decision for failed agents"""
        return AgentDecision(agent_name=agent_name, timestamp=datetime.now(), signal_strength=0.0, direction='neutral', confidence=0.0, key_insights=[f'Error: {error_msg}'], market_implications={}, time_horizon='unknown', raw_analysis={'error': error_msg})

    def _create_default_consensus(self, decisions: Dict[str, AgentDecision]) -> ConsensusDecision:
        """Create default consensus when Gemini fails"""
        total_weighted_signal = 0.0
        total_weight = 0.0
        for agent_name, decision in decisions.items():
            weight = self.agent_weights.get(agent_name, 0.0)
            signal_value = decision.signal_strength * (1 if decision.direction == 'bullish' else -1 if decision.direction == 'bearish' else 0)
            total_weighted_signal += signal_value * weight
            total_weight += weight
        avg_signal = total_weighted_signal / total_weight if total_weight > 0 else 0.0
        if avg_signal > 0.3:
            overall_signal = 'buy'
        elif avg_signal < -0.3:
            overall_signal = 'sell'
        else:
            overall_signal = 'hold'
        return ConsensusDecision(timestamp=datetime.now(), overall_signal=overall_signal, conviction_level=abs(avg_signal), asset_allocation={'stocks': 0.6, 'bonds': 0.3, 'cash': 0.1}, sector_weights={}, risk_level=0.5, consensus_factors=['Default consensus due to system error'], dissenting_views=[], execution_priority='gradual')

def _determine_time_horizon(self, agent_name: str, report: Dict) -> str:
    """Determine time horizon based on agent type"""
    horizon_map = {'macro': 'long_term', 'fed': 'medium_term', 'geo': 'medium_term', 'regulatory': 'long_term', 'sentiment': 'short_term', 'flows': 'short_term', 'supply': 'medium_term', 'innovation': 'long_term', 'fx': 'short_term', 'behavioral': 'short_term'}
    return horizon_map.get(agent_name, 'medium_term')

def _get_relevant_peer_insights(self, agent_name: str, decisions: Dict[str, AgentDecision]) -> Dict[str, str]:
    """Get insights from peer agents relevant to the current agent"""
    peer_insights = {}
    agent_relationships = {'macro': ['fed', 'geo', 'flows'], 'fed': ['macro', 'sentiment', 'flows'], 'geo': ['supply', 'fx', 'flows'], 'sentiment': ['behavioral', 'flows', 'macro'], 'flows': ['sentiment', 'macro', 'fed'], 'supply': ['geo', 'innovation', 'regulatory'], 'regulatory': ['innovation', 'supply', 'flows'], 'fx': ['fed', 'geo', 'flows'], 'behavioral': ['sentiment', 'flows', 'macro'], 'innovation': ['regulatory', 'supply', 'macro']}
    relevant_agents = agent_relationships.get(agent_name, [])
    for peer_agent in relevant_agents:
        if peer_agent in decisions:
            peer_decision = decisions[peer_agent]
            insight_summary = f'{peer_decision.direction} signal ({peer_decision.signal_strength:.2f} strength) - {(peer_decision.key_insights[0] if peer_decision.key_insights else 'No specific insights')}'
            peer_insights[peer_agent] = insight_summary
    return peer_insights

class GeopoliticalAgent:
    """Advanced geopolitical risk monitoring and analysis"""

    def __init__(self):
        self.name = 'geopolitical'
        self.data_manager = DataFeedManager()
        self.client = openai.OpenAI(api_key=CONFIG.api.openai_api_key)
        self.risk_factors = {'military_conflicts': {'Russia-Ukraine': 0.25, 'China-Taiwan': 0.2, 'Middle_East': 0.15, 'North_Korea': 0.1, 'India-Pakistan': 0.08, 'Balkans': 0.05, 'Arctic': 0.07, 'Cyber_warfare': 0.1}, 'trade_tensions': {'US-China': 0.3, 'US-EU': 0.15, 'China-EU': 0.15, 'US-Russia': 0.2, 'Brexit_aftermath': 0.1, 'USMCA_issues': 0.1}, 'sanctions_regime': {'Russia_sanctions': 0.35, 'China_tech_sanctions': 0.25, 'Iran_sanctions': 0.15, 'North_Korea_sanctions': 0.1, 'Secondary_sanctions': 0.15}, 'political_instability': {'US_domestic': 0.2, 'EU_integration': 0.18, 'China_internal': 0.15, 'Middle_East_regimes': 0.15, 'Latin_America': 0.12, 'Africa_coups': 0.1, 'Democratic_backsliding': 0.1}}
        self.sector_impact_map = {'military_conflicts': {'defense': 0.8, 'energy': 0.6, 'commodities': 0.7, 'technology': -0.3, 'tourism': -0.6, 'airlines': -0.5, 'insurance': -0.4}, 'trade_tensions': {'technology': -0.7, 'manufacturing': -0.5, 'agriculture': -0.4, 'automotive': -0.6, 'semiconductors': -0.8, 'renewable_energy': 0.3}, 'sanctions_regime': {'energy': -0.8, 'banking': -0.6, 'technology': -0.5, 'shipping': -0.4, 'commodities': 0.4, 'defense': 0.5}, 'political_instability': {'healthcare': 0.2, 'utilities': 0.3, 'consumer_staples': 0.4, 'financials': -0.4, 'real_estate': -0.3, 'currency': -0.6}}
        self.geopolitical_keywords = {'conflict_escalation': ['military buildup', 'troop movements', 'weapon shipments', 'border tensions', 'missile tests', 'naval exercises', 'air defense', 'invasion', 'occupation', 'blockade'], 'diplomatic_tensions': ['sanctions', 'tariffs', 'trade war', 'diplomatic expulsion', 'embassy closure', 'summit cancellation', 'treaty withdrawal', 'alliance strain', 'diplomatic protest'], 'regime_change': ['coup', 'revolution', 'civil unrest', 'protests', 'election fraud', 'authoritarianism', 'martial law', 'state of emergency', 'government collapse'], 'economic_warfare': ['currency manipulation', 'debt trap', 'supply chain disruption', 'critical minerals', 'technology transfer', 'intellectual property', 'cyber attacks', 'financial warfare']}
        self.regional_weights = {'North_America': 0.25, 'Europe': 0.2, 'East_Asia': 0.25, 'Middle_East': 0.15, 'South_America': 0.08, 'Africa': 0.05, 'South_Asia': 0.02}

    async def analyze_global_risks(self) -> List[GeopoliticalRisk]:
        """Comprehensive global geopolitical risk analysis"""
        risks = []
        try:
            for risk_category, risk_items in self.risk_factors.items():
                category_risks = await self._analyze_risk_category(risk_category, risk_items)
                risks.extend(category_risks)
            risks.sort(key=lambda x: x.current_level * x.confidence, reverse=True)
            return risks[:10]
        except Exception as e:
            logging.error(f'Error in global risk analysis: {e}')
            return [self._default_geopolitical_risk()]

    async def _analyze_risk_category(self, category: str, risk_items: Dict[str, float]) -> List[GeopoliticalRisk]:
        """Analyze specific risk category"""
        category_risks = []
        news_data = await self._fetch_category_news(category, list(risk_items.keys()))
        for risk_item, weight in risk_items.items():
            try:
                relevant_news = [news for news in news_data if self._is_relevant_to_risk(news, risk_item)]
                risk_level = self._calculate_risk_level(relevant_news, risk_item, category)
                trend = self._determine_risk_trend(relevant_news)
                prob_impact = self._calculate_probability_impact(risk_level, weight, relevant_news)
                affected_sectors = self._get_affected_sectors(category, risk_level)
                timeline = self._estimate_timeline(risk_level, trend, relevant_news)
                mitigation = self._get_mitigation_strategies(risk_item, category)
                confidence = self._calculate_risk_confidence(relevant_news, risk_item)
                risk = GeopoliticalRisk(region=self._get_region_from_risk(risk_item), risk_type=category, current_level=risk_level, trend=trend, probability_impact=prob_impact, affected_sectors=affected_sectors, timeline=timeline, mitigation_strategies=mitigation, confidence=confidence)
                category_risks.append(risk)
            except Exception as e:
                logging.error(f'Error analyzing {risk_item}: {e}')
                continue
        return category_risks

    async def _fetch_category_news(self, category: str, risk_items: List[str]) -> List[DataPoint]:
        """Fetch news data for specific risk category"""
        all_news = []
        queries = []
        if category == 'military_conflicts':
            queries = ['military conflict', 'war', 'invasion', 'missile', 'defense']
        elif category == 'trade_tensions':
            queries = ['trade war', 'tariffs', 'sanctions', 'trade dispute']
        elif category == 'sanctions_regime':
            queries = ['sanctions', 'embargo', 'trade restrictions']
        elif category == 'political_instability':
            queries = ['political crisis', 'coup', 'election', 'protests']
        for query in queries:
            try:
                news_data = await self.data_manager.get_multi_source_data({'news': {'query': query, 'sources': ['reuters', 'bloomberg', 'wsj', 'ft'], 'hours_back': 72}})
                if 'news' in news_data:
                    all_news.extend(news_data['news'])
            except Exception as e:
                logging.error(f'Error fetching news for {query}: {e}')
                continue
        return all_news

    def _is_relevant_to_risk(self, news: DataPoint, risk_item: str) -> bool:
        """Check if news article is relevant to specific risk"""
        text = (news.value + ' ' + news.metadata.get('description', '')).lower()
        risk_keywords = {'Russia-Ukraine': ['russia', 'ukraine', 'putin', 'zelensky', 'kyiv', 'moscow'], 'China-Taiwan': ['china', 'taiwan', 'beijing', 'taipei', 'strait', 'xi jinping'], 'Middle_East': ['iran', 'israel', 'gaza', 'lebanon', 'syria', 'yemen'], 'North_Korea': ['north korea', 'kim jong', 'pyongyang', 'dprk'], 'US-China': ['us china', 'trade war', 'biden', 'xi jinping', 'tariff'], 'Russia_sanctions': ['russia sanctions', 'swift', 'energy embargo'], 'China_tech_sanctions': ['china tech', 'semiconductor', 'huawei', 'tiktok']}
        keywords = risk_keywords.get(risk_item, [risk_item.lower().replace('_', ' ')])
        return any((keyword in text for keyword in keywords))

    def _calculate_risk_level(self, news: List[DataPoint], risk_item: str, category: str) -> int:
        """Calculate current risk level (1-10 scale)"""
        if not news:
            return 3
        base_risks = {'Russia-Ukraine': 8, 'China-Taiwan': 6, 'Middle_East': 7, 'US-China': 5, 'North_Korea': 4}
        base_risk = base_risks.get(risk_item, 5)
        escalation_keywords = self.geopolitical_keywords.get('conflict_escalation', [])
        tension_keywords = self.geopolitical_keywords.get('diplomatic_tensions', [])
        escalation_count = 0
        total_articles = len(news)
        for article in news:
            text = article.value.lower()
            escalation_count += sum((1 for keyword in escalation_keywords if keyword in text))
            escalation_count += sum((1 for keyword in tension_keywords if keyword in text))
        if total_articles > 0:
            intensity_factor = min(escalation_count / total_articles, 2.0)
            adjusted_risk = base_risk + intensity_factor
        else:
            adjusted_risk = base_risk
        return int(np.clip(adjusted_risk, 1, 10))

    def _determine_risk_trend(self, news: List[DataPoint]) -> str:
        """Determine if risk is escalating, stable, or de-escalating"""
        if len(news) < 2:
            return 'stable'
        sorted_news = sorted(news, key=lambda x: x.timestamp)
        midpoint = len(sorted_news) // 2
        older_news = sorted_news[:midpoint]
        recent_news = sorted_news[midpoint:]
        older_intensity = self._calculate_news_intensity(older_news)
        recent_intensity = self._calculate_news_intensity(recent_news)
        if recent_intensity > older_intensity * 1.2:
            return 'escalating'
        elif recent_intensity < older_intensity * 0.8:
            return 'de-escalating'
        else:
            return 'stable'

    def _calculate_news_intensity(self, news: List[DataPoint]) -> float:
        """Calculate intensity score of news articles"""
        if not news:
            return 0.0
        intensity_score = 0.0
        escalation_keywords = self.geopolitical_keywords.get('conflict_escalation', []) + self.geopolitical_keywords.get('diplomatic_tensions', [])
        for article in news:
            text = article.value.lower()
            keyword_count = sum((1 for keyword in escalation_keywords if keyword in text))
            intensity_score += keyword_count * article.confidence
        return intensity_score / len(news)

    def _calculate_probability_impact(self, risk_level: int, weight: float, news: List[DataPoint]) -> float:
        """Calculate probability-weighted impact"""
        probability = (risk_level / 10) ** 1.5
        economic_impact = weight
        if news:
            avg_age_hours = np.mean([(datetime.now() - article.timestamp).total_seconds() / 3600 for article in news])
            recency_factor = max(0.5, 1.0 - avg_age_hours / 168)
            volume_factor = min(1.5, len(news) / 10)
        else:
            recency_factor = 0.5
            volume_factor = 0.5
        return probability * economic_impact * recency_factor * volume_factor

    def _get_affected_sectors(self, category: str, risk_level: int) -> List[str]:
        """Get sectors most affected by this risk category"""
        if category not in self.sector_impact_map:
            return ['broad_market']
        sector_impacts = self.sector_impact_map[category]
        threshold = 0.3 if risk_level > 7 else 0.4 if risk_level > 5 else 0.5
        affected_sectors = []
        for sector, impact in sector_impacts.items():
            if abs(impact) >= threshold:
                affected_sectors.append(sector)
        return affected_sectors or ['broad_market']

    def _estimate_timeline(self, risk_level: int, trend: str, news: List[DataPoint]) -> str:
        """Estimate timeline for risk materialization"""
        base_timelines = {'escalating': {9: '1-3 months', 7: '3-6 months', 5: '6-12 months', 3: '1-2 years'}, 'stable': {9: '3-6 months', 7: '6-12 months', 5: '1-2 years', 3: '2+ years'}, 'de-escalating': {9: '6-12 months', 7: '1-2 years', 5: '2+ years', 3: 'Low probability'}}
        timeline_map = base_timelines.get(trend, base_timelines['stable'])
        for level in sorted(timeline_map.keys(), reverse=True):
            if risk_level >= level:
                return timeline_map[level]
        return '2+ years'

    def _get_mitigation_strategies(self, risk_item: str, category: str) -> List[str]:
        """Get investment mitigation strategies for specific risks"""
        strategies = {'military_conflicts': ['Increase defense sector allocation', 'Hedge energy exposure', 'Diversify geographically', 'Add gold/commodities hedge', 'Reduce emerging market exposure'], 'trade_tensions': ['Avoid single-country exposure', 'Focus on domestic-oriented companies', 'Hedge currency exposure', 'Diversify supply chains', 'Consider trade-war beneficiaries'], 'sanctions_regime': ['Avoid sanctioned sectors/countries', 'Increase compliance monitoring', 'Diversify banking relationships', 'Focus on domestic markets', 'Consider alternative payment systems'], 'political_instability': ['Increase safe-haven assets', 'Reduce political-sensitive sectors', 'Focus on multinational companies', 'Add volatility hedges', 'Maintain higher cash levels']}
        return strategies.get(category, ['Monitor closely', 'Maintain diversification'])

    def _get_region_from_risk(self, risk_item: str) -> str:
        """Map risk item to geographical region"""
        region_mapping = {'Russia-Ukraine': 'Europe', 'China-Taiwan': 'East_Asia', 'Middle_East': 'Middle_East', 'North_Korea': 'East_Asia', 'US-China': 'Global', 'US-EU': 'North_America', 'Brexit': 'Europe', 'India-Pakistan': 'South_Asia'}
        return region_mapping.get(risk_item, 'Global')

    def _calculate_risk_confidence(self, news: List[DataPoint], risk_item: str) -> float:
        """Calculate confidence in risk assessment"""
        confidence_factors = []
        news_count = len(news)
        volume_confidence = min(1.0, news_count / 20)
        confidence_factors.append(volume_confidence * 0.3)
        if news:
            avg_source_confidence = np.mean([article.confidence for article in news])
            confidence_factors.append(avg_source_confidence * 0.4)
        else:
            confidence_factors.append(0.3 * 0.4)
        if news:
            most_recent = max(news, key=lambda x: x.timestamp)
            hours_since = (datetime.now() - most_recent.timestamp).total_seconds() / 3600
            recency_confidence = max(0.3, 1.0 - hours_since / 72)
            confidence_factors.append(recency_confidence * 0.3)
        else:
            confidence_factors.append(0.3 * 0.3)
        return np.sum(confidence_factors)

    async def analyze_conflict_escalation(self, conflict_name: str) -> ConflictSignal:
        """Deep analysis of specific military conflict"""
        try:
            conflict_news = await self.data_manager.get_multi_source_data({'news': {'query': conflict_name, 'sources': ['reuters', 'bloomberg', 'wsj'], 'hours_back': 48}})
            news_data = conflict_news.get('news', [])
            escalation_risk = self._calculate_escalation_risk(news_data, conflict_name)
            economic_impact = self._assess_economic_impact(conflict_name, escalation_risk)
            supply_chain_risk = self._analyze_supply_chain_impact(conflict_name)
            market_sectors = self._get_market_sector_impacts(conflict_name, escalation_risk)
            duration_estimate = self._estimate_conflict_duration(news_data, escalation_risk)
            return ConflictSignal(conflict_name=conflict_name, escalation_risk=escalation_risk, economic_impact=economic_impact, supply_chain_risk=supply_chain_risk, market_sectors=market_sectors, duration_estimate=duration_estimate)
        except Exception as e:
            logging.error(f'Error analyzing conflict {conflict_name}: {e}')
            return self._default_conflict_signal(conflict_name)

    def _calculate_escalation_risk(self, news: List[DataPoint], conflict_name: str) -> float:
        """Calculate probability of conflict escalation"""
        if not news:
            return 0.3
        escalation_indicators = ['military buildup', 'troop deployment', 'weapon delivery', 'alliance activation', 'nuclear threat', 'red line crossed', 'ultimatum', 'deadline', 'mobilization', 'intervention']
        escalation_score = 0.0
        for article in news:
            text = article.value.lower()
            indicator_count = sum((1 for indicator in escalation_indicators if indicator in text))
            escalation_score += indicator_count * article.confidence
        if news:
            normalized_score = escalation_score / len(news)
            return min(1.0, normalized_score / 3.0)
        return 0.3

    def _assess_economic_impact(self, conflict_name: str, escalation_risk: float) -> Dict[str, float]:
        """Assess economic impact of conflict escalation"""
        base_impacts = {'Russia-Ukraine': {'global_gdp': -0.8, 'inflation': 2.5, 'energy_prices': 0.4, 'food_prices': 0.3, 'supply_chains': -0.6}, 'China-Taiwan': {'global_gdp': -2.5, 'inflation': 1.8, 'tech_supply': -0.8, 'shipping': -0.7, 'semiconductors': -0.9}, 'Middle_East': {'global_gdp': -0.5, 'oil_prices': 0.6, 'shipping': -0.4, 'regional_markets': -0.8, 'defense_spending': 0.3}}
        base_impact = base_impacts.get(conflict_name, {'global_gdp': -0.3, 'inflation': 1.0, 'volatility': 0.5})
        scaled_impact = {}
        for key, value in base_impact.items():
            scaled_impact[key] = value * escalation_risk
        return scaled_impact

    def _analyze_supply_chain_impact(self, conflict_name: str) -> Dict[str, float]:
        """Analyze supply chain disruption risks"""
        supply_chain_risks = {'Russia-Ukraine': {'energy': 0.8, 'fertilizers': 0.7, 'grains': 0.6, 'metals': 0.5, 'semiconductors': 0.3}, 'China-Taiwan': {'semiconductors': 0.9, 'electronics': 0.8, 'rare_earths': 0.7, 'shipping': 0.6, 'manufacturing': 0.7}, 'Middle_East': {'oil': 0.9, 'gas': 0.7, 'shipping': 0.6, 'petrochemicals': 0.5}}
        return supply_chain_risks.get(conflict_name, {'general': 0.4})

    def _get_market_sector_impacts(self, conflict_name: str, escalation_risk: float) -> Dict[str, float]:
        """Get sector-specific market impacts"""
        sector_impacts = {'Russia-Ukraine': {'energy': 0.6, 'defense': 0.8, 'agriculture': 0.4, 'technology': -0.3, 'airlines': -0.6, 'tourism': -0.7}, 'China-Taiwan': {'semiconductors': -0.9, 'technology': -0.7, 'defense': 0.8, 'shipping': -0.6, 'manufacturing': -0.5, 'commodities': 0.3}, 'Middle_East': {'energy': 0.8, 'defense': 0.6, 'airlines': -0.5, 'insurance': -0.4, 'shipping': -0.3}}
        base_impacts = sector_impacts.get(conflict_name, {'broad_market': -0.2})
        scaled_impacts = {}
        for sector, impact in base_impacts.items():
            scaled_impacts[sector] = impact * escalation_risk
        return scaled_impacts

    def _estimate_conflict_duration(self, news: List[DataPoint], escalation_risk: float) -> str:
        """Estimate conflict duration based on escalation risk"""
        if escalation_risk > 0.8:
            return '6+ months (high intensity)'
        elif escalation_risk > 0.6:
            return '3-12 months (prolonged)'
        elif escalation_risk > 0.4:
            return '1-6 months (limited)'
        else:
            return 'Weeks to months (contained)'

    def _default_geopolitical_risk(self) -> GeopoliticalRisk:
        """Return default risk in case of errors"""
        return GeopoliticalRisk(region='Global', risk_type='general_uncertainty', current_level=5, trend='stable', probability_impact=0.3, affected_sectors=['broad_market'], timeline='6-12 months', mitigation_strategies=['Maintain diversification', 'Monitor developments'], confidence=0.3)

    def _default_conflict_signal(self, conflict_name: str) -> ConflictSignal:
        """Return default conflict signal"""
        return ConflictSignal(conflict_name=conflict_name, escalation_risk=0.3, economic_impact={'global_gdp': -0.1}, supply_chain_risk={'general': 0.2}, market_sectors={'broad_market': -0.1}, duration_estimate='Unknown')

    async def generate_llm_geopolitical_analysis(self, risks: List[GeopoliticalRisk]) -> Dict:
        """Generate LLM-enhanced geopolitical analysis"""
        try:
            risk_summary = self._prepare_risk_summary(risks)
            prompt = f'\n            As a senior geopolitical risk analyst, analyze the current global risk landscape and provide investment guidance.\n\n            Current Top Risks:\n            {risk_summary}\n\n            Please provide:\n            1. Most critical risks requiring immediate attention\n            2. Potential black swan scenarios (low probability, high impact)\n            3. Portfolio hedging strategies\n            4. Regional allocation recommendations\n            5. Timeline for next major geopolitical shift\n            6. Early warning indicators to monitor\n\n            Format as JSON with keys: critical_risks, black_swan_scenarios, hedging_strategies, \n            regional_allocation, timeline, early_warning_indicators\n            '
            response = self.client.chat.completions.create(model=CONFIG.llm.deep_think_model, messages=[{'role': 'user', 'content': prompt}], temperature=CONFIG.llm.temperature, max_tokens=CONFIG.llm.max_tokens)
            return json.loads(response.choices[0].message.content)
        except Exception as e:
            logging.error(f'Error in LLM geopolitical analysis: {e}')
            return {'critical_risks': ['Russia-Ukraine conflict', 'US-China tensions'], 'black_swan_scenarios': ['Taiwan invasion', 'Nuclear incident'], 'hedging_strategies': ['Increase defense allocation', 'Add gold hedge'], 'regional_allocation': 'Underweight emerging markets', 'timeline': 'Next 6-12 months', 'early_warning_indicators': ['Troop movements', 'Diplomatic withdrawals']}

    def _prepare_risk_summary(self, risks: List[GeopoliticalRisk]) -> str:
        """Prepare risk summary for LLM analysis"""
        summary_lines = []
        for risk in risks[:5]:
            summary_lines.append(f'{risk.region} - {risk.risk_type}: Level {risk.current_level}/10 ({risk.trend}), Impact: {risk.probability_impact:.2f}, Sectors: {', '.join(risk.affected_sectors[:3])}')
        return '\n'.join(summary_lines)

    async def get_geopolitical_report(self) -> Dict:
        """Generate comprehensive geopolitical risk report"""
        global_risks = await self.analyze_global_risks()
        conflicts = ['Russia-Ukraine', 'China-Taiwan', 'Middle_East']
        conflict_analyses = []
        for conflict in conflicts:
            signal = await self.analyze_conflict_escalation(conflict)
            conflict_analyses.append({'conflict': conflict, 'escalation_risk': signal.escalation_risk, 'economic_impact': signal.economic_impact, 'duration_estimate': signal.duration_estimate})
        llm_analysis = await self.generate_llm_geopolitical_analysis(global_risks)
        return {'timestamp': datetime.now().isoformat(), 'agent': self.name, 'global_risk_assessment': {'overall_risk_level': np.mean([risk.current_level for risk in global_risks]), 'top_risks': [{'region': risk.region, 'type': risk.risk_type, 'level': risk.current_level, 'trend': risk.trend, 'timeline': risk.timeline, 'affected_sectors': risk.affected_sectors} for risk in global_risks[:5]]}, 'conflict_monitor': conflict_analyses, 'investment_implications': {'defensive_positioning': self._calculate_defensive_score(global_risks), 'sector_rotation': self._get_sector_rotation_recommendations(global_risks), 'regional_weights': self._get_regional_weight_adjustments(global_risks), 'hedging_requirements': self._get_hedging_requirements(global_risks)}, 'llm_analysis': llm_analysis, 'risk_monitoring': {'update_frequency': 'every 6 hours', 'key_indicators': ['news_flow', 'market_volatility', 'diplomatic_activity'], 'escalation_triggers': ['military_movement', 'sanctions_announcement', 'alliance_activation']}}

    def _calculate_defensive_score(self, risks: List[GeopoliticalRisk]) -> float:
        """Calculate how defensive portfolio should be"""
        high_risk_count = sum((1 for risk in risks if risk.current_level >= 7))
        escalating_risks = sum((1 for risk in risks if risk.trend == 'escalating'))
        defensive_score = high_risk_count * 0.15 + escalating_risks * 0.1
        return min(1.0, defensive_score)

    def _get_sector_rotation_recommendations(self, risks: List[GeopoliticalRisk]) -> Dict[str, str]:
        """Get sector rotation based on geopolitical risks"""
        sector_scores = defaultdict(float)
        for risk in risks:
            weight = risk.current_level * risk.confidence / 10
            for sector in risk.affected_sectors:
                if sector in self.sector_impact_map.get(risk.risk_type, {}):
                    impact = self.sector_impact_map[risk.risk_type][sector]
                    sector_scores[sector] += impact * weight
        recommendations = {}
        for sector, score in sector_scores.items():
            if score > 0.2:
                recommendations[sector] = 'overweight'
            elif score < -0.2:
                recommendations[sector] = 'underweight'
            else:
                recommendations[sector] = 'neutral'
        return recommendations

    def _get_regional_weight_adjustments(self, risks: List[GeopoliticalRisk]) -> Dict[str, float]:
        """Get regional allocation adjustments"""
        regional_adjustments = {}
        for region, base_weight in self.regional_weights.items():
            region_risks = [risk for risk in risks if risk.region == region]
            if region_risks:
                avg_risk = np.mean([risk.current_level for risk in region_risks])
                adjustment = max(-0.5, (5 - avg_risk) / 10)
                regional_adjustments[region] = base_weight * (1 + adjustment)
            else:
                regional_adjustments[region] = base_weight
        total_weight = sum(regional_adjustments.values())
        return {region: weight / total_weight for region, weight in regional_adjustments.items()}

    def _get_hedging_requirements(self, risks: List[GeopoliticalRisk]) -> List[str]:
        """Get specific hedging requirements"""
        hedges = []
        high_risks = [risk for risk in risks if risk.current_level >= 7]
        for risk in high_risks:
            if 'energy' in risk.affected_sectors:
                hedges.append('Energy price hedge')
            if 'technology' in risk.affected_sectors:
                hedges.append('Tech sector put options')
            if 'currency' in risk.affected_sectors:
                hedges.append('USD strength hedge')
            if risk.risk_type == 'military_conflicts':
                hedges.append('Gold allocation increase')
                hedges.append('Defense sector exposure')
        return list(set(hedges))

def _is_relevant_to_risk(self, news: DataPoint, risk_item: str) -> bool:
    """Check if news article is relevant to specific risk"""
    text = (news.value + ' ' + news.metadata.get('description', '')).lower()
    risk_keywords = {'Russia-Ukraine': ['russia', 'ukraine', 'putin', 'zelensky', 'kyiv', 'moscow'], 'China-Taiwan': ['china', 'taiwan', 'beijing', 'taipei', 'strait', 'xi jinping'], 'Middle_East': ['iran', 'israel', 'gaza', 'lebanon', 'syria', 'yemen'], 'North_Korea': ['north korea', 'kim jong', 'pyongyang', 'dprk'], 'US-China': ['us china', 'trade war', 'biden', 'xi jinping', 'tariff'], 'Russia_sanctions': ['russia sanctions', 'swift', 'energy embargo'], 'China_tech_sanctions': ['china tech', 'semiconductor', 'huawei', 'tiktok']}
    keywords = risk_keywords.get(risk_item, [risk_item.lower().replace('_', ' ')])
    return any((keyword in text for keyword in keywords))

def _calculate_risk_level(self, news: List[DataPoint], risk_item: str, category: str) -> int:
    """Calculate current risk level (1-10 scale)"""
    if not news:
        return 3
    base_risks = {'Russia-Ukraine': 8, 'China-Taiwan': 6, 'Middle_East': 7, 'US-China': 5, 'North_Korea': 4}
    base_risk = base_risks.get(risk_item, 5)
    escalation_keywords = self.geopolitical_keywords.get('conflict_escalation', [])
    tension_keywords = self.geopolitical_keywords.get('diplomatic_tensions', [])
    escalation_count = 0
    total_articles = len(news)
    for article in news:
        text = article.value.lower()
        escalation_count += sum((1 for keyword in escalation_keywords if keyword in text))
        escalation_count += sum((1 for keyword in tension_keywords if keyword in text))
    if total_articles > 0:
        intensity_factor = min(escalation_count / total_articles, 2.0)
        adjusted_risk = base_risk + intensity_factor
    else:
        adjusted_risk = base_risk
    return int(np.clip(adjusted_risk, 1, 10))

def _calculate_news_intensity(self, news: List[DataPoint]) -> float:
    """Calculate intensity score of news articles"""
    if not news:
        return 0.0
    intensity_score = 0.0
    escalation_keywords = self.geopolitical_keywords.get('conflict_escalation', []) + self.geopolitical_keywords.get('diplomatic_tensions', [])
    for article in news:
        text = article.value.lower()
        keyword_count = sum((1 for keyword in escalation_keywords if keyword in text))
        intensity_score += keyword_count * article.confidence
    return intensity_score / len(news)

def _get_mitigation_strategies(self, risk_item: str, category: str) -> List[str]:
    """Get investment mitigation strategies for specific risks"""
    strategies = {'military_conflicts': ['Increase defense sector allocation', 'Hedge energy exposure', 'Diversify geographically', 'Add gold/commodities hedge', 'Reduce emerging market exposure'], 'trade_tensions': ['Avoid single-country exposure', 'Focus on domestic-oriented companies', 'Hedge currency exposure', 'Diversify supply chains', 'Consider trade-war beneficiaries'], 'sanctions_regime': ['Avoid sanctioned sectors/countries', 'Increase compliance monitoring', 'Diversify banking relationships', 'Focus on domestic markets', 'Consider alternative payment systems'], 'political_instability': ['Increase safe-haven assets', 'Reduce political-sensitive sectors', 'Focus on multinational companies', 'Add volatility hedges', 'Maintain higher cash levels']}
    return strategies.get(category, ['Monitor closely', 'Maintain diversification'])

def _get_region_from_risk(self, risk_item: str) -> str:
    """Map risk item to geographical region"""
    region_mapping = {'Russia-Ukraine': 'Europe', 'China-Taiwan': 'East_Asia', 'Middle_East': 'Middle_East', 'North_Korea': 'East_Asia', 'US-China': 'Global', 'US-EU': 'North_America', 'Brexit': 'Europe', 'India-Pakistan': 'South_Asia'}
    return region_mapping.get(risk_item, 'Global')

def _calculate_escalation_risk(self, news: List[DataPoint], conflict_name: str) -> float:
    """Calculate probability of conflict escalation"""
    if not news:
        return 0.3
    escalation_indicators = ['military buildup', 'troop deployment', 'weapon delivery', 'alliance activation', 'nuclear threat', 'red line crossed', 'ultimatum', 'deadline', 'mobilization', 'intervention']
    escalation_score = 0.0
    for article in news:
        text = article.value.lower()
        indicator_count = sum((1 for indicator in escalation_indicators if indicator in text))
        escalation_score += indicator_count * article.confidence
    if news:
        normalized_score = escalation_score / len(news)
        return min(1.0, normalized_score / 3.0)
    return 0.3

def _analyze_supply_chain_impact(self, conflict_name: str) -> Dict[str, float]:
    """Analyze supply chain disruption risks"""
    supply_chain_risks = {'Russia-Ukraine': {'energy': 0.8, 'fertilizers': 0.7, 'grains': 0.6, 'metals': 0.5, 'semiconductors': 0.3}, 'China-Taiwan': {'semiconductors': 0.9, 'electronics': 0.8, 'rare_earths': 0.7, 'shipping': 0.6, 'manufacturing': 0.7}, 'Middle_East': {'oil': 0.9, 'gas': 0.7, 'shipping': 0.6, 'petrochemicals': 0.5}}
    return supply_chain_risks.get(conflict_name, {'general': 0.4})

class DecisionEngine:
    """Aggregates agent signals and makes final trading decisions"""

    def __init__(self):
        self.agent_weights = CONFIG.agent_weights
        self.risk_manager = RiskManager()

    def aggregate_signals(self, agent_reports: Dict[str, Dict]) -> List[TradingSignal]:
        """Aggregate signals from all agents into trading recommendations"""
        signals = []
        macro_signal = self._extract_macro_signal(agent_reports)
        if macro_signal:
            signals.append(macro_signal)
        sector_signals = self._extract_sector_signals(agent_reports)
        signals.extend(sector_signals)
        currency_signal = self._extract_currency_signal(agent_reports)
        if currency_signal:
            signals.append(currency_signal)
        risk_signal = self._extract_risk_signal(agent_reports)
        if risk_signal:
            signals.append(risk_signal)
        return signals

    def _extract_macro_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
        """Extract macro asset allocation signal"""
        macro_report = reports.get('macro_cycle', {})
        fed_report = reports.get('central_bank', {})
        if not macro_report or not fed_report:
            return None
        cycle_phase = macro_report.get('cycle_analysis', {}).get('current_phase', 'expansion')
        policy_stance = fed_report.get('fed_analysis', {}).get('policy_stance', 'neutral')
        if cycle_phase == 'expansion' and policy_stance in ['neutral', 'dovish']:
            direction = 'long'
            asset_class = 'equities'
            conviction = 0.7
        elif cycle_phase == 'contraction' or policy_stance == 'hawkish':
            direction = 'long'
            asset_class = 'bonds'
            conviction = 0.6
        elif cycle_phase == 'peak':
            direction = 'short'
            asset_class = 'equities'
            conviction = 0.5
        else:
            return None
        supporting_agents = ['macro_cycle', 'central_bank']
        return TradingSignal(timestamp=datetime.now(), asset_class=asset_class, direction=direction, conviction=conviction, position_size=0.4, time_horizon='medium', risk_factors=['cycle_timing', 'policy_error'], supporting_agents=supporting_agents, market_regime=f'{cycle_phase}_{policy_stance}')

    def _extract_sector_signals(self, reports: Dict[str, Dict]) -> List[TradingSignal]:
        """Extract sector rotation signals"""
        signals = []
        sector_scores = {}
        macro_report = reports.get('macro_cycle', {})
        if macro_report:
            implications = macro_report.get('investment_implications', {})
            for sector, weight in implications.items():
                sector_scores[sector] = sector_scores.get(sector, 0) + weight * self.agent_weights.get('macro_cycle', 0)
        geo_report = reports.get('geopolitical', {})
        if geo_report:
            sector_rotation = geo_report.get('investment_implications', {}).get('sector_rotation', {})
            for sector, recommendation in sector_rotation.items():
                weight = 0.2 if recommendation == 'overweight' else -0.2 if recommendation == 'underweight' else 0
                sector_scores[sector] = sector_scores.get(sector, 0) + weight * self.agent_weights.get('geopolitical', 0)
        for sector, score in sector_scores.items():
            if abs(score) > 0.1:
                direction = 'long' if score > 0 else 'short'
                conviction = min(abs(score) * 2, 1.0)
                signals.append(TradingSignal(timestamp=datetime.now(), asset_class=sector, direction=direction, conviction=conviction, position_size=min(conviction * 0.15, 0.1), time_horizon='medium', risk_factors=['sector_rotation'], supporting_agents=['macro_cycle', 'geopolitical'], market_regime='sector_rotation'))
        return signals

    def _extract_currency_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
        """Extract currency trading signal"""
        fed_report = reports.get('central_bank', {})
        geo_report = reports.get('geopolitical', {})
        if not fed_report:
            return None
        policy_stance = fed_report.get('fed_analysis', {}).get('policy_stance', 'neutral')
        if policy_stance == 'hawkish':
            direction = 'long'
            conviction = 0.6
        elif policy_stance == 'dovish':
            direction = 'short'
            conviction = 0.5
        else:
            return None
        if geo_report:
            defensive_score = geo_report.get('investment_implications', {}).get('defensive_positioning', 0)
            if defensive_score > 0.5:
                direction = 'long'
                conviction = min(conviction + defensive_score * 0.3, 1.0)
        return TradingSignal(timestamp=datetime.now(), asset_class='USD', direction=direction, conviction=conviction, position_size=0.2, time_horizon='short', risk_factors=['policy_divergence', 'geopolitical_events'], supporting_agents=['central_bank', 'geopolitical'], market_regime=f'currency_{policy_stance}')

    def _extract_risk_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
        """Extract overall risk-on/risk-off signal"""
        risk_factors = []
        risk_score = 0.0
        for agent_name, report in reports.items():
            agent_weight = self.agent_weights.get(agent_name, 0)
            if agent_name == 'geopolitical':
                geo_risk = report.get('global_risk_assessment', {}).get('overall_risk_level', 5)
                risk_score += (geo_risk - 5) / 5 * agent_weight
            elif agent_name == 'sentiment':
                sentiment_score = report.get('sentiment_analysis', {}).get('overall_sentiment', 0)
                risk_score += sentiment_score * agent_weight
            elif agent_name == 'institutional_flow':
                flow_signal = report.get('flow_analysis', {}).get('risk_sentiment', 0)
                risk_score += flow_signal * agent_weight
        if abs(risk_score) > 0.2:
            if risk_score > 0:
                asset_class = 'risk_assets'
                direction = 'long'
            else:
                asset_class = 'safe_havens'
                direction = 'long'
            conviction = min(abs(risk_score), 1.0)
            return TradingSignal(timestamp=datetime.now(), asset_class=asset_class, direction=direction, conviction=conviction, position_size=conviction * 0.3, time_horizon='short', risk_factors=risk_factors, supporting_agents=list(reports.keys()), market_regime='risk_on' if risk_score > 0 else 'risk_off')
        return None

    def generate_portfolio_recommendation(self, signals: List[TradingSignal], current_portfolio: Dict) -> PortfolioRecommendation:
        """Generate comprehensive portfolio recommendation"""
        asset_allocation = {'equities': 0.6, 'bonds': 0.3, 'commodities': 0.05, 'cash': 0.05}
        sector_weights = {}
        regional_weights = CONFIG.regional_weights.copy()
        hedges = []
        for signal in signals:
            validated = self.risk_manager.validate_signal(signal, current_portfolio)
            if validated:
                if signal.asset_class in asset_allocation:
                    adjustment = signal.position_size * (1 if signal.direction == 'long' else -1)
                    asset_allocation[signal.asset_class] += adjustment
                elif signal.asset_class in ['risk_assets', 'safe_havens']:
                    if signal.asset_class == 'risk_assets' and signal.direction == 'long':
                        asset_allocation['equities'] += signal.position_size * 0.5
                        asset_allocation['bonds'] -= signal.position_size * 0.3
                    elif signal.asset_class == 'safe_havens' and signal.direction == 'long':
                        asset_allocation['bonds'] += signal.position_size * 0.4
                        asset_allocation['cash'] += signal.position_size * 0.2
                        asset_allocation['equities'] -= signal.position_size * 0.4
                if signal.asset_class not in ['USD', 'risk_assets', 'safe_havens']:
                    sector_weights[signal.asset_class] = signal.position_size * (1 if signal.direction == 'long' else -1)
                hedges.extend(signal.risk_factors)
        total_allocation = sum(asset_allocation.values())
        if total_allocation != 1.0:
            for asset in asset_allocation:
                asset_allocation[asset] /= total_allocation
        risk_budget = {}
        for signal in signals:
            risk_budget[signal.asset_class] = signal.conviction * signal.position_size
        return PortfolioRecommendation(timestamp=datetime.now(), asset_allocation=asset_allocation, sector_weights=sector_weights, regional_weights=regional_weights, risk_budget=risk_budget, hedges=list(set(hedges)), cash_allocation=asset_allocation.get('cash', 0.05), leverage=1.0)

def _extract_macro_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
    """Extract macro asset allocation signal"""
    macro_report = reports.get('macro_cycle', {})
    fed_report = reports.get('central_bank', {})
    if not macro_report or not fed_report:
        return None
    cycle_phase = macro_report.get('cycle_analysis', {}).get('current_phase', 'expansion')
    policy_stance = fed_report.get('fed_analysis', {}).get('policy_stance', 'neutral')
    if cycle_phase == 'expansion' and policy_stance in ['neutral', 'dovish']:
        direction = 'long'
        asset_class = 'equities'
        conviction = 0.7
    elif cycle_phase == 'contraction' or policy_stance == 'hawkish':
        direction = 'long'
        asset_class = 'bonds'
        conviction = 0.6
    elif cycle_phase == 'peak':
        direction = 'short'
        asset_class = 'equities'
        conviction = 0.5
    else:
        return None
    supporting_agents = ['macro_cycle', 'central_bank']
    return TradingSignal(timestamp=datetime.now(), asset_class=asset_class, direction=direction, conviction=conviction, position_size=0.4, time_horizon='medium', risk_factors=['cycle_timing', 'policy_error'], supporting_agents=supporting_agents, market_regime=f'{cycle_phase}_{policy_stance}')

def _extract_sector_signals(self, reports: Dict[str, Dict]) -> List[TradingSignal]:
    """Extract sector rotation signals"""
    signals = []
    sector_scores = {}
    macro_report = reports.get('macro_cycle', {})
    if macro_report:
        implications = macro_report.get('investment_implications', {})
        for sector, weight in implications.items():
            sector_scores[sector] = sector_scores.get(sector, 0) + weight * self.agent_weights.get('macro_cycle', 0)
    geo_report = reports.get('geopolitical', {})
    if geo_report:
        sector_rotation = geo_report.get('investment_implications', {}).get('sector_rotation', {})
        for sector, recommendation in sector_rotation.items():
            weight = 0.2 if recommendation == 'overweight' else -0.2 if recommendation == 'underweight' else 0
            sector_scores[sector] = sector_scores.get(sector, 0) + weight * self.agent_weights.get('geopolitical', 0)
    for sector, score in sector_scores.items():
        if abs(score) > 0.1:
            direction = 'long' if score > 0 else 'short'
            conviction = min(abs(score) * 2, 1.0)
            signals.append(TradingSignal(timestamp=datetime.now(), asset_class=sector, direction=direction, conviction=conviction, position_size=min(conviction * 0.15, 0.1), time_horizon='medium', risk_factors=['sector_rotation'], supporting_agents=['macro_cycle', 'geopolitical'], market_regime='sector_rotation'))
    return signals

def _extract_currency_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
    """Extract currency trading signal"""
    fed_report = reports.get('central_bank', {})
    geo_report = reports.get('geopolitical', {})
    if not fed_report:
        return None
    policy_stance = fed_report.get('fed_analysis', {}).get('policy_stance', 'neutral')
    if policy_stance == 'hawkish':
        direction = 'long'
        conviction = 0.6
    elif policy_stance == 'dovish':
        direction = 'short'
        conviction = 0.5
    else:
        return None
    if geo_report:
        defensive_score = geo_report.get('investment_implications', {}).get('defensive_positioning', 0)
        if defensive_score > 0.5:
            direction = 'long'
            conviction = min(conviction + defensive_score * 0.3, 1.0)
    return TradingSignal(timestamp=datetime.now(), asset_class='USD', direction=direction, conviction=conviction, position_size=0.2, time_horizon='short', risk_factors=['policy_divergence', 'geopolitical_events'], supporting_agents=['central_bank', 'geopolitical'], market_regime=f'currency_{policy_stance}')

def _extract_risk_signal(self, reports: Dict[str, Dict]) -> Optional[TradingSignal]:
    """Extract overall risk-on/risk-off signal"""
    risk_factors = []
    risk_score = 0.0
    for agent_name, report in reports.items():
        agent_weight = self.agent_weights.get(agent_name, 0)
        if agent_name == 'geopolitical':
            geo_risk = report.get('global_risk_assessment', {}).get('overall_risk_level', 5)
            risk_score += (geo_risk - 5) / 5 * agent_weight
        elif agent_name == 'sentiment':
            sentiment_score = report.get('sentiment_analysis', {}).get('overall_sentiment', 0)
            risk_score += sentiment_score * agent_weight
        elif agent_name == 'institutional_flow':
            flow_signal = report.get('flow_analysis', {}).get('risk_sentiment', 0)
            risk_score += flow_signal * agent_weight
    if abs(risk_score) > 0.2:
        if risk_score > 0:
            asset_class = 'risk_assets'
            direction = 'long'
        else:
            asset_class = 'safe_havens'
            direction = 'long'
        conviction = min(abs(risk_score), 1.0)
        return TradingSignal(timestamp=datetime.now(), asset_class=asset_class, direction=direction, conviction=conviction, position_size=conviction * 0.3, time_horizon='short', risk_factors=risk_factors, supporting_agents=list(reports.keys()), market_regime='risk_on' if risk_score > 0 else 'risk_off')
    return None

class HedgeFundOrchestrator:
    """Main orchestrator for the AI hedge fund system"""

    def __init__(self):
        self.data_manager = DataFeedManager()
        self.decision_engine = DecisionEngine()
        self.risk_manager = RiskManager()
        self.agents = {'macro_cycle': MacroCycleAgent(), 'central_bank': CentralBankAgent(), 'geopolitical': GeopoliticalAgent(), 'regulatory': RegulatoryAgent(), 'sentiment': SentimentAgent(), 'institutional_flow': InstitutionalFlowAgent(), 'supply_chain': SupplyChainAgent(), 'innovation': InnovationAgent(), 'currency': CurrencyAgent(), 'behavioral': BehavioralAgent()}
        self.current_portfolio = {'positions': {}, 'sectors': {}, 'risk_budget': {}, 'last_rebalance': datetime.now()}
        self.is_running = False
        self.update_interval = CONFIG.agent.update_frequency
        self._setup_logging()

    def _setup_logging(self):
        """Setup comprehensive logging"""
        logging.basicConfig(level=CONFIG.log_level, format=CONFIG.log_format, handlers=[logging.FileHandler(CONFIG.logs_dir / f'hedge_fund_{datetime.now().strftime('%Y%m%d')}.log'), logging.StreamHandler(sys.stdout)])
        self.logger = logging.getLogger('HedgeFundOrchestrator')
        self.trade_logger = logging.getLogger('TradingSignals')
        self.risk_logger = logging.getLogger('RiskManagement')

    async def run_analysis_cycle(self) -> Dict[str, Any]:
        """Run one complete analysis cycle"""
        cycle_start = time.time()
        self.logger.info('Starting analysis cycle')
        try:
            agent_reports = await self._run_all_agents()
            signals = self.decision_engine.aggregate_signals(agent_reports)
            portfolio_rec = self.decision_engine.generate_portfolio_recommendation(signals, self.current_portfolio)
            execution_results = await self._execute_trades(signals, portfolio_rec)
            self._update_portfolio_state(execution_results, portfolio_rec)
            cycle_time = time.time() - cycle_start
            self.logger.info(f'Analysis cycle completed in {cycle_time:.2f} seconds')
            return {'timestamp': datetime.now().isoformat(), 'cycle_time': cycle_time, 'agent_reports': agent_reports, 'trading_signals': [self._signal_to_dict(s) for s in signals], 'portfolio_recommendation': self._portfolio_to_dict(portfolio_rec), 'execution_results': execution_results, 'current_portfolio': self.current_portfolio}
        except Exception as e:
            self.logger.error(f'Error in analysis cycle: {e}')
            return {'error': str(e), 'timestamp': datetime.now().isoformat()}

    async def _run_all_agents(self) -> Dict[str, Dict]:
        """Run all agents concurrently"""
        self.logger.info('Running agent analysis')

        async def run_agent(name: str, agent):
            try:
                if hasattr(agent, 'get_cycle_report'):
                    return await agent.get_cycle_report()
                elif hasattr(agent, 'get_policy_report'):
                    return await agent.get_policy_report()
                elif hasattr(agent, 'get_geopolitical_report'):
                    return await agent.get_geopolitical_report()
                else:
                    return await agent.generate_report()
            except Exception as e:
                self.logger.error(f'Error running agent {name}: {e}')
                return {'error': str(e), 'agent': name}
        tasks = [run_agent(name, agent) for name, agent in self.agents.items()]
        results = await asyncio.gather(*tasks, return_exceptions=True)
        agent_reports = {}
        for i, (name, agent) in enumerate(self.agents.items()):
            if i < len(results) and (not isinstance(results[i], Exception)):
                agent_reports[name] = results[i]
            else:
                self.logger.error(f'Agent {name} failed: {(results[i] if i < len(results) else 'Unknown error')}')
                agent_reports[name] = {'error': 'Agent failed', 'agent': name}
        return agent_reports

    async def _execute_trades(self, signals: List[TradingSignal], portfolio_rec: PortfolioRecommendation) -> Dict[str, Any]:
        """Execute trading signals (simulated)"""
        self.trade_logger.info(f'Executing {len(signals)} trading signals')
        executed_trades = []
        total_trading_cost = 0.0
        for signal in signals:
            if not self.risk_manager.validate_signal(signal, self.current_portfolio):
                self.trade_logger.warning(f'Signal rejected by risk manager: {signal.asset_class}')
                continue
            market_volatility = self._estimate_market_volatility(signal.asset_class)
            position_size = self.risk_manager.size_position(signal, market_volatility)
            execution_price = self._get_execution_price(signal.asset_class)
            trading_cost = position_size * CONFIG.trading.commission_rate
            slippage_cost = position_size * CONFIG.trading.slippage_assumption
            executed_trade = {'timestamp': datetime.now().isoformat(), 'asset_class': signal.asset_class, 'direction': signal.direction, 'position_size': position_size, 'execution_price': execution_price, 'trading_cost': trading_cost, 'slippage_cost': slippage_cost, 'signal_conviction': signal.conviction}
            executed_trades.append(executed_trade)
            total_trading_cost += trading_cost + slippage_cost
            self.trade_logger.info(f'Executed: {signal.direction} {position_size:.3f} {signal.asset_class}')
        return {'executed_trades': executed_trades, 'total_trades': len(executed_trades), 'total_trading_cost': total_trading_cost, 'rejected_signals': len(signals) - len(executed_trades)}

    def _estimate_market_volatility(self, asset_class: str) -> float:
        """Estimate market volatility for asset class"""
        volatility_map = {'equities': 0.16, 'bonds': 0.08, 'commodities': 0.25, 'USD': 0.12, 'technology': 0.22, 'energy': 0.3, 'financials': 0.18}
        return volatility_map.get(asset_class, 0.15)

    def _get_execution_price(self, asset_class: str) -> float:
        """Get simulated execution price"""
        base_prices = {'equities': 100.0, 'bonds': 98.5, 'commodities': 85.2, 'USD': 1.0, 'technology': 105.3, 'energy': 92.1}
        base_price = base_prices.get(asset_class, 100.0)
        return base_price * (1 + np.random.normal(0, 0.002))

    def _update_portfolio_state(self, execution_results: Dict, portfolio_rec: PortfolioRecommendation):
        """Update current portfolio state"""
        for trade in execution_results.get('executed_trades', []):
            asset_class = trade['asset_class']
            position_change = trade['position_size'] * (1 if trade['direction'] == 'long' else -1)
            self.current_portfolio['positions'][asset_class] = self.current_portfolio['positions'].get(asset_class, 0) + position_change
        self.current_portfolio['sectors'] = portfolio_rec.sector_weights
        self.current_portfolio['risk_budget'] = portfolio_rec.risk_budget
        self.current_portfolio['last_rebalance'] = datetime.now()
        self.logger.info('Portfolio state updated')

    def _signal_to_dict(self, signal: TradingSignal) -> Dict:
        """Convert trading signal to dictionary"""
        return {'timestamp': signal.timestamp.isoformat(), 'asset_class': signal.asset_class, 'direction': signal.direction, 'conviction': signal.conviction, 'position_size': signal.position_size, 'time_horizon': signal.time_horizon, 'risk_factors': signal.risk_factors, 'supporting_agents': signal.supporting_agents, 'market_regime': signal.market_regime}

    def _portfolio_to_dict(self, portfolio: PortfolioRecommendation) -> Dict:
        """Convert portfolio recommendation to dictionary"""
        return {'timestamp': portfolio.timestamp.isoformat(), 'asset_allocation': portfolio.asset_allocation, 'sector_weights': portfolio.sector_weights, 'regional_weights': portfolio.regional_weights, 'risk_budget': portfolio.risk_budget, 'hedges': portfolio.hedges, 'cash_allocation': portfolio.cash_allocation, 'leverage': portfolio.leverage}

    async def start_continuous_operation(self):
        """Start continuous hedge fund operation"""
        self.is_running = True
        self.logger.info('Starting continuous hedge fund operation')
        try:
            while self.is_running:
                cycle_results = await self.run_analysis_cycle()
                await self._save_cycle_results(cycle_results)
                await asyncio.sleep(self.update_interval)
        except KeyboardInterrupt:
            self.logger.info('Received shutdown signal')
        except Exception as e:
            self.logger.error(f'Error in continuous operation: {e}')
        finally:
            self.is_running = False
            self.logger.info('Hedge fund operation stopped')

    async def _save_cycle_results(self, results: Dict):
        """Save cycle results for analysis"""
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        filename = CONFIG.data_dir / f'cycle_results_{timestamp}.json'
        try:
            with open(filename, 'w') as f:
                json.dump(results, f, indent=2, default=str)
        except Exception as e:
            self.logger.error(f'Error saving results: {e}')

    def stop(self):
        """Stop the hedge fund operation"""
        self.is_running = False
        self.logger.info('Stopping hedge fund operation')

    async def get_status(self) -> Dict[str, Any]:
        """Get current system status"""
        return {'timestamp': datetime.now().isoformat(), 'is_running': self.is_running, 'agents_count': len(self.agents), 'current_portfolio': self.current_portfolio, 'last_update': self.current_portfolio.get('last_rebalance', datetime.now()).isoformat(), 'system_health': await self._check_system_health()}

    async def _check_system_health(self) -> Dict[str, str]:
        """Check system health status"""
        health = {}
        try:
            data_summary = self.data_manager.get_latest_data_summary()
            health['data_feeds'] = 'healthy'
        except Exception:
            health['data_feeds'] = 'degraded'
        healthy_agents = sum((1 for agent in self.agents.values() if hasattr(agent, 'name')))
        health['agents'] = 'healthy' if healthy_agents == len(self.agents) else 'degraded'
        try:
            CONFIG.validate_config()
            health['configuration'] = 'healthy'
        except Exception:
            health['configuration'] = 'error'
        return health

def _estimate_market_volatility(self, asset_class: str) -> float:
    """Estimate market volatility for asset class"""
    volatility_map = {'equities': 0.16, 'bonds': 0.08, 'commodities': 0.25, 'USD': 0.12, 'technology': 0.22, 'energy': 0.3, 'financials': 0.18}
